window.COURSE = {"title":"B1 revised scripts — six lessons (English)","version":"3.2.0-b12-reviewed-2026-10-07","documents":{"DOC-REQ":{"title":"NDT request (teaching sample)","pages":1,"fields":["Request / job reference (fictional: TS-V2)","Planned examination (day only, no calendar date)","Site / contact role (client's maintenance manager — Bram)","Component / drawing and weld IDs (vessel V-2; welds W-07, W-08; drawing V2-GA rev C)","Material (carbon steel)","Thickness / dimensions (12 mm / 1 200 mm — fictional sample values)","Examination extent (100 % of both welds)","NDT method (RT)","Examination technique standard (ISO 17636-2:2022, digital detectors)","Acceptance criteria (ISO 10675-1:2021; level per fictional project specification PS-V2 §6.5)","Attachments","Responsibility / confirmation (role only, no signature)"],"rules":"No default-standard fallback; method standard, acceptance criteria and legal justification are separate fields."},"DOC-TECH-JUST":{"title":"Justification of the technique (teaching sample)","pages":1,"fields":["Job / type of assignment (vessel V-2 shell welds, repair)","3a — Standard issued by a recognised standardisation organisation requiring radiography for this type of assignment: 'none identified'","3b — Contractual / project requirement: fictional PS-V2 rev C §6.3 'All circumferential butt welds in pressure-retaining shell plates shall be examined by radiographic testing over 100 % of their length.' (fictional teaching document — not a standard)","3c — Risk analysis of undetected fabrication defects: attached; RT selected for these welds (summary only, no values)","Prepared by (role: client's welding/NDT engineer — competent in NDT techniques)","Attachments"],"rules":"The selected legal route is 3c (KB IR art 3 §2); 3b alone never suffices; nothing is quoted from a real standard."},"DOC-LOC-JUST":{"title":"Justification of the irradiation location (teaching sample)","pages":1,"fields":["Workpiece / context (installed vessel on saddles; not movable)","Bunker — assessed: dismantling and transport for two repair welds assessed and rejected (reasons recorded) → not reasonably feasible","Irradiation infrastructure — none present; arranging fixed shielding around the vessel for these welds assessed (access on three sides only, crane traffic, duration) → not reasonably feasible","Conclusion for this type of assignment: another place (the hall), after risk analyses by client and company","Client's risk-analysis information for the company (hall occupancy, walkways, store behind the hall, crane use)","Associated evidence / attachments"],"rules":"Immobility, absence of infrastructure or ownership alone are never the stated reason; no transitional flowchart branch."},"DOC-LICENCE":{"title":"Establishment and operating licence — teaching excerpt","pages":2,"fields":["Authorised establishment / practice (industrial radiography in the company bunker and on clients' sites)","Installations covered","Equipment scope / inventory (placeholders, no numeric inventory)","Sources (placeholders)","Conditions","Evidence fields (acceptance, security acceptance where applicable)"],"rules":"Placeholders instead of real reference numbers; not blanket evidence that a job, site or person is ready."},"DOC-CERT-BUNKER":{"title":"Bunker conformity certificate — teaching excerpt","pages":1,"fields":["Description of the bunker and its location on the site","Permitted isotopes / maximum activity; maximum X-ray voltage and current (placeholders)","Permitted working configurations","Safety-logic reference (document with electrical diagram — referenced, not shown)","Validity (maximum 10 years)","Drawn up by: recognised expert in physical control (role only)"],"rules":"No stamp, signature, number or shielding dimension; this example has a roof; no universal roof rule."},"DOC-EXT-WORKER-FILE":{"title":"Pre-assignment information — external worker (teaching sample)","pages":2,"fields":["Page 1 — Sending employer: name / establishment unit / enterprise number (placeholders)","Page 1 — Worker: first name Clara; other identity fields as placeholders","Page 2 — Doses, last five calendar years, per year: 'provided' ×5","Page 2 — Doses, last twelve rolling months with monitoring period: 'NOT PROVIDED'","Page 2 — Non-uniform exposure / internal contamination: none declared","Page 2 — Assignment abroad: not applicable","Instruction / assignment scope (added by the operator): bunker and bunker X-ray set"],"rules":"'provided' / 'not provided' / placeholders only; a missing section is an evidence gap, not zero dose."},"DOC-AGREEMENT":{"title":"Signed agreement — external undertaking and operator (teaching sample)","pages":1,"fields":["Parties (roles only)","Clause A — Individual dosimetric monitoring and transfer of results to the exposure register: external undertaking","Clause B — Personal protective equipment: external undertaking","Clause C — Specific training on the controlled area and task: operator (not allocated)","Signature area: illustrative placeholders, no names"],"rules":"Allocates only what it names."},"DOC-CHECK-SHEET":{"title":"Pre-use check sheet — current version (teaching sample)","pages":1,"fields":["Instrument / device","Function check result","Date","Checked by (role)","Ambiguous sentence: 'Check the meter's response before/after positioning the device' (the sentence Daniel proposes to clarify)"],"rules":"The proposed revision sits beside it marked PROPOSED — not approved."},"DOC-CERT-AGENT":{"title":"Agent-course certificate (teaching sample)","pages":1,"fields":["Holder: Daniel","Theoretical training — knowledge test passed","Training body (placeholder)","Date (placeholder)"],"rules":"Proves the passed knowledge test only."},"DOC-PLANNING":{"title":"Worksite planning sheet (teaching sample)","pages":1,"fields":["Worksite / day","Team","Designated radiation protection agent (line)","Equipment","Client contact person"],"rules":"Designation is a recorded company decision."},"DOC-CONTROL-TEST-PROGRAMME":{"title":"Control and test programme — bunker safety devices (teaching sample)","pages":1,"fields":["Device: door interlock","Columns: Result · Date · Tested by","Previous month: satisfactory · date · name (placeholders)","This month: — · — · — (empty)"],"rules":"Result, date and operator name as KB IR art 15 §4 requires."},"DOC-HOLD-CARD":{"title":"Hold card (teaching sample)","pages":1,"fields":["BUNKER USE ON HOLD","Reason: this month's interlock test result not established","Placed by (role) / informed (roles)"],"rules":"The visible held-work state; not tiny status text."},"DOC-CHANGE-REGISTER":{"title":"Change register of the physical control service (teaching sample)","pages":1,"fields":["Change description (additional X-ray set, type not in licence inventory)","Approvals given / still needed (expert countersignature; Agency decision)","Implementation status (proposal)"],"rules":"Per TR 6 Dec 2021 art 10; not every change shares one signature route."},"DOC-EVENT-RECORD":{"title":"Event account / handover record (teaching sample)","pages":1,"fields":["Observation (time, place, equipment, what happened)","Work / protective status","Contacted — and whether contact succeeded","Unknowns (cause; dose)"],"rules":"Unknowns are never converted into a cause, a dose or a permission."},"DOC-NOTIFICATION":{"title":"Written notification to the Agency — teaching sample (initial)","pages":1,"fields":["What / where / when; when discovered","Equipment and sources involved","Actual consequences incl. doses where known — 'dose under assessment'","Suspected causes (labelled suspected)","Urgent measures taken","Who manages the event","Physician follow-up / proposed INES level where applicable","Notifier (role)"],"rules":"Facts known at that moment; no zero for an unknown."},"DOC-CRITERION-EXTRACT":{"title":"Criterion extract — significant events (teaching card)","pages":1,"fields":["Criterion 1.5 — loss or failure of equipment fulfilling a safety function: direct contact by the next working day; INES evaluation yes","Criterion 1.4 — non-compliance with / unsuitable safety logic leading or possibly leading to unforeseen behaviour: direct contact immediately; INES evaluation yes","Written notification within 48 h for every event meeting a criterion","Source and date of the extract"],"rules":"Learning card; the procedure holds the complete current table."},"DOC-ASSIGNMENT-SLIP":{"title":"Changed assignment slip (teaching sample)","pages":1,"fields":["Worker: Clara","Requested: assist with gamma exposures, hall two, this afternoon","Requested by (role)"],"rules":"Shown beside the instruction record."},"DOC-INSTRUCTION-RECORD":{"title":"Specific instruction record — Clara (teaching sample)","pages":1,"fields":["Area: company bunker","Equipment: bunker X-ray set","Task: X-ray radiography of castings","Given by (role) / date (placeholder)"],"rules":"Scope is the evidence; a different area/equipment/task is outside it."},"DOC-PLANNER":{"title":"Job planner — week view (teaching sample)","pages":1,"fields":["Tuesday: client request received; written justifications received","Wednesday: company risk analysis completed; planning","Thursday (current day): worksite — vessel V-2, welds W-07/W-08"],"rules":"Current day clearly marked; plays automatically, not an exercise."},"DOC-SITE-PLAN":{"title":"Site drawing — client's hall (teaching sample)","pages":1,"fields":["Vessel V-2 position","Protection perimeter line (conceptual; no distances)","Walkway route (agreed) and changed route","Store behind the hall","Gate","Supervision positions"],"rules":"Conceptual planning drawing; no exclusion distances or dose values."},"DOC-FINAL-REPORT":{"title":"Final report — teaching sample (structure only)","pages":1,"fields":["Established causes","Doses","Detailed description","Preventive measures / lessons learned / action plan","Approvals where applicable (recognised expert; class 7 safety adviser)"],"rules":"Structure only; no content invented for the case."},"DOC-REG-EXTRACT":{"title":"Regulation extract page (teaching reader)","pages":1,"fields":["Article reference and short verbatim extract (Dutch) with English gloss"],"rules":"Used in the B1.1 exploration and reference readers."},"DOC-PROCEDURE-RECORD":{"title":"Approved procedure page with its approval line, and a record line (teaching sample)","pages":1,"fields":["Procedure title and version","Approved by: recognised expert (role)","Record line: what was checked · result · date · by whom"],"rules":"Procedure = method; record = evidence of a check on a day."}},"lessons":[{"id":"B1.1","title":"Getting started: radiation protection in Belgian industry","scenes":[{"id":"S01","title":"Welcome to the course","paragraphs":[{"cue":"B1.1-S01-P1","speaker":"Emilia","text":"Welcome to your radiation protection training. I'm Emilia, and I'll be your guide. Your own health, and the safety of the people around you, are at the heart of this course. By the end of it you will recognise where radiation risks arise in industrial work, know which responsibilities and checks apply before a job starts, and know when to stop and ask for help. We build that step by step, with examples from Belgian industry, and three principles will return in every example: justification, optimisation and dose limitation.","screen_text":[],"start_visual":"Approved Emilia beside the original cream, teal and gold illustration: trefoil connected to a balance, exposure-reduction shield and bounded dial. All visible from the start; no workplace photo.","beats":[{"at":"Welcome to your radiation protection training.","show":"Reviewed explanation, focus 1"},{"at":"I'm Emilia, and I'll be your guide.","show":"Reviewed explanation, focus 2"},{"at":"By the end of it you will recognise where radiation risks ar","show":"Reviewed explanation, focus 3"},{"at":"We build that step by step, with examples from Belgian indus","show":"Reviewed explanation, focus 4"}],"equipment":[],"characters":["Emilia"],"clip":"B1.1-S01-P1"},{"cue":"B1.1-S01-P2","speaker":"Emilia","text":"I work for an industrial radiography company, and that is the company we'll follow in this course. There, I lead the physical control service: the organised radiation-protection function of the company, the people, the checks and the procedures that keep exposure under control. You will meet my colleagues as they work: Daniel preparing an inspection, Clara arriving with her file, and Bram arranging a job at his site. Through their decisions we connect the Belgian rules with the information and the equipment in front of us.","screen_text":[],"start_visual":"Emilia introduces herself beside the principles illustration, with her name and role. No other participant is shown until named.","beats":[{"at":"I work for an industrial radiography company, and that is th","show":"Reviewed explanation, focus 1"},{"at":"There, I lead the physical control service: the organised ra","show":"Reviewed explanation, focus 2"},{"at":"You will meet my colleagues as they work: Daniel preparing a","show":"Reviewed explanation, focus 3"},{"at":"Through their decisions we connect the Belgian rules with th","show":"Reviewed explanation, focus 4"}],"documents":["DOC-REQ"],"characters":["Emilia","Daniel","Clara","Bram"],"clip":"B1.1-S01-P2"},{"cue":"B1.1-S01-P3","speaker":"Emilia","text":"We start with the framework and the people: who is responsible for what, and why protection has to be settled before work begins. Later lessons build the physics and apply it to more detailed situations. Take the course at your own pace: pause, replay an explanation, and keep your own notes. The practice questions along the way help you understand the decisions; they are not scored, and the final assessment is separate.","screen_text":[],"start_visual":"A clean three-stop course route appears beside Emilia; stop 1 active.","beats":[{"at":"We start with the framework and the people: who is responsib","show":"Reviewed explanation, focus 1"},{"at":"Later lessons build the physics and apply it to more detaile","show":"Reviewed explanation, focus 2"},{"at":"Take the course at your own pace: pause, replay an explanati","show":"Reviewed explanation, focus 3"},{"at":"The practice questions along the way help you understand the","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S01-P3"},{"cue":"B1.1-S01-P4","speaker":"Emilia","text":"Before we begin, let me be clear about what this course is and what it is not. It gives you the theory: the knowledge you need if you work with radioactive sources or X-ray generators in Belgian class II industry. What it cannot give you is the rest: hands-on experience, instruction on the actual installation you'll use, and the responsibilities your employer assigns to you. Those come from your workplace. So when you finish these lessons, you'll understand the decisions; being appointed to a function, or allowed to use a particular piece of equipment, is a separate step that your company takes.","screen_text":[],"start_visual":"Emilia to camera; route fades to the two labels.","beats":[{"at":"Before we begin, let me be clear about what this course is a","show":"Reviewed explanation, focus 1"},{"at":"It gives you the theory: the knowledge you need if you work ","show":"Reviewed explanation, focus 2"},{"at":"Those come from your workplace.","show":"Reviewed explanation, focus 3"},{"at":"So when you finish these lessons, you'll understand the deci","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S01-P4"}],"sequence":{"cues_before_interaction":["B1.1-S01-P1","B1.1-S01-P2","B1.1-S01-P3","B1.1-S01-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S02","title":"Where the course will take you","paragraphs":[{"cue":"B1.1-S02-P1","speaker":"Emilia","text":"Here is the road ahead, so you know where each lesson fits. The foundations come in three stages. The first stage is the one we're in now: the Belgian framework and the people who make it work. We start here, and not with the physics, for a simple reason: every protective measure you'll ever meet is a decision taken by someone with a responsibility, and you need to know who those people are before the rules make sense.","screen_text":[],"start_visual":"One continuous three-part course route, with Framework and people active and the Belgian-framework illustration and summary visible.","beats":[{"at":"Here is the road ahead, so you know where each lesson fits.","show":"Reviewed explanation, focus 1"},{"at":"The foundations come in three stages.","show":"Reviewed explanation, focus 2"},{"at":"The first stage is the one we're in now: the Belgian framewo","show":"Reviewed explanation, focus 3"},{"at":"We start here, and not with the physics, for a simple reason","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S02-P1"},{"cue":"B1.1-S02-P2","speaker":"Emilia","text":"The second stage is radiation itself: where it comes from, how it behaves, and what the different quantities actually measure. That is where words you already hear at work, dose, dose rate, activity, get their precise meaning. With those ideas in place, shielding, exposure, biological effects and personal dosimetry stop being separate topics and become one story: how radiation reaches a person, what it does, and how we keep it low.","screen_text":[],"start_visual":"Continue in part 2 without restarting the route. Show Instruments and safety checks.","beats":[{"at":"The second stage is radiation itself: where it comes from, h","show":"Reviewed explanation, focus 1"},{"at":"That is where words you already hear at work, dose, dose rat","show":"Reviewed explanation, focus 2"},{"at":"With those ideas in place, shielding, exposure, biological e","show":"Reviewed explanation, focus 3"}],"clip":"B1.1-S02-P2"},{"cue":"B1.1-S02-P3","speaker":"Emilia","text":"The third stage brings you to the equipment and the routines: the instruments you measure with, the safety checks you perform, and the way sources and contamination are handled day to day. From there, the class II modules take the foundations into more demanding situations: the authorised activity, equipment and safety systems, radioactive sources, more precise measurements, worksite arrangements and transport, and the response when something unusual happens. We won't ask you to solve all of that today; each module gives you something the next one can use.","screen_text":[],"start_visual":"Part 3 active from the first word; show the additional class II modules as applied knowledge.","beats":[{"at":"The third stage brings you to the equipment and the routines","show":"Reviewed explanation, focus 1"},{"at":"From there, the class II modules take the foundations into m","show":"Reviewed explanation, focus 2"},{"at":"We won't ask you to solve all of that today; each module giv","show":"Reviewed explanation, focus 3"}],"clip":"B1.1-S02-P3"},{"cue":"B1.1-S02-P4","speaker":"Emilia","text":"Each part of the course is taught by a colleague whose own work fits the subject, so you hear the physics from someone who measures, and the routines from someone who performs them. For this first module I stay with you from start to finish, so that we can build on our conversation from one lesson to the next, and so that the people you meet today, Daniel, Clara and Bram, are still the same people when the situations become harder.","screen_text":[],"start_visual":"A distinct four-part learning flow, not the course route again. Explanation, workplace example, decision and feedback stay visible.","beats":[{"at":"Each part of the course is taught by a colleague whose own w","show":"Reviewed explanation, focus 1"},{"at":"For this first module I stay with you from start to finish, ","show":"Reviewed explanation, focus 2"}],"clip":"B1.1-S02-P4"}],"sequence":{"cues_before_interaction":["B1.1-S02-P1","B1.1-S02-P2","B1.1-S02-P3","B1.1-S02-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S03","title":"Who protects whom? The Belgian system","paragraphs":[{"cue":"B1.1-S03-P1","speaker":"Emilia","text":"Let's begin with the people and organisations responsible for radiation protection in Belgium, starting from the outside. FANC is the Federal Agency for Nuclear Control: the public authority that regulates and supervises nuclear safety and radiation protection, with one purpose: to protect workers, the public and the environment from ionising radiation. For an industrial radiography company, FANC is the regulator. It grants the authorisations we need, it sets the rules, and through its inspections it checks that we comply. The protection itself is organised inside the company, by the people you'll meet next.","screen_text":[],"start_visual":"FANC name and official logo","beats":[{"at":"Let's begin with the people and organisations responsible fo","show":"Reviewed explanation, focus 1"},{"at":"FANC is the Federal Agency for Nuclear Control: the public a","show":"Reviewed explanation, focus 2"},{"at":"It grants the authorisations we need, it sets the rules, and","show":"Reviewed explanation, focus 3"},{"at":"The protection itself is organised inside the company, by th","show":"Reviewed explanation, focus 4"}],"equipment":["EQ-FANC-LOGO"],"characters":["Emilia"],"clip":"B1.1-S03-P1","documents":[]},{"cue":"B1.1-S03-P2","speaker":"Emilia","text":"Now step inside the company. Ours is an NDT company. NDT stands for non-destructive testing: we check whether a weld, a casting or a pipe is sound without cutting it open or damaging it. One way to do that is industrial radiography: we send X-rays or gamma rays through the part onto a detector, and the image shows cracks, voids or inclusions hidden inside the metal. That is why we work with X-ray generators and sealed radioactive sources, and why radiation protection is part of our daily work. A company that does this needs a licence for it. In the regulation the licence holder is called the operator, and the law places the responsibility for radiation protection squarely on the operator. To carry that responsibility, every operator must organise a physical control service, the service I introduced at the start. \"Physical\" here refers to the physics of radiation: the service controls exposure, from the equipment to the worksite. The health of the workers themselves is followed separately, through medical surveillance by a recognised physician.","screen_text":[],"start_visual":"Company frame highlighted; the word 'operator' appears on the frame.","beats":[{"at":"Now step inside the company.","show":"Reviewed explanation, focus 1"},{"at":"One way to do that is industrial radiography: we send X-rays","show":"Reviewed explanation, focus 2"},{"at":"In the regulation the licence holder is called the operator,","show":"Reviewed explanation, focus 3"},{"at":"The health of the workers themselves is followed separately,","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S03-P2"},{"cue":"B1.1-S03-P3","speaker":"Emilia","text":"This is where I fit in. I am the head of that service. I coordinate and organise its work, and I have direct access to the head of the company: if a responsibility is unclear, or an issue needs to reach management, the organisation has to let me take it there. Beside my function stands another one, the recognised expert in physical control, and in a moment you'll see why I keep the two apart.","screen_text":[],"start_visual":"Emilia steps into the service area of the scene (supplied pose: standing, open hand).","beats":[{"at":"This is where I fit in.","show":"Reviewed explanation, focus 1"},{"at":"I am the head of that service.","show":"Reviewed explanation, focus 2"},{"at":"I coordinate and organise its work, and I have direct access","show":"Reviewed explanation, focus 3"},{"at":"Beside my function stands another one, the recognised expert","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S03-P3"},{"cue":"B1.1-S03-P4","speaker":"Emilia","text":"The regulation reserves certain tasks for a recognised expert in physical control: a person who holds an individual recognition from FANC for a defined scope of work. Why an expert with a formal recognition? Because some judgements, whether a risk analysis is sound, whether a procedure gives enough protection, whether an installation may be put into service, must rest on expertise that the regulator has verified. A company may employ such an expert; ours does not. So, as the regulation requires, we have a contract with a recognised physical-control organisation: a specialist service provider, itself recognised by FANC, which carries out those expert tasks for us.","screen_text":[],"start_visual":"Company-to-organisation contract","beats":[{"at":"The regulation reserves certain tasks for a recognised exper","show":"Reviewed explanation, focus 1"},{"at":"Why an expert with a formal recognition?","show":"Reviewed explanation, focus 2"},{"at":"A company may employ such an expert; ours does not.","show":"Reviewed explanation, focus 3"},{"at":"So, as the regulation requires, we have a contract with a re","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S03-P4","characters":["Emilia"],"documents":[]},{"cue":"B1.1-S03-P5","speaker":"Emilia","clip":"B1.1-S03-P5","text":"Two things are easy to blend, so let me name them separately. The organisation is the service provider: it holds a recognition and keeps meeting its conditions. The expert is a person employed by it, with her own individual recognition. In our arrangement, that expert performs the reserved tasks for our company: she examines and approves our radiation-protection risk analysis and our working procedures, for example. I coordinate our service; she brings the formally recognised expertise; and both of us work under FANC's supervision.","start_visual":"Individual expert inside the recognised organisation","beats":[{"at":"Two things are easy to blend, so let me name them separately","show":"Reviewed explanation, focus 1"},{"at":"The organisation is the service provider: it holds a recogni","show":"Reviewed explanation, focus 2"},{"at":"In our arrangement, that expert performs the reserved tasks ","show":"Reviewed explanation, focus 3"},{"at":"I coordinate our service; she brings the formally recognised","show":"Reviewed explanation, focus 4"}],"screen_text":[],"characters":["Emilia"],"documents":[]},{"cue":"B1.1-S03-P6","speaker":"Emilia","clip":"B1.1-S03-P6","text":"What does that look like in practice? The expert comes to our company for periodic evaluation visits, to see how radiation protection and safety actually work, and not only how they are written down. Depending on the visit, she examines equipment and safety devices, reviews dosimetry results and staff training, and checks our procedures and working arrangements. In industrial radiography that can include our own premises and observations at a customer's worksite; the exact scope follows from our activities and from the visit itself. Her job, in one sentence, is to connect what our records say with what happens where people work.","start_visual":"Why visit: evaluate radiation protection in practice","beats":[{"at":"What does that look like in practice?","show":"Reviewed explanation, focus 1"},{"at":"The expert comes to our company for periodic evaluation visi","show":"Reviewed explanation, focus 2"},{"at":"In industrial radiography that can include our own premises ","show":"Reviewed explanation, focus 3"},{"at":"Her job, in one sentence, is to connect what our records say","show":"Reviewed explanation, focus 4"}],"screen_text":[],"characters":["Emilia"],"documents":[]},{"cue":"B1.1-S03-P7","speaker":"Emilia","clip":"B1.1-S03-P7","text":"After the visit, the company receives a written evaluation report. It records the findings and identifies the actions we have to take, each with a deadline. A report can grade how serious an issue is and show which actions are still open and which have been closed. The follow-up is mine to coordinate: we read the findings, carry out the required actions, and report back to the expert on what we have done. The organisation, in turn, has its own duties towards FANC. That is what gives the visit its weight: the expert's findings carry through into our records and, where needed, to the regulator.","start_visual":"Teaching report: findings, actions, deadlines and status","beats":[{"at":"After the visit, the company receives a written evaluation r","show":"Reviewed explanation, focus 1"},{"at":"A report can grade how serious an issue is and show which ac","show":"Reviewed explanation, focus 2"},{"at":"The follow-up is mine to coordinate: we read the findings, c","show":"Reviewed explanation, focus 3"},{"at":"That is what gives the visit its weight: the expert's findin","show":"Reviewed explanation, focus 4"}],"screen_text":[],"characters":["Emilia"],"documents":[]},{"cue":"B1.1-S03-P8","speaker":"Emilia","text":"Now the people in the field: the industrial radiographers, sometimes called RT technicians, who actually carry out the radiography. In industrial radiography their training is built in. Every radiographer follows the training for radiation protection agents early in their employment, and only a radiographer who has followed it may operate gamma or X-ray equipment. So every radiographer is trained as an agent: one group of people, with two names for two sides of their work.","screen_text":[],"start_visual":"Daniel in the hall area of the scene with his handheld instrument.","beats":[{"at":"Now the people in the field: the industrial radiographers, s","show":"Reviewed explanation, focus 1"},{"at":"In industrial radiography their training is built in.","show":"Reviewed explanation, focus 2"},{"at":"Every radiographer follows the training for radiation protec","show":"Reviewed explanation, focus 3"},{"at":"So every radiographer is trained as an agent: one group of p","show":"Reviewed explanation, focus 4"}],"equipment":["EQ-HANDHELD-SURVEY","EQ-EPD-LEFT-CHEST","EQ-TLD-RIGHT-UPPER-CHEST"],"characters":["Daniel"],"clip":"B1.1-S03-P8"},{"cue":"B1.1-S03-P9","speaker":"Emilia","text":"On a worksite, the company goes one step further. From the trained radiographers present who belong to our own staff, it designates one as the radiation protection agent for that worksite. For those tasks, the agent works under our service. His job is the frequent, systematic checking of everyday protection: that the protection rules and work procedures are being followed; that the protective equipment, the instruments and the dosimeters are available, working and used correctly; and that any abnormal situation reaches me and the recognised expert. He does those checks according to instructions and procedures that the recognised expert has approved, which is how the expert's judgement reaches the worksite without the expert standing there.","screen_text":[],"start_visual":"Planning sheet DOC-PLANNING close-up: the 'designated agent' line with Daniel's name for Thursday.","beats":[{"at":"On a worksite, the company goes one step further.","show":"Reviewed explanation, focus 1"},{"at":"From the trained radiographers present who belong to our own","show":"Reviewed explanation, focus 2"},{"at":"His job is the frequent, systematic checking of everyday pro","show":"Reviewed explanation, focus 3"},{"at":"He does those checks according to instructions and procedure","show":"Reviewed explanation, focus 4"}],"documents":["DOC-PLANNING","DOC-CHECK-SHEET","DOC-PROCEDURE-RECORD"],"clip":"B1.1-S03-P9"},{"cue":"B1.1-S03-P10","speaker":"Emilia","text":"Now connect the roles, and notice that they form a circle rather than a ladder. FANC regulates and supervises from outside. Our company organises radiation protection and remains responsible for it. I coordinate our service. The recognised organisation provides the recognised expert, who evaluates our protection and performs the examinations and approvals reserved for her. And on every worksite a designated agent checks and reports, under procedures the expert approved. The company keeps its responsibility alongside the expert's contract, and every radiographer keeps his own duties alongside the designated agent.","screen_text":[],"start_visual":"Regulator supervises","beats":[{"at":"Now connect the roles, and notice that they form a circle ra","show":"Reviewed explanation, focus 1"},{"at":"Our company organises radiation protection and remains respo","show":"Reviewed explanation, focus 2"},{"at":"The recognised organisation provides the recognised expert, ","show":"Reviewed explanation, focus 3"},{"at":"The company keeps its responsibility alongside the expert's ","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S03-P10","characters":["Emilia"],"documents":[]}],"sequence":{"cues_before_interaction":["B1.1-S03-P1","B1.1-S03-P2","B1.1-S03-P3","B1.1-S03-P4","B1.1-S03-P5","B1.1-S03-P6","B1.1-S03-P7","B1.1-S03-P8","B1.1-S03-P9","B1.1-S03-P10"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S04","title":"The expert's report lands on my desk","paragraphs":[{"cue":"B1.1-S04-P1","speaker":"Emilia","text":"The recognised expert visited us last week, and this morning her evaluation report is on my desk. One of her actions reads: the working procedure for setting up a worksite has to be revised, because it no longer matches the way our teams actually work. She has set a date by which she wants to see it done. Nothing dramatic: exactly the kind of finding a good visit produces.","screen_text":[],"start_visual":"Expert visit: assess protection in practice","beats":[{"at":"The recognised expert visited us last week, and this morning","show":"Reviewed explanation, focus 1"},{"at":"One of her actions reads: the working procedure for setting ","show":"Reviewed explanation, focus 2"},{"at":"She has set a date by which she wants to see it done.","show":"Reviewed explanation, focus 3"},{"at":"Nothing dramatic: exactly the kind of finding a good visit p","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S04-P1","characters":["Emilia"],"documents":[]},{"cue":"B1.1-S04-P2","speaker":"Emilia","text":"Within an hour I have heard three opinions. Our managing director: \"We pay that organisation, let them write it.\" Luc, our most experienced radiographer: \"I know how it should read; I'll change it this afternoon and the teams can start using it.\" And Daniel, new to all of this, asking me which of the two is right. Think about who is responsible, who drafts, who approves, and when a procedure may be used.","screen_text":[],"start_visual":"Daniel considers the purpose of the visit","beats":[{"at":"Within an hour I have heard three opinions.","show":"Reviewed explanation, focus 1"},{"at":"Our managing director: \"We pay that organisation, let them w","show":"Reviewed explanation, focus 2"},{"at":"Think about who is responsible, who drafts, who approves, an","show":"Reviewed explanation, focus 3"}],"documents":[],"equipment":["EQ-FANC-LOGO"],"clip":"B1.1-S04-P2","characters":["Emilia"]}],"interaction":{"id":"B1.1-S04-Q01","type":"single_choice","title_visible":"Who does what to close this action?","prompt_spoken_once":"Who does what to close this action properly?","situation_visible_text":"The expert's report asks us to revise the worksite set-up procedure by a set date. The director wants the organisation to write it. Luc wants to change it himself this afternoon.","options":[{"id":"a","text":"The recognised organisation writes the new procedure and issues it to the teams; that is the service we pay for.","correct":false,"feedback":{"spoken":"We do pay the organisation, and its expert will have a real part in this, just not the one the director has in mind. The procedure describes how our company works, and the responsibility for our protection stays with the company; so the drafting is ours, with the people who do the work. What the expert brings is the examination and the approval: she checks whether our revised procedure gives enough protection, and only after her approval do our agents work on the basis of it.","screen":"The company drafts the procedure; the expert examines and approves it; the company stays responsible."},"clip":"B1.1-S04-Q01-a"},{"id":"b","text":"Our company revises the procedure, the recognised expert examines and approves it, and only then do the teams work with the new version.","correct":true,"feedback":{"spoken":"Yes. I organise the revision with Luc and the teams, because they know how the work is actually done; that is the company carrying its responsibility. The draft goes to the expert, who examines and approves it, the task the regulation reserves for her. Until she has, the current approved version stays in use, and I report back to her before the deadline so that she can close the action. Three roles, one procedure, and everyone can say which part was theirs.","screen":"The company revises, the expert approves, the teams use the approved version. Until then the current version applies."},"clip":"B1.1-S04-Q01-b"},{"id":"c","text":"Luc revises the procedure today and the teams start using it; the expert reviews it at her next visit.","correct":false,"feedback":{"spoken":"Luc's experience is exactly what the revision needs, and his draft is where I would start. What the draft cannot do yet is govern the work: our agents carry out their checks on the basis of procedures the recognised expert has approved, and a revised text becomes such a procedure only when she has examined and approved it. So the teams keep using the current version, the draft goes to the expert now, and her approval, not her next visit, is what puts it into use.","screen":"A draft is not yet a procedure. The expert approves it first; then the teams use it."},"clip":"B1.1-S04-Q01-c"}],"clip":"B1.1-S04-Q01","reviewed_b11":true},"sequence":{"cues_before_interaction":["B1.1-S04-P1","B1.1-S04-P2"],"interaction_after_cue":"B1.1-S04-P2","interaction_id":"B1.1-S04-Q01","post_interaction_cues":[]}},{"id":"S05","title":"From Bram's email to a prepared request","paragraphs":[{"cue":"B1.1-S05-P1","speaker":"Emilia","text":"Let me take you to Havenmeer Process Works. Bram is the maintenance manager here; his company runs this workshop, owns the equipment and knows the site. Havenmeer is our client: it asks our company to inspect some welds, and it will have to give us the information only a client can give. Our planning desk prepares the assignment with Bram before any of our radiographers goes to work, and that preparation is where radiation protection begins.","screen_text":[],"start_visual":"Bram at Havenmeer workshop","beats":[{"at":"Let me take you to Havenmeer Process Works.","show":"Reviewed explanation, focus 1"},{"at":"Bram is the maintenance manager here; his company runs this ","show":"Reviewed explanation, focus 2"},{"at":"Havenmeer is our client: it asks our company to inspect some","show":"Reviewed explanation, focus 3"},{"at":"Our planning desk prepares the assignment with Bram before a","show":"Reviewed explanation, focus 4"}],"characters":["Emilia","Bram"],"clip":"B1.1-S05-P1"},{"cue":"B1.1-S05-P2","speaker":"Emilia","text":"This is the steel vessel Bram wants inspected. The two highlighted rings are welds: they join sections of the vessel wall, and each runs all the way around. On his drawing they are numbered seven and eight. The vessel is one point two metres across and its steel wall is twelve millimetres thick. It is fixed to its supports and connected to pipework, so it stays where it is, which already tells you something about where the radiography will have to happen. Bram will have to explain that later, when he justifies the location.","screen_text":[],"start_visual":"Both welds highlighted on the vessel","beats":[{"at":"This is the steel vessel Bram wants inspected.","show":"Reviewed explanation, focus 1"},{"at":"On his drawing they are numbered seven and eight.","show":"Reviewed explanation, focus 2"},{"at":"The vessel is one point two metres across and its steel wall","show":"Reviewed explanation, focus 3"},{"at":"Bram will have to explain that later, when he justifies the ","show":"Reviewed explanation, focus 4"}],"characters":["Emilia","Bram"],"clip":"B1.1-S05-P2"},{"cue":"B1.1-S05-P3","speaker":"Emilia","text":"The job starts with an email. Bram writes: could you radiograph two welds on our vessel on Thursday? Please let me know whether this fits your planning. That is a familiar first enquiry, and it opens a conversation. Planning now knows what Bram wants; what it needs next is everything that lets us prepare the inspection properly.","screen_text":[],"start_visual":"Original short enquiry email","beats":[{"at":"The job starts with an email.","show":"Reviewed explanation, focus 1"},{"at":"Bram writes: could you radiograph two welds on our vessel on","show":"Reviewed explanation, focus 2"},{"at":"That is a familiar first enquiry, and it opens a conversatio","show":"Reviewed explanation, focus 3"},{"at":"Planning now knows what Bram wants; what it needs next is ev","show":"Reviewed explanation, focus 4"}],"characters":["Emilia","Bram"],"clip":"B1.1-S05-P3"},{"cue":"B1.1-S05-P4","speaker":"Emilia","text":"So our planner replies with specific questions. Which welds, and how much of each weld must be examined? Please send a marked drawing, the material, the diameter and the wall thickness, and the examination requirements. We also need the exact location in the workshop, the proposed time, who else works nearby, and a contact person. To make that easy, planning sends Bram an inspection request form that puts those details in one place. Each line on it serves a purpose: the welds and the drawing tell us what to image, the material and thickness tell us how, and the location and the people nearby tell us whom we have to protect.","screen_text":[],"start_visual":"Planner asks for marked drawing and scope","beats":[{"at":"So our planner replies with specific questions.","show":"Reviewed explanation, focus 1"},{"at":"Please send a marked drawing, the material, the diameter and","show":"Reviewed explanation, focus 2"},{"at":"We also need the exact location in the workshop, the propose","show":"Reviewed explanation, focus 3"},{"at":"Each line on it serves a purpose: the welds and the drawing ","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"],"clip":"B1.1-S05-P4"},{"cue":"B1.1-S05-P5","speaker":"Emilia","text":"Bram completes the request and attaches his drawing. Now every row matches something real: weld seven and weld eight, both in carbon steel, with the same diameter and wall thickness. He asks for the full circumference of each weld to be examined. He names the workshop and puts himself down as the contact person, reachable throughout the work, so that there is always someone on his side who can answer, decide and reach his colleagues. The law asks the client for correct written job information at least twenty-four hours before the work. That day is for us: it is the time in which we plan the exposure, mark out the area we keep clear, and agree who watches it.","screen_text":[],"start_visual":"Bram returns request and marked drawing","beats":[{"at":"Bram completes the request and attaches his drawing.","show":"Reviewed explanation, focus 1"},{"at":"He asks for the full circumference of each weld to be examin","show":"Reviewed explanation, focus 2"},{"at":"He names the workshop and puts himself down as the contact p","show":"Reviewed explanation, focus 3"},{"at":"That day is for us: it is the time in which we plan the expo","show":"Reviewed explanation, focus 4"}],"characters":["Emilia","Bram"],"clip":"B1.1-S05-P5"},{"cue":"B1.1-S05-P6","speaker":"Emilia","text":"Planning also sends Bram a justification form. It asks for his reasons for requesting radiography, and for proposing this location, with the information that supports each reason. Bram gathers those answers with colleagues who have the technical knowledge, because the reasons have to hold up, in writing, for this type of job. We will read that justification in the next scenes; for now, notice who receives the form and why planning needs it back before we go further.","screen_text":[],"start_visual":"Planning sends justification form to client","beats":[{"at":"Planning also sends Bram a justification form.","show":"Reviewed explanation, focus 1"},{"at":"It asks for his reasons for requesting radiography, and for ","show":"Reviewed explanation, focus 2"},{"at":"Bram gathers those answers with colleagues who have the tech","show":"Reviewed explanation, focus 3"},{"at":"We will read that justification in the next scenes; for now,","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"],"clip":"B1.1-S05-P6"},{"cue":"B1.1-S05-P7","speaker":"Emilia","text":"There is a separate sheet as well: the task risk analysis, often called the TRA. Look at one issue in this workshop: a forklift route passes the vessel, and people use the nearby workbenches. Bram supplies that site information so that his company and ours can coordinate the precautions, and our company assesses the radiation risks on top of it. This sheet is about the hazards while the work is done. The justification form answers a different question, why radiography at all and what a missed defect would mean, and the two stay separate for that reason.","screen_text":[],"start_visual":"Separate TRA worksheet","beats":[{"at":"There is a separate sheet as well: the task risk analysis, o","show":"Reviewed explanation, focus 1"},{"at":"Look at one issue in this workshop: a forklift route passes ","show":"Reviewed explanation, focus 2"},{"at":"This sheet is about the hazards while the work is done.","show":"Reviewed explanation, focus 3"},{"at":"The justification form answers a different question, why rad","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"],"clip":"B1.1-S05-P7"},{"cue":"B1.1-S05-P8","speaker":"Emilia","text":"Bram returns the completed request, the marked drawing and the supporting documents. Planning brings the file together for the technical and safety review that follows. The first email has become a job we can assess, and the review is what turns it into a job we can do. Keep that sequence in mind: the client asks, planning clarifies, the client supplies the information, and our company reviews it. Next, we look at the reasoning behind using radiation.","screen_text":[],"start_visual":"Bram returns a coordinated file","beats":[{"at":"Bram returns the completed request, the marked drawing and t","show":"Reviewed explanation, focus 1"},{"at":"Planning brings the file together for the technical and safe","show":"Reviewed explanation, focus 2"},{"at":"Keep that sequence in mind: the client asks, planning clarif","show":"Reviewed explanation, focus 3"},{"at":"Next, we look at the reasoning behind using radiation.","show":"Reviewed explanation, focus 4"}],"characters":["Emilia","Bram"],"clip":"B1.1-S05-P8"}],"sequence":{"cues_before_interaction":["B1.1-S05-P1","B1.1-S05-P2","B1.1-S05-P3","B1.1-S05-P4","B1.1-S05-P5","B1.1-S05-P6","B1.1-S05-P7","B1.1-S05-P8"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S06","title":"Three principles working together","paragraphs":[{"cue":"B1.1-S06-P1","clip":"B1.1-S06-P1","speaker":"Emilia","text":"Bram's request is now on our desk. Before we read his justification, let me show you how the three principles I named at the start work together, for ordinary, planned industrial work like this. Justification asks whether using radiation is warranted at all. Optimisation asks how we keep the exposure that remains as low as we reasonably can. Dose limitation sets the boundaries that may never be crossed. Each of the three has its own evidence, and a job is ready only when all three are answered.","screen_text":[],"start_visual":"Three linked responsibilities around the request","beats":[{"at":"Bram's request is now on our desk.","show":"Reviewed explanation, focus 1"},{"at":"Justification asks whether using radiation is warranted at a","show":"Reviewed explanation, focus 2"},{"at":"Optimisation asks how we keep the exposure that remains as l","show":"Reviewed explanation, focus 3"},{"at":"Each of the three has its own evidence, and a job is ready o","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]},{"cue":"B1.1-S06-P2","clip":"B1.1-S06-P2","speaker":"Emilia","text":"Start with justification. Bram needs reliable information about these welds, because a defect that goes unnoticed could matter for the safety of the vessel. That is the benefit. Using radiation also brings disadvantages, among them a health risk, even at doses that cause no immediate effect, and the benefit has to outweigh them. A competent assessment therefore looks at what information the inspection must deliver and whether another suitable testing technique could deliver it. That reasoning has to be written down, for this type of job, by the people who can judge it; in the next scene we read Bram's.","screen_text":[],"start_visual":"Benefit: useful weld information","beats":[{"at":"Start with justification.","show":"Reviewed explanation, focus 1"},{"at":"That is the benefit.","show":"Reviewed explanation, focus 2"},{"at":"Using radiation also brings disadvantages, among them a heal","show":"Reviewed explanation, focus 3"},{"at":"That reasoning has to be written down, for this type of job,","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]},{"cue":"B1.1-S06-P3","clip":"B1.1-S06-P3","speaker":"Emilia","text":"Suppose the use of radiography is justified. Then optimisation begins: keeping exposure as low as reasonably achievable, taking economic and social factors into account. For this vessel that means examining the practical arrangements before anyone starts. Can shielding be placed between the source and the people around? Can people work farther from the source, or spend less time near it? Can the forklift route and the workbenches be reorganised so that fewer people could be exposed at all? The inspection must still reach the quality the client needs, so the team chooses and verifies the measures under its procedures. And a reasonable improvement is worth making even when the dose would already stay well below a limit.","screen_text":[],"start_visual":"Shielding considered in the plan","beats":[{"at":"Suppose the use of radiography is justified.","show":"Reviewed explanation, focus 1"},{"at":"For this vessel that means examining the practical arrangeme","show":"Reviewed explanation, focus 2"},{"at":"Can the forklift route and the workbenches be reorganised so","show":"Reviewed explanation, focus 3"},{"at":"And a reasonable improvement is worth making even when the d","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]},{"cue":"B1.1-S06-P4","clip":"B1.1-S06-P4","speaker":"Emilia","text":"Dose limitation answers a different question. For planned work, the applicable limits restrict the dose a person may receive over a specified period, for workers and for members of the public. A worker's record carries over from one assignment to the next: exposure from every job counts towards the same total. So a limit marks the boundary; below it, every exposure still counts and optimisation still applies. Planning and dose monitoring are how we keep that check alive during the work.","screen_text":[],"start_visual":"Dose limits apply over a defined period","beats":[{"at":"Dose limitation answers a different question.","show":"Reviewed explanation, focus 1"},{"at":"For planned work, the applicable limits restrict the dose a ","show":"Reviewed explanation, focus 2"},{"at":"So a limit marks the boundary; below it, every exposure stil","show":"Reviewed explanation, focus 3"},{"at":"Planning and dose monitoring are how we keep that check aliv","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]},{"cue":"B1.1-S06-P5","clip":"B1.1-S06-P5","speaker":"Emilia","text":"Now imagine someone answers our planner: \"The dose will be low, so we can go ahead.\" That sentence speaks to the third principle only, and even there it is an expectation, where the check asks for a documented comparison with the applicable limit. It says nothing yet about why radiography is needed for these welds, and nothing about which reasonable measures have been taken. The reverse is just as true: a sound justification still needs good protection. The three parts have to support one another.","screen_text":[],"start_visual":"Claim: low dose means proceed","beats":[{"at":"Now imagine someone answers our planner: \"The dose will be l","show":"Reviewed explanation, focus 1"},{"at":"It says nothing yet about why radiography is needed for thes","show":"Reviewed explanation, focus 2"},{"at":"The reverse is just as true: a sound justification still nee","show":"Reviewed explanation, focus 3"},{"at":"The three parts have to support one another.","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]},{"cue":"B1.1-S06-P6","clip":"B1.1-S06-P6","speaker":"Emilia","text":"Bring that back to Bram's vessel. We need a sound reason for using radiation, practical arrangements that reduce exposure, and respect for the applicable dose limits, and each of the three stands on its own evidence, so the file is finished only when all three are. That is the framework for the lessons that follow. First we examine justification and who has to provide it. Then we look more closely at optimisation in preparing the job.","screen_text":[],"start_visual":"Reason for using radiation","beats":[{"at":"Bring that back to Bram's vessel.","show":"Reviewed explanation, focus 1"},{"at":"We need a sound reason for using radiation, practical arrang","show":"Reviewed explanation, focus 2"},{"at":"First we examine justification and who has to provide it.","show":"Reviewed explanation, focus 3"},{"at":"Then we look more closely at optimisation in preparing the j","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]}],"sequence":{"cues_before_interaction":["B1.1-S06-P1","B1.1-S06-P2","B1.1-S06-P3","B1.1-S06-P4","B1.1-S06-P5","B1.1-S06-P6"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S07","title":"Justification: from the request to the work location","paragraphs":[{"cue":"B1.1-S07-P1","clip":"B1.1-S07-P1","speaker":"Emilia","text":"Let's review Bram's request properly, instead of putting it in the diary. The Belgian Royal Decree of the seventeenth of February, twenty twenty-three, on industrial radiography asks three justification questions for every assignment. Why this examination technique? Why this irradiation location? And why this equipment? The first two belong to the client: Havenmeer gives us its written justification of the technique and of the location, for each type of assignment. The third belongs to us: our company justifies the equipment, and decides whether it can accept the assignment at all. You can open the legal references below as we go.","screen_text":[],"start_visual":"Three written decisions","beats":[{"at":"Let's review Bram's request properly, instead of putting it ","show":"Reviewed explanation, focus 1"},{"at":"Why this examination technique?","show":"Reviewed explanation, focus 2"},{"at":"The first two belong to the client: Havenmeer gives us its w","show":"Reviewed explanation, focus 3"},{"at":"You can open the legal references below as we go.","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]},{"cue":"B1.1-S07-P2","clip":"B1.1-S07-P2","speaker":"Emilia","text":"First, why radiography for these welds? Article three gives two routes. The first: a specific industrial standard, issued by a recognised standardisation organisation, requires radiography for this type of assignment; then the client identifies that requirement, standard and clause. The second: where no industrial standard provides for radiography, or the client asks for more than the standard does, the client justifies radiography with a risk analysis of what it would mean if a fabrication defect went undetected. Two documents are easy to mistake for that analysis, so know them: a purchase order that says \"please do X-ray\" tells us what the client wants; a standard that explains how to take a radiograph tells us how to do it well. The justification is the reasoning behind the choice, and that is what we read.","screen_text":[],"start_visual":"Two routes under article 3","beats":[{"at":"First, why radiography for these welds?","show":"Reviewed explanation, focus 1"},{"at":"The first: a specific industrial standard, issued by a recog","show":"Reviewed explanation, focus 2"},{"at":"The second: where no industrial standard provides for radiog","show":"Reviewed explanation, focus 3"},{"at":"The justification is the reasoning behind the choice, and th","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]},{"cue":"B1.1-S07-P3","clip":"B1.1-S07-P3","speaker":"Emilia","text":"In Bram's file, no industrial standard requiring radiography has been identified for these two welds. His project specification asks for radiography, so the second route applies: his reasoned risk analysis. Its subject is a weld that holds pressure: what a missed defect could lead to, and whether another examination technique could give the same assurance. Keep this apart from the task risk assessment about forklifts, access and other workshop hazards: both matter, and they answer different questions. We read the reasoning in the analysis; the label \"project requirement\" on the specification is where that reasoning starts, and the analysis is where it is made.","screen_text":[],"start_visual":"Bram: risk-analysis route","beats":[{"at":"In Bram's file, no industrial standard requiring radiography","show":"Reviewed explanation, focus 1"},{"at":"His project specification asks for radiography, so the secon","show":"Reviewed explanation, focus 2"},{"at":"Keep this apart from the task risk assessment about forklift","show":"Reviewed explanation, focus 3"},{"at":"We read the reasoning in the analysis; the label \"project re","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]},{"cue":"B1.1-S07-P4","clip":"B1.1-S07-P4","speaker":"Emilia","text":"Next, where should the work take place? Article four gives a firm rule for small movable workpieces: if the complete workpiece fits within one cubic metre and weighs less than five hundred kilograms, its radiography takes place in a bunker: both conditions together, and the piece has to be movable. Look at this separate small pipe assembly: eighty by sixty by forty centimetres, one hundred and twenty kilograms. It meets the conditions, so it goes to a bunker. Note that we judge the complete workpiece, because the whole piece is what travels, and the short length of weld being examined is only the part we image. Our company also checks that the bunker holds a valid conformity certificate.","screen_text":[],"start_visual":"Movable complete workpiece","beats":[{"at":"Next, where should the work take place?","show":"Reviewed explanation, focus 1"},{"at":"Look at this separate small pipe assembly: eighty by sixty b","show":"Reviewed explanation, focus 2"},{"at":"It meets the conditions, so it goes to a bunker.","show":"Reviewed explanation, focus 3"},{"at":"Our company also checks that the bunker holds a valid confor","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]},{"cue":"B1.1-S07-P5","clip":"B1.1-S07-P5","speaker":"Emilia","text":"For a larger or heavier workpiece, a bunker is still the preferred location. Where that is not reasonably feasible, the next option is an irradiation infrastructure at the client's site, after risk analyses by both the client and our company. An irradiation infrastructure is a real facility: fixed shielding built for radiation protection, with the required safety arrangements and supervised entrances; shielding and control, in other words, that stand between the radiation and everyone else. Only when neither a bunker nor such an infrastructure is reasonably feasible may another location be considered, again after both risk analyses. The client records the location justification in writing.","screen_text":[],"start_visual":"Bunker first","beats":[{"at":"For a larger or heavier workpiece, a bunker is still the pre","show":"Reviewed explanation, focus 1"},{"at":"Where that is not reasonably feasible, the next option is an","show":"Reviewed explanation, focus 2"},{"at":"Only when neither a bunker nor such an infrastructure is rea","show":"Reviewed explanation, focus 3"},{"at":"The client records the location justification in writing.","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]},{"cue":"B1.1-S07-P6","clip":"B1.1-S07-P6","speaker":"Emilia","text":"Now apply that order to Bram's vessel. It is one point two metres across and installed in the workshop; welds seven and eight are part of it, so the vessel as a whole is the workpiece. The file therefore examines dismantling and transporting the vessel to a bunker, and explains why that is not reasonably feasible here. It then examines whether fixed shielding could be provided at the vessel, and explains the outcome. Those two supported assessments are what carry the choice of the hall. Bram supplies the site information; our company reviews the proposed conditions and decides whether it can accept them.","screen_text":[],"start_visual":"Two welds remain part of the vessel","beats":[{"at":"Now apply that order to Bram's vessel.","show":"Reviewed explanation, focus 1"},{"at":"The file therefore examines dismantling and transporting the","show":"Reviewed explanation, focus 2"},{"at":"It then examines whether fixed shielding could be provided a","show":"Reviewed explanation, focus 3"},{"at":"Bram supplies the site information; our company reviews the ","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]},{"cue":"B1.1-S07-P7","clip":"B1.1-S07-P7","speaker":"Emilia","text":"If the hall is justified, the radiation still needs a protected work area. Before the radiography, the team marks out a continuous protection perimeter, using at least barrier tape and ionising-radiation warning signs, with a warning lamp in darkness or poor visibility. Look beyond the vessel: workshop doors, nearby benches and every route into the area are part of the picture. Bram is told where the perimeter will run. The client and our company agree in advance who will supervise it, with extra people wherever the radiographers cannot watch the whole line themselves. The tape marks the boundary; the protection comes from the distance it creates, which is why the one thing that matters is that nobody crosses it. And work outside a bunker is always done by at least two industrial radiographers.","screen_text":[],"start_visual":"Continuous barrier around work","beats":[{"at":"If the hall is justified, the radiation still needs a protec","show":"Reviewed explanation, focus 1"},{"at":"Look beyond the vessel: workshop doors, nearby benches and e","show":"Reviewed explanation, focus 2"},{"at":"The client and our company agree in advance who will supervi","show":"Reviewed explanation, focus 3"},{"at":"And work outside a bunker is always done by at least two ind","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]},{"cue":"B1.1-S07-P8","clip":"B1.1-S07-P8","speaker":"Emilia","text":"Where that boundary runs follows from a measurement, under article nineteen. The dose rate outside the perimeter is limited according to who is there: ten microsieverts per hour where people work permanently and in adjoining buildings, forty where workstations are only occasionally occupied, because someone who spends the whole day at a bench must be protected more than someone who passes by. Repeated work at the same place must also respect the three-hundred-microsievert yearly constraint for each person who is not occupationally exposed. The team measures at the perimeter during the first exposure or a test exposure and enlarges the area if the reading asks for it. These values are ceilings; optimisation, which we look at next, works below them.","screen_text":[],"start_visual":"Permanent workplaces and adjoining buildings","beats":[{"at":"Where that boundary runs follows from a measurement, under a","show":"Reviewed explanation, focus 1"},{"at":"The dose rate outside the perimeter is limited according to ","show":"Reviewed explanation, focus 2"},{"at":"The team measures at the perimeter during the first exposure","show":"Reviewed explanation, focus 3"},{"at":"These values are ceilings; optimisation, which we look at ne","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]},{"cue":"B1.1-S07-P9","clip":"B1.1-S07-P9","speaker":"Emilia","text":"Finally, our company justifies the equipment. Article five prefers an X-ray generator when that is feasible without creating additional risk. Where gamma radiography is used, the isotope's penetrating power has to suit the examination. As head of our physical control service, I make sure that a person competent in the different NDT techniques has justified the technique, the isotope and the activity for each assignment, so the equipment is chosen for the job, with reasons. And if our company cannot accept the client's justification of the technique or of the location, it refuses the assignment.","screen_text":[],"start_visual":"X-ray preference with conditions","beats":[{"at":"Finally, our company justifies the equipment.","show":"Reviewed explanation, focus 1"},{"at":"Article five prefers an X-ray generator when that is feasibl","show":"Reviewed explanation, focus 2"},{"at":"As head of our physical control service, I make sure that a ","show":"Reviewed explanation, focus 3"},{"at":"And if our company cannot accept the client's justification ","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]},{"cue":"B1.1-S07-P10","clip":"B1.1-S07-P10","speaker":"Emilia","text":"Bram's request can now be read as a connected file: a reason for radiography, a supported location choice, our equipment assessment, and agreed protection arrangements; four pieces of evidence, each standing on its own. In the workshop, the required measures and the last-minute risk assessment still have to be in place, and if safe working turns out to be impossible, the radiographers stop and report it immediately. Before we move on to optimisation, let me place three workpieces for you. The small pipe assembly, movable, within the size and under the weight: the bunker. A heavy frame that could be moved but would not fit a bunker: a bunker where reasonably feasible, otherwise an irradiation infrastructure after both risk analyses. Bram's installed vessel: the hall, on the strength of the two assessments we just read. Notice that wall thickness played no part in placing them: it helps us choose the examination technique, and it is not part of the bunker rule.","screen_text":[],"start_visual":"Connected evidence","beats":[{"at":"Bram's request can now be read as a connected file: a reason","show":"Reviewed explanation, focus 1"},{"at":"Before we move on to optimisation, let me place three workpi","show":"Reviewed explanation, focus 2"},{"at":"A heavy frame that could be moved but would not fit a bunker","show":"Reviewed explanation, focus 3"},{"at":"Notice that wall thickness played no part in placing them: i","show":"Reviewed explanation, focus 4"}],"characters":["Emilia"]}],"interaction":{"id":"B1.1-S07-Q01","type":"case_sequence","title_visible":"Who justifies what?","prompt_spoken_once":"Bram calls you about his request. Three of his questions, three answers to choose. Each answer is explained.","cases":[{"id":"case1","title":"The technique","situation_visible_text":"Bram: \"You're the radiography specialists. Can't you simply confirm that these welds need radiography, so I don't have to write anything?\"","prompt_spoken_once":"Bram asks: you are the radiography specialists, can't you simply confirm that these welds need radiography, so he doesn't have to write anything? What do you tell him?","options":[{"id":"a","text":"Yes: our head of service confirms the technique for every job, so his written justification is covered by ours.","correct":false,"feedback":{"spoken":"Our head of service does check every job: she makes sure a competent person justified the technique, isotope and activity. That is our company's verification of a justification that already exists. The justification itself is the client's: for each type of assignment, Bram puts in writing why radiography is the right method, either because a standard from a recognised standardisation organisation requires it, or, as here, through his risk analysis of what an undetected defect would mean. We check his reasoning; we cannot write it for him.","screen":"Our head of service does check every job: she makes sure a competent person justified the technique, isotope and activity. That is our company's verification of a justification that already exists. The justification itself is the client's: for each type of assignment, Bram puts in writing why radiography is the right method, either because a standard from a recognised standardisation organisation requires it, or, as here, through his risk analysis of what an undetected defect would mean. We check his reasoning; we cannot write it for him."},"clip":"B1.1-S07-Q01-case1-a"},{"id":"b","text":"No: the technique justification is the client's, in writing: a standard that requires radiography, or his risk analysis of undetected defects.","correct":true,"feedback":{"spoken":"Yes. The decree gives Bram two routes: a specific industrial standard from a recognised standardisation organisation that requires radiography for this type of assignment, or, where no such standard provides for it, a risk analysis of what it would mean if a fabrication defect went undetected in these pressure-holding welds. For his vessel no such standard has been identified, so it is the risk analysis, prepared with people who can judge it. Our part comes afterwards: we verify it, and we refuse the job if we cannot accept it.","screen":"Yes. The decree gives Bram two routes: a specific industrial standard from a recognised standardisation organisation that requires radiography for this type of assignment, or, where no such standard provides for it, a risk analysis of what it would mean if a fabrication defect went undetected in these pressure-holding welds. For his vessel no such standard has been identified, so it is the risk analysis, prepared with people who can judge it. Our part comes afterwards: we verify it, and we refuse the job if we cannot accept it."},"clip":"B1.1-S07-Q01-case1-b"},{"id":"c","text":"No, but his project specification already says \"all shell welds shall be radiographed\", and that sentence is the justification.","correct":false,"feedback":{"spoken":"The specification is a real document and it matters: it tells us what Bram requires of his welds. What it does not contain is the reasoning the decree asks for. A requirement in his own project document is not a standard issued by a recognised standardisation organisation, so it does not open the first route; and it is not a risk analysis, so it does not complete the second. The specification is where Bram's reasoning starts; the risk analysis is where he makes it.","screen":"The specification is a real document and it matters: it tells us what Bram requires of his welds. What it does not contain is the reasoning the decree asks for. A requirement in his own project document is not a standard issued by a recognised standardisation organisation, so it does not open the first route; and it is not a risk analysis, so it does not complete the second. The specification is where Bram's reasoning starts; the risk analysis is where he makes it."},"clip":"B1.1-S07-Q01-case1-c"}],"clip":"B1.1-S07-Q01-case1"},{"id":"case2","title":"The location","situation_visible_text":"Bram: \"The vessel is welded in place and we have no bunker, so the hall is the only option. Is that enough for the location?\"","prompt_spoken_once":"Bram says: the vessel is welded in place and we have no bunker, so the hall is the only option. Is that enough for the location? What do you tell him?","options":[{"id":"a","text":"Yes: a fixed vessel cannot go to a bunker, so the firm bunker rule does not apply and the hall follows.","correct":false,"feedback":{"spoken":"Right about the rule: the firm requirement is for small, movable workpieces, and this vessel is neither small nor movable. Outside that rule the decree sets an order, not a free choice: a bunker is still preferred, then an irradiation infrastructure at the site, and only when neither is reasonably feasible another place. Bram's justification has to walk that order with reasons, why dismantling and transport are unreasonable, why fixed shielding at the vessel is not feasible, before the hall is the answer.","screen":"Right about the rule: the firm requirement is for small, movable workpieces, and this vessel is neither small nor movable. Outside that rule the decree sets an order, not a free choice: a bunker is still preferred, then an irradiation infrastructure at the site, and only when neither is reasonably feasible another place. Bram's justification has to walk that order with reasons, why dismantling and transport are unreasonable, why fixed shielding at the vessel is not feasible, before the hall is the answer."},"clip":"B1.1-S07-Q01-case2-a"},{"id":"b","text":"Yes, as long as our company adds its own risk analysis of the hall to his file.","correct":false,"feedback":{"spoken":"Our risk analysis is required and we will make it. It answers how we work safely at a place, once that place is justified. Justifying the place is Bram's task, in writing, and the decree asks him for two assessments: whether taking the vessel to a bunker is reasonably feasible, and whether fixed shielding at the vessel is. Both risk analyses, his and ours, then support the hall. His sentence gives the facts; the assessments give the justification.","screen":"Our risk analysis is required and we will make it. It answers how we work safely at a place, once that place is justified. Justifying the place is Bram's task, in writing, and the decree asks him for two assessments: whether taking the vessel to a bunker is reasonably feasible, and whether fixed shielding at the vessel is. Both risk analyses, his and ours, then support the hall. His sentence gives the facts; the assessments give the justification."},"clip":"B1.1-S07-Q01-case2-b"},{"id":"c","text":"Not yet: his written justification has to assess both the bunker and fixed shielding at the vessel, with reasons, before the hall is justified.","correct":true,"feedback":{"spoken":"Exactly. \"Welded in place\" and \"no bunker on site\" are facts; the justification is the reasoning the decree asks for. Bram's file has to show why dismantling and transport to a bunker are not reasonably feasible, and why an irradiation infrastructure, fixed shielding at the vessel, is not either. With those two assessments in writing, and risk analyses from both companies, the hall is the justified location, and the perimeter and its supervision are planned there.","screen":"Exactly. \"Welded in place\" and \"no bunker on site\" are facts; the justification is the reasoning the decree asks for. Bram's file has to show why dismantling and transport to a bunker are not reasonably feasible, and why an irradiation infrastructure, fixed shielding at the vessel, is not either. With those two assessments in writing, and risk analyses from both companies, the hall is the justified location, and the perimeter and its supervision are planned there."},"clip":"B1.1-S07-Q01-case2-c"}],"clip":"B1.1-S07-Q01-case2"},{"id":"case3","title":"The equipment","situation_visible_text":"Bram: \"Will you be using X-rays or a gamma source for my welds? And is that my decision or yours?\"","prompt_spoken_once":"Bram asks: X-rays or a gamma source for his welds, and is that his decision or ours? What do you tell him?","options":[{"id":"a","text":"Ours: our company justifies the equipment, preferring an X-ray generator where that is feasible without extra risk, and matching the isotope to the examination where gamma is used.","correct":true,"feedback":{"spoken":"Yes. The third justification question belongs to our company. The decree prefers an X-ray generator when that is feasible without creating additional risk; where gamma radiography is used, the isotope's penetrating power has to suit the examination. Our head of service makes sure a person competent in the NDT techniques justified the technique, the isotope and the activity for this assignment. Bram hears what we chose and why; the choice and its reasons are ours.","screen":"Yes. The third justification question belongs to our company. The decree prefers an X-ray generator when that is feasible without creating additional risk; where gamma radiography is used, the isotope's penetrating power has to suit the examination. Our head of service makes sure a person competent in the NDT techniques justified the technique, the isotope and the activity for this assignment. Bram hears what we chose and why; the choice and its reasons are ours."},"clip":"B1.1-S07-Q01-case3-a"},{"id":"b","text":"His: the client justifies technique and location, and the equipment is part of the technique.","correct":false,"feedback":{"spoken":"Half right: Bram does justify the technique, why radiography, and the location. The equipment is the third, separate question, and the decree gives it to the company doing the work, because it depends on our generators, our sources and our competence. So Bram justifies that radiography is needed and where; we justify what we bring, with a preference for X-rays where feasible without extra risk.","screen":"Half right: Bram does justify the technique, why radiography, and the location. The equipment is the third, separate question, and the decree gives it to the company doing the work, because it depends on our generators, our sources and our competence. So Bram justifies that radiography is needed and where; we justify what we bring, with a preference for X-rays where feasible without extra risk."},"clip":"B1.1-S07-Q01-case3-b"},{"id":"c","text":"Neither: FANC decides which equipment may be used on a client's site.","correct":false,"feedback":{"spoken":"FANC is in the picture, as the regulator that licensed our equipment and can prohibit a location it finds insufficiently justified. The choice of equipment for a given assignment, though, is made by our company, under the decree's rule: X-ray generator where feasible without extra risk, and a suitable isotope where gamma is used, justified by a competent person and checked by our head of service. We decide; FANC supervises.","screen":"FANC is in the picture, as the regulator that licensed our equipment and can prohibit a location it finds insufficiently justified. The choice of equipment for a given assignment, though, is made by our company, under the decree's rule: X-ray generator where feasible without extra risk, and a suitable isotope where gamma is used, justified by a competent person and checked by our head of service. We decide; FANC supervises."},"clip":"B1.1-S07-Q01-case3-c"}],"clip":"B1.1-S07-Q01-case3"}],"clip":"B1.1-S07-Q01","reviewed_b11":true},"sequence":{"cues_before_interaction":["B1.1-S07-P1","B1.1-S07-P2","B1.1-S07-P3","B1.1-S07-P4","B1.1-S07-P5","B1.1-S07-P6","B1.1-S07-P7","B1.1-S07-P8","B1.1-S07-P9","B1.1-S07-P10"],"interaction_after_cue":"B1.1-S07-P10","interaction_id":"B1.1-S07-Q01","post_interaction_cues":[]}},{"id":"S08","title":"Optimisation: protecting people in Bram's hall","paragraphs":[{"cue":"B1.1-S08-P1","speaker":"Emilia","text":"We are back in Bram's workshop at Havenmeer. For this example, the reasons for examining the installed vessel here have been accepted. Now we improve the way the job will be done. Optimisation means keeping exposure as low as reasonably achievable, taking economic and social factors into account: looking, below the limits, for every reasonable improvement. Daniel and Sofia are our radiography team. With Bram, they prepare the positions, the shielding and the access arrangements before any exposure.","screen_text":[],"start_visual":"Optimisation hall: approved Daniel and Sofia miniatures, installed vessel, workbenches and legible horizontal route labels. Paragraph-specific physical arrangement.","beats":[{"at":"We are back in Bram's workshop at Havenmeer.","show":"Reviewed explanation, focus 1"},{"at":"Now we improve the way the job will be done.","show":"Reviewed explanation, focus 2"},{"at":"Optimisation means keeping exposure as low as reasonably ach","show":"Reviewed explanation, focus 3"},{"at":"With Bram, they prepare the positions, the shielding and the","show":"Reviewed explanation, focus 4"}],"characters":["Daniel","Sofia"],"clip":"B1.1-S08-P1"},{"cue":"B1.1-S08-P2","speaker":"Emilia","text":"Start with the radiation itself, before the barrier tape. The team chooses a beam direction that points away from where people are, and restricts the beam so that only the weld and its surroundings are irradiated. Here, a lead shielding screen is placed between the examination area and the proposed control position. Its material, thickness and position have to suit the equipment and the assessed radiation field, including scattered radiation, because radiation that hits the vessel and the floor bounces off in other directions and reaches places the direct beam never pointed at. The screen takes a large share of the exposure out of the control position; the perimeter around the whole set-up takes care of everyone else.","screen_text":[],"start_visual":"Optimisation hall: approved Daniel and Sofia miniatures, installed vessel, workbenches and legible horizontal route labels. Paragraph-specific physical arrangement.","beats":[{"at":"Start with the radiation itself, before the barrier tape.","show":"Reviewed explanation, focus 1"},{"at":"The team chooses a beam direction that points away from wher","show":"Reviewed explanation, focus 2"},{"at":"Its material, thickness and position have to suit the equipm","show":"Reviewed explanation, focus 3"},{"at":"The screen takes a large share of the exposure out of the co","show":"Reviewed explanation, focus 4"}],"characters":["Daniel","Sofia"],"clip":"B1.1-S08-P2"},{"cue":"B1.1-S08-P3","speaker":"Emilia","text":"Now look at Daniel's position. The controls are placed away from the vessel, outside the protection perimeter, with the shielding between him and the examination area. Increasing distance usually reduces exposure. For an unshielded point source in free space, twice the distance gives roughly a quarter of the dose rate; scattering and shielding in this hall change that simple relationship. The exact positions follow from the assessment and are confirmed by measurement on the day. Sofia watches the other approach from outside the perimeter. The two radiographers stay in visual or audible contact with each other throughout, and extra supervision is arranged wherever they cannot cover all the access routes themselves.","screen_text":[],"start_visual":"Optimisation hall: approved Daniel and Sofia miniatures, installed vessel, workbenches and legible horizontal route labels. Paragraph-specific physical arrangement.","beats":[{"at":"Now look at Daniel's position.","show":"Reviewed explanation, focus 1"},{"at":"Increasing distance usually reduces exposure.","show":"Reviewed explanation, focus 2"},{"at":"The exact positions follow from the assessment and are confi","show":"Reviewed explanation, focus 3"},{"at":"The two radiographers stay in visual or audible contact with","show":"Reviewed explanation, focus 4"}],"characters":["Daniel","Sofia"],"clip":"B1.1-S08-P3"},{"cue":"B1.1-S08-P4","speaker":"Emilia","text":"The pedestrian route is another part of the job. People normally use it to reach the workbenches. Bram arranges for those activities to stop and for the route to be closed during the exposures. The closure is agreed in advance, marked, and supervised, so that it holds even when someone is in a hurry. Daniel covers the control-side approach and Sofia the other entrance. The team starts only when both routes are controlled, and if someone crosses the boundary during an exposure, the exposure is stopped first and the conversation comes afterwards.","screen_text":[],"start_visual":"Optimisation hall: approved Daniel and Sofia miniatures, installed vessel, workbenches and legible horizontal route labels. Paragraph-specific physical arrangement.","beats":[{"at":"The pedestrian route is another part of the job.","show":"Reviewed explanation, focus 1"},{"at":"Bram arranges for those activities to stop and for the route","show":"Reviewed explanation, focus 2"},{"at":"The closure is agreed in advance, marked, and supervised, so","show":"Reviewed explanation, focus 3"},{"at":"The team starts only when both routes are controlled, and if","show":"Reviewed explanation, focus 4"}],"characters":["Daniel","Sofia"],"clip":"B1.1-S08-P4"},{"cue":"B1.1-S08-P5","speaker":"Emilia","text":"Good preparation also keeps exposure time down. Before any radiation is produced, the team checks the weld identification, the detector position, the equipment and the exposure plan, so that each image is taken once and taken right. During the exposure, everyone stays at their assessed position and nobody approaches the vessel. After it, the team confirms safe conditions with the required radiation checks before anyone goes near. Time is saved by preparation and discipline; the exposure itself lasts as long as the image quality needs, because an image that has to be repeated costs more dose than one done properly.","screen_text":[],"start_visual":"Optimisation hall: approved Daniel and Sofia miniatures, installed vessel, workbenches and legible horizontal route labels. Paragraph-specific physical arrangement.","beats":[{"at":"Good preparation also keeps exposure time down.","show":"Reviewed explanation, focus 1"},{"at":"Before any radiation is produced, the team checks the weld i","show":"Reviewed explanation, focus 2"},{"at":"After it, the team confirms safe conditions with the require","show":"Reviewed explanation, focus 3"},{"at":"Time is saved by preparation and discipline; the exposure it","show":"Reviewed explanation, focus 4"}],"characters":["Daniel","Sofia"],"clip":"B1.1-S08-P5"},{"cue":"B1.1-S08-P6","speaker":"Emilia","text":"Finally, the drawing becomes real only in the workshop. The team checks the actual hall against the plan and carries out the last-minute risk assessment. During the first or a test exposure, they measure at the perimeter and adjust it where the reading asks for it; the shielding and the occupied positions are verified under the work procedure in the same way. And if the access route reopens or conditions change, the work stops and the assessment is made again. That is optimisation in practice: shielding, distance, preparation and supervision working together, with measurement confirming that the arrangements do what the drawing promised.","screen_text":[],"start_visual":"Optimisation hall: approved Daniel and Sofia miniatures, installed vessel, workbenches and legible horizontal route labels. Paragraph-specific physical arrangement.","beats":[{"at":"Finally, the drawing becomes real only in the workshop.","show":"Reviewed explanation, focus 1"},{"at":"The team checks the actual hall against the plan and carries","show":"Reviewed explanation, focus 2"},{"at":"And if the access route reopens or conditions change, the wo","show":"Reviewed explanation, focus 3"},{"at":"That is optimisation in practice: shielding, distance, prepa","show":"Reviewed explanation, focus 4"}],"characters":["Daniel","Sofia"],"clip":"B1.1-S08-P6"}],"sequence":{"cues_before_interaction":["B1.1-S08-P1","B1.1-S08-P2","B1.1-S08-P3","B1.1-S08-P4","B1.1-S08-P5","B1.1-S08-P6"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S09","title":"Does the screen protect the whole team?","paragraphs":[{"cue":"B1.1-S09-P1","speaker":"Emilia","text":"Look at the two working positions in Bram's hall. The lead screen stands between the vessel and Daniel's controls. Sofia supervises the other entrance, on the opposite side of the examination area. She is outside the perimeter too, with her personal dosimeter on, and from where she stands she can see the door and the forklift route. What she does not have is the screen: it stands on Daniel's side, and nothing is between her and the vessel.","screen_text":[],"start_visual":"Same hall; Daniel-screen relationship highlighted, then Sofia on the opposite side. No measured result claimed.","beats":[{"at":"Look at the two working positions in Bram's hall.","show":"Reviewed explanation, focus 1"},{"at":"The lead screen stands between the vessel and Daniel's contr","show":"Reviewed explanation, focus 2"},{"at":"She is outside the perimeter too, with her personal dosimete","show":"Reviewed explanation, focus 3"},{"at":"What she does not have is the screen: it stands on Daniel's ","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S09-P1"},{"cue":"B1.1-S09-P2","speaker":"Emilia","text":"During the test exposure the team measures at both positions. At Daniel's controls the reading is low. At Sofia's position it meets the applicable dose-rate criterion for that position, and clearly higher than at Daniel's. Sofia says what many of us would say: \"The reading meets the criterion, so I'm fine where I am.\" Bram points to a spot by the door, five metres further back, from which the entrance is still in full view. Luc mentions that a second screen is in the depot and could be here tomorrow.","screen_text":[],"start_visual":"Same hall; Daniel-screen relationship highlighted, then Sofia on the opposite side. No measured result claimed.","beats":[{"at":"During the test exposure the team measures at both positions","show":"Reviewed explanation, focus 1"},{"at":"At Daniel's controls the reading is low.","show":"Reviewed explanation, focus 2"},{"at":"Sofia says what many of us would say: \"The reading meets the","show":"Reviewed explanation, focus 3"},{"at":"Luc mentions that a second screen is in the depot and could ","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S09-P2"},{"cue":"B1.1-S09-P3","speaker":"Emilia","text":"That is the whole of optimisation in one small decision: a position whose reading meets the applicable criterion, two ways to improve it, and a job that has been prepared for today. Keep three things in view: the dose at Sofia's position, the entrance she supervises, and what is reasonable to ask of the team and the client.","screen_text":[],"start_visual":"Same hall; Daniel-screen relationship highlighted, then Sofia on the opposite side. No measured result claimed.","beats":[{"at":"That is the whole of optimisation in one small decision: a p","show":"Reviewed explanation, focus 1"},{"at":"Keep three things in view: the dose at Sofia's position, the","show":"Reviewed explanation, focus 2"}],"clip":"B1.1-S09-P3"}],"interaction":{"id":"B1.1-S09-Q01","type":"single_choice","title_visible":"Sofia's position","prompt_spoken_once":"What does the team do about Sofia's position?","situation_visible_text":"At Sofia's position the measured dose rate is within the applicable dose-rate criterion but well above Daniel's. Bram offers a spot five metres further back with the entrance still in view. A second screen could arrive tomorrow.","options":[{"id":"a","text":"Keep her where she is: the reading at her position is within the applicable criterion, so the arrangement is acceptable.","correct":false,"feedback":{"spoken":"The reading does tell us something important: the applicable dose-rate criterion is met at this position, and the team was right to measure rather than assume. Respecting the limit is the third principle; optimisation is the second, and it keeps asking whether a reasonable improvement is available. Here one is, at no cost: a position further back that still gives her the entrance. Below the limit, the question is always: is there a better place she can stand?","screen":"The local criterion is met, and a free improvement is still available. Optimisation continues below the limit."},"clip":"B1.1-S09-Q01-a"},{"id":"b","text":"Move her to the position by the door, where the entrance is still in view, and measure again during a controlled test exposure before routine work.","correct":true,"feedback":{"spoken":"Yes. Distance is the cheapest protection there is: the farther position offers a practical improvement while the entrance stays supervised. The team verifies the new arrangement and measures there during a controlled test exposure. Routine work continues only if the results confirm adequate protection. Dose reduced, supervision kept, the client's day respected: that is what \"as low as reasonably achievable\" looks like in a hall.","screen":"Further back, entrance still covered, measured again: a reasonable improvement, verified."},"clip":"B1.1-S09-Q01-b"},{"id":"c","text":"Postpone the exposures until the second screen arrives tomorrow and put it on Sofia's side.","correct":false,"feedback":{"spoken":"A second screen would lower Sofia's dose further, and on a longer job it may well be worth bringing. Optimisation, though, weighs the improvement against what it costs, a day's delay for Bram's plant, a team that stands idle, and against what else is available. Today the team first assesses the available farther position and verifies it by measurement. If that does not provide adequate protection, it must add suitable measures or postpone the job. The screen remains an option to assess, not something cost alone allows us to dismiss.","screen":"A screen helps; a free improvement is available today. Reasonable means weighing the gain against the cost."},"clip":"B1.1-S09-Q01-c"}],"clip":"B1.1-S09-Q01","reviewed_b11":true},"sequence":{"cues_before_interaction":["B1.1-S09-P1","B1.1-S09-P2","B1.1-S09-P3"],"interaction_after_cue":"B1.1-S09-P3","interaction_id":"B1.1-S09-Q01","post_interaction_cues":[]}},{"id":"S10","title":"Dose information: read the right evidence","paragraphs":[{"cue":"B1.1-S10-P1","speaker":"Emilia","text":"We have improved the arrangements for Bram's job. Now look at what the instruments and the dose records can actually tell us, because they answer different questions. Daniel carries three devices. In his hand, the survey meter: it measures the radiation field at a place, right now, at the perimeter, at the control position, next to the vessel after an exposure. On the left of his chest, the electronic personal dosimeter: it follows the dose he himself receives, shows it live and sounds an alarm at a set level. On the right, the passive badge: it records his dose over the monitoring period and is read out afterwards by the dosimetry service, which makes it the official record of what he received. Three devices, three jobs, and all three sit behind the shielding and the perimeter that do the protecting.","screen_text":[],"start_visual":"B1Followup: S10 view 1; linked to Bram’s current assignment.","beats":[{"at":"We have improved the arrangements for Bram's job.","show":"Reviewed explanation, focus 1"},{"at":"Daniel carries three devices.","show":"Reviewed explanation, focus 2"},{"at":"On the left of his chest, the electronic personal dosimeter:","show":"Reviewed explanation, focus 3"},{"at":"Three devices, three jobs, and all three sit behind the shie","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S10-P1"},{"cue":"B1.1-S10-P2","speaker":"Emilia","text":"With those three in mind, keep two quantities apart. A dose rate, in microsieverts per hour, is what the survey meter reads: how fast dose is being delivered at one place at one moment. An accumulated dose, in millisieverts, is what the dosimeters build up: how much a person has received over a period. A rate at the tape and a dose on a badge are different things, so comparing one with a limit meant for the other tells you nothing. To check a personal dose limit, the quantity, the person and the period have to match, with every exposure of that period included, which is why one favourable reading at the perimeter says nothing about Daniel's dose for the year.","screen_text":[],"start_visual":"B1Followup: S10 view 2; linked to Bram’s current assignment.","beats":[{"at":"With those three in mind, keep two quantities apart.","show":"Reviewed explanation, focus 1"},{"at":"A dose rate, in microsieverts per hour, is what the survey m","show":"Reviewed explanation, focus 2"},{"at":"A rate at the tape and a dose on a badge are different thing","show":"Reviewed explanation, focus 3"},{"at":"To check a personal dose limit, the quantity, the person and","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S10-P2"},{"cue":"B1.1-S10-P3","speaker":"Emilia","text":"Three reference levels guide protection, and each serves a different purpose. The legal dose limit is the boundary that may never be crossed. A dose constraint sits below it: a planning level used in optimisation for a particular job or source, which the Agency can impose. The alarm setting on Daniel's electronic dosimeter is different again: an operational warning threshold, set for this task under our approved arrangements, so that he knows early when the work is not going as planned. Limit, constraint, alarm: boundary, planning level, early warning.","screen_text":[],"start_visual":"B1Followup: S10 view 3; linked to Bram’s current assignment.","beats":[{"at":"Three reference levels guide protection, and each serves a d","show":"Reviewed explanation, focus 1"},{"at":"The legal dose limit is the boundary that may never be cross","show":"Reviewed explanation, focus 2"},{"at":"The alarm setting on Daniel's electronic dosimeter is differ","show":"Reviewed explanation, focus 3"},{"at":"Limit, constraint, alarm: boundary, planning level, early wa","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S10-P3"},{"cue":"B1.1-S10-P4","speaker":"Emilia","text":"So what happens when the alarm sounds in Bram's hall? Daniel acts under the procedure: the exposure is stopped, he moves away from the source, and he reports what happened before anything resumes. The alarm is a signal to act; its cause and the recorded dose still need to be checked. An alarm does not, by itself, establish how the dose compares with a limit. And when the alarm stays silent, the dosimeter has recorded what he received; the proof that the limits were respected comes from the records over the period, read against the right quantity and the right person. The instruments tell us where we are; the planning and the records tell us whether we did well.","screen_text":[],"start_visual":"B1Followup: S10 view 3; linked to Bram’s current assignment.","beats":[{"at":"So what happens when the alarm sounds in Bram's hall?","show":"Reviewed explanation, focus 1"},{"at":"The alarm is a signal to act; its cause and the recorded dos","show":"Reviewed explanation, focus 2"},{"at":"An alarm does not, by itself, establish how the dose compare","show":"Reviewed explanation, focus 3"},{"at":"The instruments tell us where we are; the planning and the r","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S10-P4"}],"sequence":{"cues_before_interaction":["B1.1-S10-P1","B1.1-S10-P2","B1.1-S10-P3","B1.1-S10-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S11","title":"Can one reading answer for the week?","paragraphs":[{"cue":"B1.1-S11-P1","speaker":"Emilia","text":"For this dose-planning example, look ahead to the end of the Havenmeer job. Back at the depot, Daniel reads his electronic dosimeter: a small dose for the day, well within what the plan expected. The survey meter has done its work at the perimeter and at the control position. His passive badge goes back in the rack; the dosimetry service will read it out at the end of the monitoring period, as it does every time.","screen_text":[],"start_visual":"B1Followup: S11 view 1; linked to Bram’s current assignment.","beats":[{"at":"For this dose-planning example, look ahead to the end of the","show":"Reviewed explanation, focus 1"},{"at":"Back at the depot, Daniel reads his electronic dosimeter: a ","show":"Reviewed explanation, focus 2"},{"at":"The survey meter has done its work at the perimeter and at t","show":"Reviewed explanation, focus 3"},{"at":"His passive badge goes back in the rack; the dosimetry servi","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S11-P1"},{"cue":"B1.1-S11-P2","speaker":"Emilia","text":"Luc is planning the coming days. \"Daniel's reading is low,\" he says, \"so I'll put him on the gamma job tomorrow and the two bunker days after that. No need to look anything up.\" Sofia, listening, isn't so sure: the week's jobs add up, and Daniel had a heavy job last week too. Think about what Luc is holding in his hand, what that number covers, and what the limit is written for.","screen_text":[],"start_visual":"B1Followup: S11 view 1; linked to Bram’s current assignment.","beats":[{"at":"Luc is planning the coming days.","show":"Reviewed explanation, focus 1"},{"at":"\"Daniel's reading is low,\" he says, \"so I'll put him on the ","show":"Reviewed explanation, focus 2"},{"at":"No need to look anything up.\" Sofia, listening, isn't so sur","show":"Reviewed explanation, focus 3"},{"at":"Think about what Luc is holding in his hand, what that numbe","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S11-P2"}],"interaction":{"id":"B1.1-S11-Q01","type":"single_choice","title_visible":"Planning Daniel's week","prompt_spoken_once":"What does Luc need before he schedules Daniel's week?","situation_visible_text":"Daniel's electronic dosimeter shows a small dose for today's job. Luc wants to schedule him for a gamma job tomorrow and two bunker days after that, without checking anything. His badge is read out at the end of the period.","options":[{"id":"a","text":"Nothing more: today's electronic reading is low, so the limit leaves plenty of room for the week.","correct":false,"feedback":{"spoken":"Today's reading is real and useful: it tells us this job went as planned. What it covers is one day. The limit is written for a person over a period, and every job in that period counts towards the same total, last week's heavy job included. So the number in Luc's hand is one entry in a running record, and the planning question is answered by that record, with the last entry as one part of it.","screen":"One day's reading is one entry. The limit applies to the period, with every job included."},"clip":"B1.1-S11-Q01-a"},{"id":"b","text":"The readout of Daniel's passive badge for today's job, before anything else is scheduled.","correct":false,"feedback":{"spoken":"The badge is the official record, and it will confirm the period's dose when the service reads it out. That is exactly why it is read per monitoring period and not per job: it is the check behind the planning. Between readouts, our service keeps Daniel's running dose from the electronic dosimeters and the previous readouts, and that is what Luc looks at before he fills a week.","screen":"The badge confirms the period afterwards. Planning uses the running record kept by the service."},"clip":"B1.1-S11-Q01-b"},{"id":"c","text":"Daniel's running dose for the period so far, with the expected doses of the three planned jobs, set against his constraint and the limit.","correct":true,"feedback":{"spoken":"Yes. Three things, matching the way the limit is written: the right person, the right quantity, the right period. The service keeps Daniel's running dose: today's reading, last week's job, the earlier official results and the subsequent operational readings, without counting any exposure twice. Luc adds what the gamma job and the bunker days are expected to give, and reads the total against the planning level set for Daniel and the limit behind it. If the plan meets the applicable requirements, it can be scheduled. Otherwise the service revises the protective arrangements and work allocation. Moving a job to a later day does not reset a person's dose for the period. That is how one low reading becomes a planning decision instead of a guess.","screen":"Running dose for the period plus the expected doses of the planned jobs, against constraint and limit."},"clip":"B1.1-S11-Q01-c"}],"clip":"B1.1-S11-Q01","reviewed_b11":true},"sequence":{"cues_before_interaction":["B1.1-S11-P1","B1.1-S11-P2"],"interaction_after_cue":"B1.1-S11-P2","interaction_id":"B1.1-S11-Q01","post_interaction_cues":[]}},{"id":"S12","title":"The regulation, our licence and our procedures","paragraphs":[{"cue":"B1.1-S12-P1","speaker":"Emilia","text":"Now return to the preparation of Bram's job. Planning has accepted the request, and the team is preparing the agreed work. On the desk lie three kinds of document, and Daniel reaches for each of them for a different reason. The first is the regulation: it tells us what has to be done, for everyone who does this work. Article sixteen of the industrial radiography decree, for instance, requires that the safety measures identified in the risk analyses are in place and that the team performs a last-minute risk assessment before the first exposure. That is the requirement, written once, for every job.","screen_text":[],"start_visual":"B1Followup: S12 view 1; linked to Bram’s current assignment.","beats":[{"at":"Now return to the preparation of Bram's job.","show":"Reviewed explanation, focus 1"},{"at":"On the desk lie three kinds of document, and Daniel reaches ","show":"Reviewed explanation, focus 2"},{"at":"The first is the regulation: it tells us what has to be done","show":"Reviewed explanation, focus 3"},{"at":"That is the requirement, written once, for every job.","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S12-P1"},{"cue":"B1.1-S12-P2","speaker":"Emilia","text":"The second is our company's licence. It is the Agency's authorisation for our company: it names the installations and equipment we may use, the sources we may hold, the practices we may carry out, industrial radiography in our bunker and on clients' sites, and the conditions attached to all of that. When Daniel wants to know whether we may bring a particular X-ray set to Havenmeer, the licence is the document that answers. Its scope and its conditions are what our company works within, and every job is prepared inside that frame.","screen_text":[],"start_visual":"B1Followup: S12 view 2; linked to Bram’s current assignment.","beats":[{"at":"The second is our company's licence.","show":"Reviewed explanation, focus 1"},{"at":"It is the Agency's authorisation for our company: it names t","show":"Reviewed explanation, focus 2"},{"at":"When Daniel wants to know whether we may bring a particular ","show":"Reviewed explanation, focus 3"},{"at":"Its scope and its conditions are what our company works with","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S12-P2"},{"cue":"B1.1-S12-P3","speaker":"Emilia","text":"The third is the approved work procedure, and with it the worksite record. The procedure describes how our team performs the work and the checks: in which order, with which instruments, against which criteria. Its radiation-protection content has been examined and approved by the recognised expert, you saw in the earlier scenes how that approval comes about, so when Daniel follows it, the expert's judgement is at the vessel with him. The record is the other half: it shows what was actually checked at Havenmeer, by whom, when, and with what result. The procedure is the method; the record is the evidence that the method was applied today, in this hall, with these results.","screen_text":[],"start_visual":"B1Followup: S12 view 3; linked to Bram’s current assignment.","beats":[{"at":"The third is the approved work procedure, and with it the wo","show":"Reviewed explanation, focus 1"},{"at":"The procedure describes how our team performs the work and t","show":"Reviewed explanation, focus 2"},{"at":"The record is the other half: it shows what was actually che","show":"Reviewed explanation, focus 3"},{"at":"The procedure is the method; the record is the evidence that","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S12-P3"},{"cue":"B1.1-S12-P4","speaker":"Emilia","text":"Three documents, three questions. What is required? The regulation. What may our company do, and under which conditions? The licence. How do we do it, and what did we actually check? The procedure and its record. Open the three parts of Bram's job file and read, in each one, the line that answers its question.","screen_text":[],"start_visual":"B1Followup: S12 view 3; linked to Bram’s current assignment.","beats":[{"at":"Three documents, three questions.","show":"Reviewed explanation, focus 1"},{"at":"The regulation.","show":"Reviewed explanation, focus 2"},{"at":"How do we do it, and what did we actually check?","show":"Reviewed explanation, focus 3"},{"at":"Open the three parts of Bram's job file and read, in each on","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S12-P4"}],"interaction":{"id":"B1.1-S12-X01","type":"guided_exploration","title_visible":"What does each part of the file establish?","prompt_spoken_once":"Open the three parts of the job file and read the line each one is there for.","items":[{"id":"regulation","label":"The regulation: what is required?","page":"Extract of the industrial radiography decree, article sixteen, with the two lines in focus: the identified safety measures are present; a last-minute risk assessment is performed before the first exposure.","spoken":"This is the requirement for Bram's job and for every job like it: the safety measures from the risk analyses are in place, and the team carries out its last-minute risk assessment before the first exposure. It is the same for every hall and every team. Which measures those are for Havenmeer, and whether they were checked today, you find in the next two parts.","screen":"Required: assessed safety measures present; last-minute risk assessment before the first exposure.","field_in_focus":"The regulation: what is required?","clip":"B1.1-S12-X01-regulation"},{"id":"licence","label":"Our licence: what may we do, under which conditions?","page":"Teaching excerpt of the company licence, with the fields in focus: authorised practices (radiography in the company bunker and on clients' sites); equipment scope; conditions.","spoken":"This is the Agency's authorisation for our company. It tells Daniel that radiography on a client's site is within our practices, that the X-ray set he plans to bring is within our equipment scope, and which conditions apply. The licence sets the frame for the job; the justification, the risk analyses and today's checks fill that frame in for Havenmeer.","screen":"Licence: authorised practices, equipment scope, conditions.","field_in_focus":"Our licence: what may we do, under which conditions?","clip":"B1.1-S12-X01-licence"},{"id":"procedure","label":"Procedure and record: how, and what was checked?","page":"The worksite set-up procedure with its approval line (recognised expert) in focus; below it, today's worksite record with one completed line: perimeter measured at the first exposure · result · time · Daniel.","spoken":"The procedure tells the team how: mark out the perimeter, measure at the line during the first exposure, enlarge it if the reading asks for it, approved by the recognised expert. The record shows that it happened at Havenmeer: the measurement, the result, the time, and Daniel's name. Together they answer \"how do we work\" and \"what did we do today\", and the record is what the expert and the Agency will read later.","screen":"Procedure: how to check. Record: who checked what, when, with which result.","field_in_focus":"Procedure and record: how, and what was checked?","clip":"B1.1-S12-X01-procedure"}],"clip":"B1.1-S12-X01","reviewed_b11":true},"sequence":{"cues_before_interaction":["B1.1-S12-P1","B1.1-S12-P2","B1.1-S12-P3","B1.1-S12-P4"],"interaction_after_cue":"B1.1-S12-P4","interaction_id":"B1.1-S12-X01","post_interaction_cues":[]}},{"id":"S13","title":"The hall is no longer as planned","paragraphs":[{"cue":"B1.1-S13-P1","speaker":"Emilia","text":"Daniel and Sofia arrive at Havenmeer Process Works for the job that was planned last week. Bram meets them at the door of the hall. Everything was prepared on paper: the workpiece, the technique, the protection perimeter, the place for the shielding and the positions of the two radiographers. Daniel walks in and sees two things that were different on paper. Pallets are now stored exactly where the perimeter and the shielding were planned. And in the adjoining hall, behind the wall, a maintenance team is at work. In the plan, that hall was empty.","screen_text":[],"start_visual":"B1Followup: S13 view 1; linked to Bram’s current assignment.","beats":[{"at":"Daniel and Sofia arrive at Havenmeer Process Works for the j","show":"Reviewed explanation, focus 1"},{"at":"Everything was prepared on paper: the workpiece, the techniq","show":"Reviewed explanation, focus 2"},{"at":"Pallets are now stored exactly where the perimeter and the s","show":"Reviewed explanation, focus 3"},{"at":"In the plan, that hall was empty.","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S13-P1"},{"cue":"B1.1-S13-P2","speaker":"Emilia","text":"These two changes matter because the plan was calculated on the hall as it was described. The distance to the perimeter, the place of the shielding, the positions of Daniel and Sofia and the dose rate at the wall of the adjoining hall all follow from that description. Pallets in the way mean the perimeter can no longer run where it was calculated, and the shielding can no longer stand where it was meant to stand. People in the adjoining hall mean that the wall is now a boundary with someone on the other side. The assessment must include adjoining areas, even when people cannot be seen from the vessel. Article nineteen sets a maximum of ten microsieverts per hour for permanent workstations and adjoining buildings; an apparently empty adjoining area must not simply be ignored. One change moves the perimeter. The other changes what the perimeter has to protect.","screen_text":[],"start_visual":"B1Followup: S13 view 2; linked to Bram’s current assignment.","beats":[{"at":"These two changes matter because the plan was calculated on ","show":"Reviewed explanation, focus 1"},{"at":"Pallets in the way mean the perimeter can no longer run wher","show":"Reviewed explanation, focus 2"},{"at":"Article nineteen sets a maximum of ten microsieverts per hou","show":"Reviewed explanation, focus 3"},{"at":"The other changes what the perimeter has to protect.","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S13-P2"},{"cue":"B1.1-S13-P3","speaker":"Emilia","text":"The X-ray set stays switched off and the first exposure waits. Daniel reports to Luc and to our service, and tells Bram what he has found. Then each of them decides their own part. Bram decides what happens in his hall: whether the pallets are moved, and whether the maintenance team stays, pauses or leaves. Our company decides whether the plan still covers the new situation. That means a new look at the perimeter, at the shielding and at the dose rate on every side, including the side it cannot see. If the pallets are gone and the neighbouring work is paused, our team still checks that the agreed conditions really are present before proceeding under the procedure. If the pallets stay or the team keeps working, the plan is adapted, checked and confirmed first. In both cases the start signal comes from the company's own check, after Bram has done his part.","screen_text":[],"start_visual":"B1Followup: S13 view 2; linked to Bram’s current assignment.","beats":[{"at":"The X-ray set stays switched off and the first exposure wait","show":"Reviewed explanation, focus 1"},{"at":"Bram decides what happens in his hall: whether the pallets a","show":"Reviewed explanation, focus 2"},{"at":"That means a new look at the perimeter, at the shielding and","show":"Reviewed explanation, focus 3"},{"at":"In both cases the start signal comes from the company's own ","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S13-P3"},{"cue":"B1.1-S13-P4","speaker":"Emilia","text":"Changed conditions are normal on a site. Halls get used, pallets arrive, other teams are planned in. The skill is to see the change, stop, report it and reassess, instead of fitting the work around it. And the division is clear: the person who owns the hall decides about the hall, and the company that brings the radiation decides about the radiation. Bram can clear the space and move his people. Whether it is safe to expose is a decision our company takes, and it takes that decision with the plan in hand.","screen_text":[],"start_visual":"B1Followup: S13 view 2; linked to Bram’s current assignment.","beats":[{"at":"Changed conditions are normal on a site.","show":"Reviewed explanation, focus 1"},{"at":"The skill is to see the change, stop, report it and reassess","show":"Reviewed explanation, focus 2"},{"at":"And the division is clear: the person who owns the hall deci","show":"Reviewed explanation, focus 3"},{"at":"Whether it is safe to expose is a decision our company takes","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S13-P4"}],"interaction":{"id":"B1.1-S13-Q01","type":"single_choice","title_visible":"Who decides what?","prompt_spoken_once":"Daniel has found two changes. Who decides what, before the first exposure can start?","situation_visible_text":"Daniel and Sofia arrive at Havenmeer Process Works for the planned on-site job. Pallets are now stored where the protection perimeter and the shielding were planned. A maintenance team is working in the adjoining hall, which the plan assumed to be empty. No exposure has started yet.","options":[{"id":"a","text":"Bram clears the pallets and confirms that the maintenance team will take a break during the exposures. With both settled, Daniel starts as planned, because the hall is now as it was described.","correct":false,"feedback":{"spoken":"You have Bram's part right: the pallets and the maintenance team are his to arrange. The piece that is missing is the company's own check. The plan was calculated on an empty adjoining hall and on a perimeter at a certain distance. A break during the exposures is an arrangement, and arrangements are verified and written into the plan before they protect anyone. The hall is only as described when the company has confirmed that itself.","screen":"Bram arranges the hall. The company confirms the plan before the start."},"clip":"B1.1-S13-Q01-a"},{"id":"b","text":"Bram clears the pallets and decides whether the maintenance team stays or leaves. Daniel takes his word on the adjoining hall and only re-measures the perimeter on his own side of the wall.","correct":false,"feedback":{"spoken":"You are right that Bram decides about the pallets and about his own people. Where this goes wrong is the wall. The perimeter belongs to the radiography company on every side, also on the side it cannot see. A boundary that is measured on one side and taken on trust on the other is half a boundary. The company checks the dose rate where people can be, and the adjoining hall is now exactly such a place.","screen":"The perimeter is the company's on every side, including behind the wall."},"clip":"B1.1-S13-Q01-b"},{"id":"c","text":"Bram decides what happens to the pallets and the maintenance team, because the hall is his. The company decides whether the new situation is still covered by the plan and checks the setup before exposure and verifies the perimeter during the first or a test exposure.","correct":true,"feedback":{"spoken":"Exactly. Two owners, two decisions. Bram owns the hall, so the pallets and the maintenance team are his to move, pause or keep. The company owns the radiation, so whether the plan still holds, where the perimeter now runs and what the dose rate is on every side are its decisions, with the setup checked beforehand and dose rates measured during the first or a test exposure. Daniel reports to Luc, to our service and to Bram, and the job starts when both parts are done.","screen":"Bram: the hall. The company: the plan, the perimeter and the start."},"clip":"B1.1-S13-Q01-c"}],"clip":"B1.1-S13-Q01","reviewed_b11":true},"sequence":{"cues_before_interaction":["B1.1-S13-P1","B1.1-S13-P2","B1.1-S13-P3","B1.1-S13-P4"],"interaction_after_cue":"B1.1-S13-P4","interaction_id":"B1.1-S13-Q01","post_interaction_cues":[]}},{"id":"S14","title":"From hold to a verified arrangement","paragraphs":[{"cue":"B1.1-S14-P1","speaker":"Emilia","text":"We stay at Havenmeer, because the hold is only the beginning. The first thing Daniel does is report in facts. The space where the shielding and the perimeter were planned is taken by stored pallets. People are at work in the adjoining hall. No exposure has been made. He reports it this way to Luc and to our service, and he writes it down the same way in the worksite file. Facts first, because everyone who now has to decide, Luc, the physical control service and Bram, works from this description and nothing else. A report of what has been seen, what is known and what still has to be established is the ground every next step stands on.","screen_text":[],"start_visual":"B1Followup: S14 view 1; linked to Bram’s current assignment.","beats":[{"at":"We stay at Havenmeer, because the hold is only the beginning","show":"Reviewed explanation, focus 1"},{"at":"The space where the shielding and the perimeter were planned","show":"Reviewed explanation, focus 2"},{"at":"He reports it this way to Luc and to our service, and he wri","show":"Reviewed explanation, focus 3"},{"at":"A report of what has been seen, what is known and what still","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S14-P1"},{"cue":"B1.1-S14-P2","speaker":"Emilia","text":"Bram does his part: he has the pallets moved and he coordinates with the maintenance team about when they work and where. Meanwhile the company looks at the arrangement as a whole, and that is more than the two things Daniel noticed. Five elements belong together in a site arrangement: the space, the direction of the beam, the shielding, the areas where people can be, and who supervises the perimeter during the exposures. Change one and the others shift with it. A pallet that stays means the shielding moves, and shielding that moves means the beam direction and the perimeter distance are looked at again. The outcome can be that the stored material is moved, that the neighbouring work is rescheduled, or that a different arrangement is assessed and chosen. The outcome can also be that the job waits for another day, because safe conditions are a result that is reached, and sometimes the way to reach them is to come back.","screen_text":[],"start_visual":"B1Followup: S14 view 2; linked to Bram’s current assignment.","beats":[{"at":"Bram does his part: he has the pallets moved and he coordina","show":"Reviewed explanation, focus 1"},{"at":"Five elements belong together in a site arrangement: the spa","show":"Reviewed explanation, focus 2"},{"at":"A pallet that stays means the shielding moves, and shielding","show":"Reviewed explanation, focus 3"},{"at":"The outcome can also be that the job waits for another day, ","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S14-P2"},{"cue":"B1.1-S14-P3","speaker":"Emilia","text":"When the arrangement is decided, the team walks it before anyone exposes. The shielding stands where it is drawn. The perimeter is marked where it is calculated. The agreed arrangements for the adjoining hall are confirmed, and the applicable boundary criterion is included in the checks. The worksite information is updated so the file describes the hall as it is today. Then Daniel and Sofia do their last-minute risk assessment at the spot: a short, deliberate look at the real situation, in the minutes before the first exposure, by the people who will do the work.","screen_text":[],"start_visual":"B1Followup: S14 view 3; linked to Bram’s current assignment.","beats":[{"at":"When the arrangement is decided, the team walks it before an","show":"Reviewed explanation, focus 1"},{"at":"The perimeter is marked where it is calculated.","show":"Reviewed explanation, focus 2"},{"at":"The agreed arrangements for the adjoining hall are confirmed","show":"Reviewed explanation, focus 3"},{"at":"Then Daniel and Sofia do their last-minute risk assessment a","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S14-P3"},{"cue":"B1.1-S14-P4","speaker":"Emilia","text":"The first exposure is a test. During it the team measures the dose rate at the perimeter and at the wall of the adjoining hall, and compares the readings with the limits in the plan. Where a reading is higher than planned, the arrangement is adjusted and measured again. The readings that go into the record are the ones from the meter, written at the time, with the place and the moment. That is what makes the arrangement verified: a plan that was calculated, a set-up that was checked, and measurements that confirm it. The permission to continue follows from those readings, and that is where this example ends.","screen_text":[],"start_visual":"B1Followup: S14 view 3; linked to Bram’s current assignment.","beats":[{"at":"The first exposure is a test.","show":"Reviewed explanation, focus 1"},{"at":"Where a reading is higher than planned, the arrangement is a","show":"Reviewed explanation, focus 2"},{"at":"The readings that go into the record are the ones from the m","show":"Reviewed explanation, focus 3"},{"at":"The permission to continue follows from those readings, and ","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S14-P4"}],"sequence":{"cues_before_interaction":["B1.1-S14-P1","B1.1-S14-P2","B1.1-S14-P3","B1.1-S14-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S15","title":"Bram's assignment: bring the reasoning together","paragraphs":[{"cue":"B1.1-S15-P1","speaker":"Emilia","text":"Bram's request is where this lesson started, so let us walk his request back from the beginning, this time in one line of reasoning. He asked for radiography on two welds. Before any exposure was made, the company asked three questions, in this order. Is radiography needed for these welds, and on what basis: a standard from a recognised standardisation organisation, or a risk analysis of what an undetected defect would mean? Where will the exposure take place, and does this piece belong in the bunker, or is there a supported reason for his hall? And with what equipment, with an X-ray generator preferred where that is feasible without extra risk? Three questions, three justified answers, and only then a job.","screen_text":[],"start_visual":"B1Followup S15 closing view 1.","beats":[{"at":"Bram's request is where this lesson started, so let us walk ","show":"Reviewed explanation, focus 1"},{"at":"Before any exposure was made, the company asked three questi","show":"Reviewed explanation, focus 2"},{"at":"Where will the exposure take place, and does this piece belo","show":"Reviewed explanation, focus 3"},{"at":"Three questions, three justified answers, and only then a jo","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S15-P1"},{"cue":"B1.1-S15-P2","speaker":"Emilia","text":"With the job justified, the company organised protection. It drew the perimeter around the work, put distance and shielding between the radiation and the people, and placed two radiographers where they can supervise the perimeter and remain in visual or audible contact. It gave each of them a survey meter for the dose rate at a place and dosimeters for the dose they themselves receive, and it read those numbers against the planning level set for them and the limit behind it. It planned Daniel's week on his running dose for the period, with every job counted. And it wrote all of that down in documents that each answer a different question: what is required, what the company may do, how it is done, and what was done.","screen_text":[],"start_visual":"B1Followup S15 closing view 2.","beats":[{"at":"With the job justified, the company organised protection.","show":"Reviewed explanation, focus 1"},{"at":"It drew the perimeter around the work, put distance and shie","show":"Reviewed explanation, focus 2"},{"at":"It planned Daniel's week on his running dose for the period,","show":"Reviewed explanation, focus 3"},{"at":"And it wrote all of that down in documents that each answer ","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S15-P2"},{"cue":"B1.1-S15-P3","speaker":"Emilia","text":"Then the hall was different from the plan, and the reasoning showed its value. The team held. Daniel reported facts. Bram arranged his hall, the company reassessed its plan, and the start was made to depend on measurements at the first exposure. Every step you have seen in this lesson belongs to one of three things: justifying the work, protecting the people, and checking that the real situation matches the plan.","screen_text":[],"start_visual":"B1Followup S15 closing view 3.","beats":[{"at":"Then the hall was different from the plan, and the reasoning","show":"Reviewed explanation, focus 1"},{"at":"The team held.","show":"Reviewed explanation, focus 2"},{"at":"Bram arranged his hall, the company reassessed its plan, and","show":"Reviewed explanation, focus 3"},{"at":"Every step you have seen in this lesson belongs to one of th","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S15-P3"},{"cue":"B1.1-S15-P4","speaker":"Emilia","text":"Now Bram calls again. A week later, he has another weld in the same hall. He says: you have the plan from last time, the pallets are gone, the hall is quiet, can you come tomorrow and do the same? It sounds simple, and that is exactly why it is a good test of what you have learned.","screen_text":[],"start_visual":"B1Followup S15 closing view 3.","beats":[{"at":"Now Bram calls again.","show":"Reviewed explanation, focus 1"},{"at":"A week later, he has another weld in the same hall.","show":"Reviewed explanation, focus 2"},{"at":"He says: you have the plan from last time, the pallets are g","show":"Reviewed explanation, focus 3"},{"at":"It sounds simple, and that is exactly why it is a good test ","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S15-P4"},{"cue":"B1.1-S15-P5","speaker":"Emilia","text":"That closes the first lesson, and here is what you now carry with you. You know what a radiography company is and why it exists: it finds defects that eyes cannot see, with radiation that needs rules. You know who is who around that radiation: the Agency that licenses and supervises, the recognised organisation and its expert who examine and approve, the physical control service that watches from inside, the head of that service who makes sure every justification was made by someone competent, the company that refuses a job it cannot accept, and the radiographers who do the work and are trained as agents. You know the three questions that come before every job, technique, location and equipment, and that each has to be justified and written down. You know how the people are protected: with a perimeter, distance, shielding, two radiographers, a survey meter for the dose rate at a place, dosimeters for the dose a person receives, and a planning level below the limit. You know which document answers which question. And you know what to do when the real situation differs from the plan: hold, report facts, let each party decide its own part, and verify with measurements before the start.","screen_text":[],"start_visual":"B1Followup S15 closing view 3.","beats":[{"at":"That closes the first lesson, and here is what you now carry","show":"Reviewed explanation, focus 1"},{"at":"You know who is who around that radiation: the Agency that l","show":"Reviewed explanation, focus 2"},{"at":"You know how the people are protected: with a perimeter, dis","show":"Reviewed explanation, focus 3"},{"at":"And you know what to do when the real situation differs from","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S15-P5"},{"cue":"B1.1-S15-P6","speaker":"Emilia","text":"Keep three questions with you for every lesson that follows. What is known? What still has to be checked? And who has to act? In B one point two we stay with the same people and make their responsibilities concrete: what the radiation protection agent checks on the day, what the recognised expert approves and how often, and who receives the report when something is found.","screen_text":[],"start_visual":"B1Followup S15 closing view 3.","beats":[{"at":"Keep three questions with you for every lesson that follows.","show":"Reviewed explanation, focus 1"},{"at":"What is known?","show":"Reviewed explanation, focus 2"},{"at":"And who has to act?","show":"Reviewed explanation, focus 3"},{"at":"In B one point two we stay with the same people and make the","show":"Reviewed explanation, focus 4"}],"clip":"B1.1-S15-P6"}],"interaction":{"id":"B1.1-S15-R01","type":"single_choice","title_visible":"Bram's second request","prompt_spoken_once":"What does Bram's second request start in the company?","situation_visible_text":"A week after the first job, Bram asks for radiography on another weld in the same hall. He offers last week's plan, says the pallets are gone and the hall is quiet, and asks whether the team can come tomorrow and do the same.","options":[{"id":"a","text":"The same three questions as the first time, for this weld: whether radiography is justified, where it belongs, and with what equipment. Then a plan for the hall as it is on the day, verified at the first exposure.","correct":true,"feedback":{"spoken":"Exactly. A second weld is a second request, and a request starts the reasoning, not the exposure. Justification is about this weld: the standard or the risk analysis that applies to it, and the question whether this piece can go to the bunker. Last week's plan is a useful starting point, and it becomes this week's plan when the hall has been checked as it is tomorrow and the first exposure has been measured. Bram's good news about the pallets is welcome. The company checks it itself.","screen":"A new weld starts the three questions again. Last week's plan is a starting point; tomorrow's hall and the first exposure decide."},"clip":"B1.1-S15-R01-a"},{"id":"b","text":"Last week's plan, because the justification was done for this hall and these workpieces. The team arrives, confirms that the pallets are gone and the hall is quiet, and starts with the same perimeter and measurements.","correct":false,"feedback":{"spoken":"You have remembered that the plan was built with care, and much of it will carry over. The part to look at again is the justification, because we must check whether the existing written justification for the type of assignment covers this new weld and these conditions. The standard or risk analysis, the location and the equipment must remain applicable. And a perimeter is confirmed by measuring at the first exposure, at every job, also in a hall the team knows.","screen":"Check that the written justification covers this assignment type and its conditions; verify the perimeter during the first or a test exposure."},"clip":"B1.1-S15-R01-b"},{"id":"c","text":"A visit by the recognised expert, because a second job in the same hall makes it a regular site and the expert approves the arrangement. The team waits for that approval and then uses last week's plan.","correct":false,"feedback":{"spoken":"You are right that the recognised expert has a role, and you will see in the next lesson what the expert approves and when. The decision to accept Bram's request, to justify this weld and to prepare the arrangement lies with the company itself: the head of the physical control service makes sure the justification was made by someone competent, and the team plans and verifies the hall. The expert checks that this system works. Tomorrow's job starts with the company's own three questions.","screen":"The client justifies technique and location; our company checks acceptance, justifies equipment and plans the work. The expert performs the reserved expert tasks."},"clip":"B1.1-S15-R01-c"}],"clip":"B1.1-S15-R01","reviewed_b11":true},"sequence":{"cues_before_interaction":["B1.1-S15-P1","B1.1-S15-P2","B1.1-S15-P3","B1.1-S15-P4"],"interaction_after_cue":"B1.1-S15-P4","interaction_id":"B1.1-S15-R01","post_interaction_cues":[{"cue":"B1.1-S15-P5","condition":"after activity completion"},{"cue":"B1.1-S15-P6","condition":"after activity completion"}]}}]},{"id":"B1.2","title":"The people behind radiation protection","scenes":[{"id":"S01","title":"Welcome back: who does what","paragraphs":[{"cue":"B1.2-S01-P1","text":"Welcome back. In the first lesson you met the people around radiation protection and followed one job from Bram's email to a verified arrangement. Today we stay inside our own company, and we look at the same people from a different side: not who they are, but what each of them is allowed to decide, what they have to be able to show, and who has to hear from whom when something is wrong.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Welcome back.","show":"Focus 1"},{"at":"In the first lesson you met the people around radiation prot","show":"Focus 2"},{"at":"Today we stay inside our own company, and we look at the sam","show":"Focus 3"}],"clip":"B1.2-S01-P1"},{"cue":"B1.2-S01-P2","text":"I'll do that with three messages that arrived on my desk this week, because that is how these questions actually come: not as definitions, but as a colleague who needs an answer before Thursday. One is from our planner, one from the team, and one from Daniel. Each of them looks simple, and each of them hides a decision that belongs to a particular person.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"I'll do that with three messages that arrived on my desk thi","show":"Focus 1"},{"at":"One is from our planner, one from the team, and one from Dan","show":"Focus 2"},{"at":"Each of them looks simple, and each of them hides a decision","show":"Focus 3"}],"clip":"B1.2-S01-P2"},{"cue":"B1.2-S01-P3","text":"By the end of this lesson you will be able to tell apart three things that people easily lump together: doing a check, coordinating it, and approving the procedure behind it. You will know what a training certificate proves and what still has to be shown next to it. You will know exactly who has to hear from a radiographer when a check fails. And you will recognise one role name that sounds like ours and belongs to a different decree. Let's start with the messages.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"By the end of this lesson you will be able to tell apart thr","show":"Focus 1"},{"at":"You will know what a training certificate proves and what st","show":"Focus 2"},{"at":"And you will recognise one role name that sounds like ours a","show":"Focus 3"},{"at":"Let's start with the messages.","show":"Focus 4"}],"clip":"B1.2-S01-P3"}],"sequence":{"cues_before_interaction":["B1.2-S01-P1","B1.2-S01-P2","B1.2-S01-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S02","title":"Three questions on my desk","paragraphs":[{"cue":"B1.2-S02-P1","text":"Here is the first message, from our planner: \"Who is the radiation protection agent on Thursday's worksite?\" The second comes from the team: \"Can we start using the revised version of the pre-use check form for the survey meters and the exposure devices?\" And the third is from Daniel, who joined us a few months ago: \"I passed the agent course. Does that mean I can be the agent on my own now?\"","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Here is the first message, from our planner: \"Who is the rad","show":"Focus 1"},{"at":"Does that mean I can be the agent on my own now?\"","show":"Focus 2"}],"clip":"B1.2-S02-P1"},{"cue":"B1.2-S02-P2","text":"It would be easy to answer all three with \"ask the safety people\". A team works better when it can answer them itself, because behind each message stand three different responsibilities: who performs a task, who has approved the way it is done, and who has to be told when something does not fit. When those three are kept apart, a missed check or an unapproved form is noticed the same day. When they are blurred, it can sit unnoticed for months.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"It would be easy to answer all three with \"ask the safety pe","show":"Focus 1"},{"at":"A team works better when it can answer them itself, because ","show":"Focus 2"},{"at":"When those three are kept apart, a missed check or an unappr","show":"Focus 3"},{"at":"When they are blurred, it can sit unnoticed for months.","show":"Focus 4"}],"clip":"B1.2-S02-P2"},{"cue":"B1.2-S02-P3","text":"Notice also that the three messages are about three different kinds of paper. A completed check form records what one person observed on one day. A procedure describes how a check has to be done, every day, by everyone. A certificate shows that a person passed a test. I keep all three in the same folder, because they belong to the same activity, and I read each of them for what it proves and nothing more. Hold on to that; we come back to it with every message.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Notice also that the three messages are about three differen","show":"Focus 1"},{"at":"A procedure describes how a check has to be done, every day,","show":"Focus 2"},{"at":"A certificate shows that a person passed a test.","show":"Focus 3"},{"at":"Hold on to that; we come back to it with every message.","show":"Focus 4"}],"clip":"B1.2-S02-P3"}],"sequence":{"cues_before_interaction":["B1.2-S02-P1","B1.2-S02-P2","B1.2-S02-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S03","title":"Who may lead the service, and what leading means","paragraphs":[{"cue":"B1.2-S03-P1","text":"You know from the first lesson that our company, as the licence holder, is the operator, and that every operator organises a physical control service. Today I want to show you the conditions behind that, because they decide who may do what. The first condition is about the head of the service. If the operator has a recognised expert in physical control of class one or two on its own staff, it entrusts the leadership of the service to that expert. If it has no such expert, it entrusts the leadership to a member of staff who has followed the basic and the continuing training that the general regulation sets out. That is our situation, and I am that staff member. For a radiography company the industrial radiography decree adds one more condition: the head of the service has three years of relevant experience in radiation protection for industrial radiography.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"You know from the first lesson that our company, as the lice","show":"Focus 1"},{"at":"The first condition is about the head of the service.","show":"Focus 2"},{"at":"If it has no such expert, it entrusts the leadership to a me","show":"Focus 3"},{"at":"For a radiography company the industrial radiography decree ","show":"Focus 4"}],"clip":"B1.2-S03-P1"},{"cue":"B1.2-S03-P2","text":"What does leading the service mean in practice? The regulation gives two things. The head coordinates and organises the proper execution of the tasks given to the service, and the head has direct access to the head of the establishment and to the operator. Put those together and you have my job on a Monday: I make sure every task the service has to do is covered by someone who can actually do it, and when a task cannot be done with the arrangements we have, I take that straight to the people who can change the arrangements. Coordinating is a real power, and it is also a bounded one: I organise the checks, I keep the versions of our procedures apart, I make sure the right people are told. I do not approve the procedures myself, and that is the next condition.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"What does leading the service mean in practice?","show":"Focus 1"},{"at":"The head coordinates and organises the proper execution of t","show":"Focus 2"},{"at":"Put those together and you have my job on a Monday: I make s","show":"Focus 3"},{"at":"I do not approve the procedures myself, and that is the next","show":"Focus 4"}],"clip":"B1.2-S03-P2"},{"cue":"B1.2-S03-P3","text":"The general regulation lists a group of tasks, examining and approving, measuring, evaluating, that are carried out by a recognised expert of class one or two. We have no such expert on our staff, so the regulation requires us to entrust those tasks to a physical control organisation recognised for the purpose, and the contract between our company and that organisation is concluded for exactly this. Notice the two words: the contract is with the organisation, and the organisation provides the expert. That is why an expert from the organisation appears in our files, approves our procedures and visits our installations, and it is also why, when that expert is unavailable, the organisation is still bound to us.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"The general regulation lists a group of tasks, examining and","show":"Focus 1"},{"at":"We have no such expert on our staff, so the regulation requi","show":"Focus 2"},{"at":"Notice the two words: the contract is with the organisation,","show":"Focus 3"},{"at":"That is why an expert from the organisation appears in our f","show":"Focus 4"}],"clip":"B1.2-S03-P3"},{"cue":"B1.2-S03-P4","text":"One more condition closes the picture. In class two and three establishments, the Agency is charged with supervising whether the physical control service carries out its mission properly. So the Agency looks at the service itself: whether it exists, whether it is led by someone who meets the conditions, whether its tasks are done. Keep the whole arrangement in mind as four decisions: the company stays responsible, the head coordinates, the expert from the contracted organisation approves and evaluates, and the Agency supervises the service. The three messages on my desk are each answered by one of those four.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"One more condition closes the picture.","show":"Focus 1"},{"at":"In class two and three establishments, the Agency is charged","show":"Focus 2"},{"at":"Keep the whole arrangement in mind as four decisions: the co","show":"Focus 3"},{"at":"The three messages on my desk are each answered by one of th","show":"Focus 4"}],"clip":"B1.2-S03-P4"}],"sequence":{"cues_before_interaction":["B1.2-S03-P1","B1.2-S03-P2","B1.2-S03-P3","B1.2-S03-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S04","title":"Who is the agent on Thursday?","paragraphs":[{"cue":"B1.2-S04-P1","text":"Now the planner's message: who is the agent on Thursday's worksite? The general regulation says that the operator designates, in each of its establishments and among its own staff, radiation protection agents who carry out the physical control tasks listed for them. For those tasks the agents depend functionally on the service, and they have followed the training for agents. The industrial radiography decree makes that concrete for us: on every worksite the company designates an agent from the industrial radiographers present who belong to its staff and have followed that training.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Now the planner's message: who is the agent on Thursday's wo","show":"Focus 1"},{"at":"The general regulation says that the operator designates, in","show":"Focus 2"},{"at":"For those tasks the agents depend functionally on the servic","show":"Focus 3"},{"at":"The industrial radiography decree makes that concrete for us","show":"Focus 4"}],"clip":"B1.2-S04-P1"},{"cue":"B1.2-S04-P2","text":"So the answer to the planner is a person, chosen for that day. All our radiographers are trained as agents, and for Thursday the company names one of the radiographers who will actually be there. That designation is a company decision about one worksite, and it is recorded in the planning. My part is to make sure the decision has been taken, that it is written down, and that the person named is prepared for that installation and that task. \"Ask the safety department\" is an answer that skips all of that, because the agent has to be someone standing in that hall on Thursday.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"So the answer to the planner is a person, chosen for that da","show":"Focus 1"},{"at":"All our radiographers are trained as agents, and for Thursda","show":"Focus 2"},{"at":"My part is to make sure the decision has been taken, that it","show":"Focus 3"},{"at":"\"Ask the safety department\" is an answer that skips all of t","show":"Focus 4"}],"clip":"B1.2-S04-P2"},{"cue":"B1.2-S04-P3","text":"You heard in the first lesson what the agent checks: that the protection rules and work procedures are followed, that the protective means, the instruments and the dosimeters are available, working and used correctly, and that abnormal situations reach me and the recognised expert. The regulation calls those checks frequent and systematic, and that is the point of the function: a trained person on the spot, looking at everyday protection every time, rather than an occasional visit from outside.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"You heard in the first lesson what the agent checks: that th","show":"Focus 1"},{"at":"The regulation calls those checks frequent and systematic, a","show":"Focus 2"}],"clip":"B1.2-S04-P3"},{"cue":"B1.2-S04-P4","text":"And the list closes with one sentence I want you to carry through this lesson: the agent carries out those tasks on the basis of instructions and procedures approved by a recognised expert in physical control. That sentence connects the agent and the expert without confusing them. The expert has approved how the checking is done. The agent does the checking. When Daniel checks a survey meter against our pre-use procedure and records the result, that record is his observation on that day. The expert's approval of the procedure tells us how a check is to be done; the record tells us whether a particular check was actually done. Each piece of evidence answers its own question, and neither replaces the other.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"And the list closes with one sentence I want you to carry th","show":"Focus 1"},{"at":"The expert has approved how the checking is done.","show":"Focus 2"},{"at":"When Daniel checks a survey meter against our pre-use proced","show":"Focus 3"},{"at":"Each piece of evidence answers its own question, and neither","show":"Focus 4"}],"clip":"B1.2-S04-P4"}],"sequence":{"cues_before_interaction":["B1.2-S04-P1","B1.2-S04-P2","B1.2-S04-P3","B1.2-S04-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S05","title":"The revised check form: who may do what with it?","paragraphs":[{"cue":"B1.2-S05-P1","text":"Now the team's message: can they start using the revised pre-use check form? Here is how the revision came about. Daniel noticed that one sentence on the current form can be read two ways: whether the meter's response is checked before or after the device is positioned. He wrote a clearer sentence and suggested we use it. That is exactly the kind of contribution I want from a radiographer, and I told him so.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Now the team's message: can they start using the revised pre","show":"Focus 1"},{"at":"Here is how the revision came about.","show":"Focus 2"},{"at":"He wrote a clearer sentence and suggested we use it.","show":"Focus 3"},{"at":"That is exactly the kind of contribution I want from a radio","show":"Focus 4"}],"clip":"B1.2-S05-P1"},{"cue":"B1.2-S05-P2","text":"A good suggestion is still a proposal, and the reason is in the sentence from the last scene. The form belongs to a radiation-protection procedure, and the agents do their checks on the basis of procedures approved by the recognised expert. A clearer wording changes what the agents do, so it goes through the same approval as the rest of the procedure. So I ask Daniel to describe the ambiguity with an example, I bring the proposal to our recognised organisation for its expert to examine, and the team keeps using the current version until the revised one has been examined and approved. Nobody on a worksite should have to guess which form applies.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"A good suggestion is still a proposal, and the reason is in ","show":"Focus 1"},{"at":"The form belongs to a radiation-protection procedure, and th","show":"Focus 2"},{"at":"So I ask Daniel to describe the ambiguity with an example, I","show":"Focus 3"},{"at":"Nobody on a worksite should have to guess which form applies","show":"Focus 4"}],"clip":"B1.2-S05-P2"},{"cue":"B1.2-S05-P3","text":"Here is where it gets interesting, and where this week's message actually comes from. The expert who usually handles our files is away for three weeks. The team would like the clearer form now, and two colleagues have offered me a way out. Luc: \"You lead the service, you can sign off a wording change yourself and show it to her when she's back.\" Our director: \"She approved that check last year; a clearer sentence for the same check doesn't need her again.\"","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Here is where it gets interesting, and where this week's mes","show":"Focus 1"},{"at":"The expert who usually handles our files is away for three w","show":"Focus 2"},{"at":"The team would like the clearer form now, and two colleagues","show":"Focus 3"},{"at":"Luc: \"You lead the service, you can sign off a wording chang","show":"Focus 4"}],"clip":"B1.2-S05-P3"},{"cue":"B1.2-S05-P4","text":"Both are trying to help, and both are testing the lines we just drew: what coordinating allows me to do, what approval is and who gives it, and whom our contract is actually with. Think about those three before you answer.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Both are trying to help, and both are testing the lines we j","show":"Focus 1"},{"at":"Think about those three before you answer.","show":"Focus 2"}],"clip":"B1.2-S05-P4"}],"interaction":{"id":"B1.2-S05-Q01","type":"single_choice","reviewed_b12":true,"title_visible":"The expert is away for three weeks","prompt_spoken_once":"What may I do, as head of the service, so that the team gets a clear form as soon as possible?","situation_visible_text":"Daniel's clearer version of the pre-use check form is on the desk, marked PROPOSED. The expert who handles our files is away for three weeks. Luc suggests that Emilia signs off the wording herself. The director says last year's approval of the check covers it.","options":[{"id":"a","text":"Approve the clearer sentence myself for the three weeks, as head of the service, and put it on the expert's desk for confirmation when she returns.","correct":false,"feedback":{"spoken":"You are right that the head of the service has real powers, and keeping the teams working with clear instructions is part of my job. The power to approve a radiation-protection procedure is a different one: the regulation gives examining and approving to a recognised expert, and our contract places those tasks with the recognised organisation. Coordinating means I organise the route to approval and keep the versions apart. A sentence I sign for three weeks would be a form that no expert has approved, in use on a worksite.","screen":"The head coordinates. Approval of a procedure is the expert's task, by contract with the organisation."},"clip":"B1.2-S05-Q01-a"},{"id":"b","text":"Let the team use the clearer form now, because the check itself is unchanged and the expert approved that check last year.","correct":false,"feedback":{"spoken":"You have seen correctly that the content of the check has not changed, and that is why the revision will be examined for approval. What the expert approved last year is the procedure as written, including the sentence Daniel found ambiguous. A new wording changes what the agents do on the spot, so it is part of the procedure and goes through the same examination. Last year's approval covers last year's text; the clearer text gets its own.","screen":"Approval covers the procedure as written. A new wording is examined before it is used."},"clip":"B1.2-S05-Q01-b"},{"id":"c","text":"Keep the current form in use, and send the proposal to the recognised organisation, which has one of its experts examine it; the team uses the clearer form as soon as that approval is in.","correct":true,"feedback":{"spoken":"Exactly. Our contract is with the organisation, and the organisation provides a recognised expert; one expert's holiday does not pause our contract. So I send the proposal to the organisation and ask it to have the examination done, and until the approval is in, the current form stays in use. That is coordinating in full: the proposal moves, the versions stay apart, and the team knows which form applies on every day in between.","screen":"Contract with the organisation; it provides the expert. Current form until the approval is in."},"clip":"B1.2-S05-Q01-c"}],"clip":"B1.2-S05-Q01"},"sequence":{"cues_before_interaction":["B1.2-S05-P1","B1.2-S05-P2","B1.2-S05-P3","B1.2-S05-P4"],"interaction_after_cue":"B1.2-S05-P4","interaction_id":"B1.2-S05-Q01","post_interaction_cues":[]}},{"id":"S06","title":"Training has several different jobs to do","paragraphs":[{"cue":"B1.2-S06-P1","text":"That brings us to Daniel's message: he passed the agent course, so can he be the agent on his own now? To answer that properly I have to separate several things that people lump together as \"training\". They have different purposes and different evidence, and each one has to be there on its own.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"That brings us to Daniel's message: he passed the agent cour","show":"Focus 1"},{"at":"To answer that properly I have to separate several things th","show":"Focus 2"},{"at":"They have different purposes and different evidence, and eac","show":"Focus 3"}],"clip":"B1.2-S06-P1"},{"cue":"B1.2-S06-P2","text":"The first thing Daniel received, before he worked in radiography at all, was our own four-hour initial instruction: how we work, which safety equipment we use and how, dosimeters, survey meters, dose-rate meters, the bunker equipment here and at our clients. The industrial radiography decree wants that given by a radiographer with at least three years of professional experience who knows our installations. Then there is the general information every exposed worker receives before starting at the workstation: the health risks, the rules of good practice, what the signs mean, what to do in an emergency. It is written down, and we refresh it at least once a year. The full list is in the reference reader; what matters for you is to recognise it when it is missing.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"The first thing Daniel received, before he worked in radiogr","show":"Focus 1"},{"at":"The industrial radiography decree wants that given by a radi","show":"Focus 2"},{"at":"It is written down, and we refresh it at least once a year.","show":"Focus 3"},{"at":"The full list is in the reference reader; what matters for y","show":"Focus 4"}],"clip":"B1.2-S06-P2"},{"cue":"B1.2-S06-P3","text":"Next, training for the actual job. On top of that general information, the operator organises training aimed at the person's own workstation or function, and at the devices and substances he uses. It happens on recruitment, when someone changes function, when a work tool is changed or introduced, and when a new technology arrives, and it is repeated as needs require and documented. So when Daniel moves from our X-ray sets to a gamma projector he has not used before, that is a new device, and it asks for its own training. Experience with one device is evidence for that device.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Next, training for the actual job.","show":"Focus 1"},{"at":"On top of that general information, the operator organises t","show":"Focus 2"},{"at":"So when Daniel moves from our X-ray sets to a gamma projecto","show":"Focus 3"},{"at":"Experience with one device is evidence for that device.","show":"Focus 4"}],"clip":"B1.2-S06-P3"},{"cue":"B1.2-S06-P4","text":"Then the agent course, which is what Daniel's message is about. The general regulation sets the floor: a certificate based on a passed knowledge test, proving a theoretical basic training of at least eight hours, supplemented by at least eight hours for class two establishments, together with relevant practical experience in physical control for the type of installation, and continuing training afterwards. The Agency's training regulation fills that in for our kind of company. Because we work with both X-ray devices and sealed sources, our radiographers follow the combined route: twelve hours of basic training and twelve hours of supplementary training covering devices and sources together. The theory is supplemented by practical training or experience in the installation type, the programme is approved by a recognised expert, and class two agents follow at least four hours of continuing training a year. For radiographers the decree places the agent training within three months of entering service, and without it nobody manipulates gamma or X-ray equipment.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Then the agent course, which is what Daniel's message is abo","show":"Focus 1"},{"at":"The Agency's training regulation fills that in for our kind ","show":"Focus 2"},{"at":"Because we work with both X-ray devices and sealed sources, ","show":"Focus 3"},{"at":"For radiographers the decree places the agent training withi","show":"Focus 4"}],"clip":"B1.2-S06-P4"},{"cue":"B1.2-S06-P5","text":"And finally designation. Training makes someone eligible. The company's decision to name him as the agent for a worksite is a separate act, recorded in the planning, taken when the evidence for that person, that installation and that day is there. All of this happens during working time and at the operator's cost. For external workers who come from another company, the division between their employer and us needs its own attention; that is a later lesson, and I keep it out of Daniel's case.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"And finally designation.","show":"Focus 1"},{"at":"Training makes someone eligible.","show":"Focus 2"},{"at":"All of this happens during working time and at the operator'","show":"Focus 3"},{"at":"For external workers who come from another company, the divi","show":"Focus 4"}],"clip":"B1.2-S06-P5"}],"sequence":{"cues_before_interaction":["B1.2-S06-P1","B1.2-S06-P2","B1.2-S06-P3","B1.2-S06-P4","B1.2-S06-P5"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S07","title":"What does Daniel's certificate establish?","paragraphs":[{"cue":"B1.2-S07-P1","text":"Daniel's folder currently holds one document: the certificate from his agent course, based on a passed knowledge test, combined route, twelve plus twelve hours. It is a real achievement and I want him to feel that. Now read it for what it proves. It answers one of the requirements we just walked through: the theory. It says nothing yet about practical training or experience with our projectors, nothing about the workplace instruction for our installations, and nothing about a company decision to designate him. An empty line in the folder is not a failure; it is something I still have to establish.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Daniel's folder currently holds one document: the certificat","show":"Focus 1"},{"at":"Now read it for what it proves.","show":"Focus 2"},{"at":"It answers one of the requirements we just walked through: t","show":"Focus 3"},{"at":"An empty line in the folder is not a failure; it is somethin","show":"Focus 4"}],"clip":"B1.2-S07-P1"},{"cue":"B1.2-S07-P2","text":"So my reply to Daniel is: well done, and here is what we establish next, and who decides. And then the planner's message and Daniel's message meet. Sofia, who was scheduled as the second radiographer on Thursday, is ill. Thursday is a gamma job at a client's site. Luc proposes a solution: \"Daniel has his certificate, he has done three X-ray jobs with me and he was good. Put him down as the agent for Thursday.\"","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"So my reply to Daniel is: well done, and here is what we est","show":"Focus 1"},{"at":"Sofia, who was scheduled as the second radiographer on Thurs","show":"Focus 2"},{"at":"Thursday is a gamma job at a client's site.","show":"Focus 3"},{"at":"Put him down as the agent for Thursday.\"","show":"Focus 4"}],"clip":"B1.2-S07-P2"},{"cue":"B1.2-S07-P3","text":"Luc is not being careless; he is doing what an experienced colleague does, solving Thursday. Read his proposal against the layers of evidence from the last scene: the certificate, the training for the device Daniel will actually use, the workplace instruction, and the designation. Then decide what Thursday needs.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Luc is not being careless; he is doing what an experienced c","show":"Focus 1"},{"at":"Read his proposal against the layers of evidence from the la","show":"Focus 2"},{"at":"Then decide what Thursday needs.","show":"Focus 3"}],"clip":"B1.2-S07-P3"}],"interaction":{"id":"B1.2-S07-Q01","type":"single_choice","reviewed_b12":true,"title_visible":"Can Daniel be the agent on Thursday?","prompt_spoken_once":"Can Daniel be designated as the agent for Thursday, and what decides it?","situation_visible_text":"Thursday is a gamma job at a client's site. Sofia is ill. Daniel has his agent certificate and three X-ray jobs with Luc. Luc proposes to put Daniel down as the agent for Thursday.","options":[{"id":"a","text":"Only if his file also shows the practical training or experience for the projector and the workplace instruction for that equipment; then the designation is a company decision, recorded in the planning.","correct":true,"feedback":{"spoken":"Yes. Luc has given us two true things: the theory is proven by the certificate, and Daniel has practical experience, with X-ray sets. Thursday is a gamma job. The training for the device a person actually uses is a separate layer, and so is the workplace instruction for that equipment; experience with one device is evidence for that device. When those two are in the file for the projector, the company can designate him, and that decision is written in the planning. If they are not, Thursday needs another agent, and Daniel's path continues on a job with Luc on the projector.","screen":"Certificate plus device training plus workplace instruction, then a recorded company decision."},"clip":"B1.2-S07-Q01-a"},{"id":"b","text":"Yes, provided a second experienced radiographer is present, because work outside the bunker is always done by two radiographers anyway.","correct":false,"feedback":{"spoken":"You remembered the rule from the first lesson correctly: outside a bunker there are always at least two industrial radiographers. That rule is about the work. The designation of the agent is about one person: the company names someone who has followed the agent training and who is prepared for that installation. A second radiographer standing next to Daniel adds safety to the job; it does not add the projector training to Daniel's file. Two separate requirements, each shown on its own.","screen":"Two radiographers is a rule for the work. Designation is about the person's own evidence."},"clip":"B1.2-S07-Q01-b"},{"id":"c","text":"Yes: the certificate proves the theory and the three X-ray jobs prove the practice, so the company can designate him for Thursday.","correct":false,"feedback":{"spoken":"You have the two layers Luc named, and you have them right. The layer that is missing is the one Thursday is about. The three jobs were on X-ray sets; Thursday is a gamma projector. Training for the actual device and the workplace instruction for it are separate requirements, documented separately. For an X-ray job, his relevant experience is one part of the evidence; the other training requirements and the company designation still have to be established. For the projector, the file needs its own line first.","screen":"Practice counts for the device it was done on. A gamma job needs the projector evidence."},"clip":"B1.2-S07-Q01-c"}],"clip":"B1.2-S07-Q01"},"sequence":{"cues_before_interaction":["B1.2-S07-P1","B1.2-S07-P2","B1.2-S07-P3"],"interaction_after_cue":"B1.2-S07-P3","interaction_id":"B1.2-S07-Q01","post_interaction_cues":[]}},{"id":"S08","title":"One person, more than one function","paragraphs":[{"cue":"B1.2-S08-P1","text":"Suppose a few weeks have passed. Daniel's practical experience on the projector and his workplace instruction are documented, and the company has designated him as the agent on a worksite. He is now both: the radiographer doing the radiography, and the agent for that site. When he positions the device and makes the exposure, the operational duties of a radiographer apply. When he checks that the protection perimeter is set up as the procedure requires, he is exercising the agent function under the approved procedure. Same person, two functions, and at every decision we can say which one is at work.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Suppose a few weeks have passed.","show":"Focus 1"},{"at":"He is now both: the radiographer doing the radiography, and ","show":"Focus 2"},{"at":"When he positions the device and makes the exposure, the ope","show":"Focus 3"},{"at":"Same person, two functions, and at every decision we can say","show":"Focus 4"}],"clip":"B1.2-S08-P1"},{"cue":"B1.2-S08-P2","text":"The same is true higher up the chart. I am also the company's quality and safety manager, and I have been formally appointed to head the physical control service. The letters on my business card create neither function; the appointments do. In a small company one name appears in several places, and that is legitimate when the conditions for each function are met.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"The same is true higher up the chart.","show":"Focus 1"},{"at":"I am also the company's quality and safety manager, and I ha","show":"Focus 2"},{"at":"The letters on my business card create neither function; the","show":"Focus 3"},{"at":"In a small company one name appears in several places, and t","show":"Focus 4"}],"clip":"B1.2-S08-P2"},{"cue":"B1.2-S08-P3","text":"What we avoid is the shortcut: assuming that a senior title brings every power on the chart with it. A head of service who is also quality manager still has the head's powers and the quality manager's, each within its own appointment. Hold on to that; at the end of this lesson you will meet an appointment with a name very close to ours that belongs to a different decree altogether.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"What we avoid is the shortcut: assuming that a senior title ","show":"Focus 1"},{"at":"A head of service who is also quality manager still has the ","show":"Focus 2"},{"at":"Hold on to that; at the end of this lesson you will meet an ","show":"Focus 3"}],"clip":"B1.2-S08-P3"}],"sequence":{"cues_before_interaction":["B1.2-S08-P1","B1.2-S08-P2","B1.2-S08-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S09","title":"When a check does not pass: who has to hear","paragraphs":[{"cue":"B1.2-S09-P1","text":"Now a situation rather than a document. Daniel is the designated agent on a worksite. Before the first exposure he performs the pre-use check on the survey meter, and the meter fails its function check. The device has not been positioned and no exposure has been made. We know the observation. We do not know the cause, and we have no reason to think anyone has been exposed. That is enough to require action, and it is too little to invent a diagnosis.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Now a situation rather than a document.","show":"Focus 1"},{"at":"Before the first exposure he performs the pre-use check on t","show":"Focus 2"},{"at":"We know the observation.","show":"Focus 3"},{"at":"That is enough to require action, and it is too little to in","show":"Focus 4"}],"clip":"B1.2-S09-P1"},{"cue":"B1.2-S09-P2","text":"In the first lesson you saw the reflex: stop, report, reassess. Today the question is more precise: who exactly has to hear, and in which capacity. Three provisions come together, and each names different people. The general regulation puts a duty on every worker: follow the instructions, never expose yourself unnecessarily, never damage or remove protective means, and report immediately, at least to the physical control service, every irregularity or defect in the protective means. You do not need an agent title for that duty; it belongs to everyone.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"In the first lesson you saw the reflex: stop, report, reasse","show":"Focus 1"},{"at":"Today the question is more precise: who exactly has to hear,","show":"Focus 2"},{"at":"The general regulation puts a duty on every worker: follow t","show":"Focus 3"},{"at":"You do not need an agent title for that duty; it belongs to ","show":"Focus 4"}],"clip":"B1.2-S09-P2"},{"cue":"B1.2-S09-P3","text":"The agent's list adds a task on top: informing the head of the physical control service and the recognised expert of every abnormal situation. And the industrial radiography decree tells radiographers to stop the radiography when safe working is not possible and to report that immediately, with the reason, to their hierarchical superior, to the head of the physical control service and to the client's contact person. So Daniel, in one morning, is three things at once: a worker who reports a defect, an agent who informs the head and the expert, and a radiographer who tells his supervisor and the client. The service is the one address that appears in all three.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"The agent's list adds a task on top: informing the head of t","show":"Focus 1"},{"at":"And the industrial radiography decree tells radiographers to","show":"Focus 2"},{"at":"So Daniel, in one morning, is three things at once: a worker","show":"Focus 3"},{"at":"The service is the one address that appears in all three.","show":"Focus 4"}],"clip":"B1.2-S09-P3"},{"cue":"B1.2-S09-P4","text":"That is why our procedure for this case routes everything through the service, and I tell you its condition so you never have to guess: a failed instrument is reported to the service before any exposure, the service makes sure the expert is informed, and the service decides whether the work continues with a checked replacement. Daniel takes the protective action his instruction assigns, he calls the service on the worksite line, and he keeps the boundary around technical work he is not authorised or competent to do. And he describes what he saw, not what he supposes.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"That is why our procedure for this case routes everything th","show":"Focus 1"},{"at":"Daniel takes the protective action his instruction assigns, ","show":"Focus 2"},{"at":"And he describes what he saw, not what he supposes.","show":"Focus 3"}],"clip":"B1.2-S09-P4"}],"sequence":{"cues_before_interaction":["B1.2-S09-P1","B1.2-S09-P2","B1.2-S09-P3","B1.2-S09-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S10","title":"The spare meter in the van","paragraphs":[{"cue":"B1.2-S10-P1","text":"Keep the facts in mind: Daniel is the designated, prepared agent; the survey meter failed its function check; no exposure has been made; the cause is unknown. Now one more fact. There is a second survey meter in the van, calibrated, and Daniel runs its pre-use check: it passes.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Keep the facts in mind: Daniel is the designated, prepared a","show":"Focus 1"},{"at":"Now one more fact.","show":"Focus 2"},{"at":"There is a second survey meter in the van, calibrated, and D","show":"Focus 3"}],"clip":"B1.2-S10-P1"},{"cue":"B1.2-S10-P2","text":"Luc, on the phone: \"Then there's nothing to report, is there? You've got a working meter, start the job.\" Daniel is not sure. He has a passing meter in his hand and a failed one on the table, and three provisions in his head. What does he do?","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Luc, on the phone: \"Then there's nothing to report, is there","show":"Focus 1"},{"at":"You've got a working meter, start the job.\" Daniel is not su","show":"Focus 2"},{"at":"He has a passing meter in his hand and a failed one on the t","show":"Focus 3"},{"at":"What does he do?","show":"Focus 4"}],"clip":"B1.2-S10-P2"}],"interaction":{"id":"B1.2-S10-Q01","type":"single_choice","reviewed_b12":true,"title_visible":"A working meter, a failed meter","prompt_spoken_once":"Daniel has a working meter and a failed one. What does he do before the first exposure?","situation_visible_text":"The first survey meter failed its function check. The spare meter from the van passes its pre-use check. No exposure has been made. Luc says there is nothing to report and the job can start.","options":[{"id":"a","text":"Start with the spare meter, since its check passed, and note the failed meter in the van's logbook so the service can read it at the next review.","correct":false,"feedback":{"spoken":"The spare meter does solve the measuring problem, and Daniel was right to run its own pre-use check first; that is the agent's task done properly. What stays open is the failed meter. A defect in the protective means is reported immediately, at least to the service, and as agent Daniel also informs the head and the expert. A logbook entry is a record for later; the duty is to report now, so that the failed meter is taken out of use and the question whether the job continues is answered by the people the procedure names.","screen":"The spare solves the measurement. The failed meter is reported now, not at the next review."},"clip":"B1.2-S10-Q01-a"},{"id":"b","text":"Report the failed meter now to the service, Luc and the client's contact person, take it out of use, and start only when the service confirms that the job continues with the checked spare.","correct":true,"feedback":{"spoken":"Yes. Three duties, one phone call. The failed meter is an irregularity in the protective means, so it is reported immediately, at least to the service; as agent Daniel makes sure the head and the expert hear, which our procedure routes through the service; and as the radiographer who halted the work he tells Luc and the client's contact person. The failed meter is tagged out so nobody picks it up. Whether the job continues with the spare is the service's decision under our procedure, and when that confirmation comes, Daniel starts with a meter that passed its own check.","screen":"Report now, tag out the failed meter; the service decides on continuing with the spare."},"clip":"B1.2-S10-Q01-b"},{"id":"c","text":"Stop the job for today, because an irregularity in the protective means means no exposure until the recognised expert has looked at the failed meter.","correct":false,"feedback":{"spoken":"You have the reporting right, and you are right that the expert has to be informed. The step you have added is waiting for her. The expert is informed through the service, and she will look at the meter question; the decision whether today's work continues with a checked replacement is taken under our procedure by the service, not tied to the expert's visit. Stopping the day would be the correct outcome if the service decided it. Here Daniel reports, and lets the people the procedure names decide.","screen":"The expert is informed via the service. Continuing with the spare is the service's decision."},"clip":"B1.2-S10-Q01-c"}],"clip":"B1.2-S10-Q01"},"sequence":{"cues_before_interaction":["B1.2-S10-P1","B1.2-S10-P2"],"interaction_after_cue":"B1.2-S10-P2","interaction_id":"B1.2-S10-Q01","post_interaction_cues":[]}},{"id":"S11","title":"A handover the next person can act on","paragraphs":[{"cue":"B1.2-S11-P1","text":"Daniel has done the right things. Now he has to say them in a way the next person can act on, and that is a skill of its own. A handover in a situation like this has four parts: what was observed, what has been done, who has been contacted and who is still being contacted, and what is still unknown. Four parts, and nobody has claimed a cause or a dose.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Daniel has done the right things.","show":"Focus 1"},{"at":"Now he has to say them in a way the next person can act on, ","show":"Focus 2"},{"at":"A handover in a situation like this has four parts: what was","show":"Focus 3"},{"at":"Four parts, and nobody has claimed a cause or a dose.","show":"Focus 4"}],"clip":"B1.2-S11-P1"},{"cue":"B1.2-S11-P2","text":"Watch what each part does for the receiver. The observation tells me what I am dealing with: a meter that failed its function check. The actions tell me the state of the site: exposure held, device untouched. The contacts tell me who already knows and whom I still have to reach, so nobody is called twice and nobody is forgotten. And the unknown is the most important line of the four: it tells me what the expert has to decide, and it keeps the handover true whatever the cause turns out to be. Those four parts come back in the lesson on abnormal events and reporting, where time limits and the Agency's criteria get their own treatment. Today the point is organisational: a clear handover lets the person with the next responsibility act.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Watch what each part does for the receiver.","show":"Focus 1"},{"at":"The actions tell me the state of the site: exposure held, de","show":"Focus 2"},{"at":"And the unknown is the most important line of the four: it t","show":"Focus 3"},{"at":"Today the point is organisational: a clear handover lets the","show":"Focus 4"}],"clip":"B1.2-S11-P2"},{"cue":"B1.2-S11-P3","text":"Daniel has written three versions of his call to me on the worksite record. All three are polite, all three mention the failed check. Read them as the person who has to act on them, and pick the one you could act on without first calling him back.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Daniel has written three versions of his call to me on the w","show":"Focus 1"},{"at":"All three are polite, all three mention the failed check.","show":"Focus 2"},{"at":"Read them as the person who has to act on them, and pick the","show":"Focus 3"}],"clip":"B1.2-S11-P3"}],"interaction":{"id":"B1.2-S11-R01","type":"single_choice","reviewed_b12":true,"title_visible":"Three versions of the same call","prompt_spoken_once":"Which of the three handovers can I act on as it stands?","situation_visible_text":"Daniel has written three versions of his handover to the head of the service after the failed meter check. The spare meter has passed its check. The service has not yet decided whether the job continues.","options":[{"id":"a","text":"\"Emilia, Daniel at the pipe-rack site. The survey meter failed its function check during the pre-use check; the device is not positioned, no exposure. I've told Luc and the client contact. I'm calling the expert now so she has it first-hand, and I'll call you back with what she says.\"","correct":false,"feedback":{"spoken":"This handover has the observation, the state of the site and two of the contacts, and all of it is true. The one line to change is the route to the expert. The agent's duty is that the head and the expert are informed, and our procedure routes that through the service: Daniel reports to me, and the service makes sure the expert hears, with the facts in one place. A radiographer calling the expert directly leaves me waiting for a decision I am supposed to organise. Same facts, one call fewer, and the handover is complete.","screen":"Facts right; the expert is informed through the service, not by Daniel directly."},"clip":"B1.2-S11-R01-a"},{"id":"b","text":"\"Emilia, Daniel at the pipe-rack site. The first survey meter failed its check; the battery is faulty, so I've swapped to the spare, which passes. Luc and the client contact know. We're ready to start at ten unless you say otherwise.\"","correct":false,"feedback":{"spoken":"This is the handover of someone who wants to solve the problem, and the spare meter's check is exactly right. Two lines go beyond what Daniel knows. \"The battery is faulty\" is a cause nobody has established; the honest line is that the cause is open. And \"we start at ten unless you say otherwise\" lifts the hold himself, where our procedure gives the decision to continue to the service. Keep the observation, label the suspicion as a suspicion, and ask for the decision instead of announcing it.","screen":"Cause stated as fact, hold lifted by the sender. Keep the cause open and ask for the decision."},"clip":"B1.2-S11-R01-b"},{"id":"c","text":"\"Emilia, Daniel at the pipe-rack site. The survey meter failed its function check during the pre-use check; the device is not positioned, no exposure. The failed meter is tagged out; the spare passed its own check. Luc and the client contact know. The cause is unknown. I'm waiting for the service's decision on continuing with the spare.\"","correct":true,"feedback":{"spoken":"Yes. Observed, done, contacted, unknown, and then the question that is mine to answer. I know what happened, I know the site is held and the failed meter is out of circulation, I know who has been told and that the expert is still to be informed by me, and I know the one thing nobody knows yet. I can act on this as it stands: inform the expert, decide on the spare under the procedure, and call Daniel back. A handover like this stays true whether the cause turns out to be the battery, the meter or something else.","screen":"Observed, done, contacted, unknown. The receiver can act without calling back."},"clip":"B1.2-S11-R01-c"}],"layout":"handover_documents","clip":"B1.2-S11-R01"},"sequence":{"cues_before_interaction":["B1.2-S11-P1","B1.2-S11-P2","B1.2-S11-P3"],"interaction_after_cue":"B1.2-S11-P3","interaction_id":"B1.2-S11-R01","post_interaction_cues":[]}},{"id":"S12","title":"A role with a similar name: the delegate for radiological security","paragraphs":[{"cue":"B1.2-S12-P1","text":"One more message arrived this week, and it came through the planner from Bram. His company is preparing for a gamma job on its site, and his question was: \"Who is your delegate for radiological security for the sources you bring to us?\" It is a good question, and it is about a role that sounds like ours and belongs to a different decree. Belgium has a separate royal decree of the seventeenth of March, twenty twenty-four, on the security of radioactive substances and certain nuclear materials; colleagues call it RAMAS. Radiation protection is about controlling exposure. Security is about preventing unauthorised removal, malicious acts and misuse of radioactive substances. The two meet in our work, and their responsibilities are separate.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"One more message arrived this week, and it came through the ","show":"Focus 1"},{"at":"Belgium has a separate royal decree of the seventeenth of Ma","show":"Focus 2"},{"at":"Radiation protection is about controlling exposure.","show":"Focus 3"},{"at":"The two meet in our work, and their responsibilities are sep","show":"Focus 4"}],"clip":"B1.2-S12-P1"},{"cue":"B1.2-S12-P2","text":"Where does the security decree apply? To radioactive substances, whether or not placed in a device, above the exemption levels, in establishments of class one, two or three, and also to radioactive substances used in a mobile installation or in temporary work licensed under the general regulation. That second part is us: our gamma projectors contain sealed sources, and we take them to worksites. An X-ray set contains no radioactive substance, so an X-ray-only activity is outside this decree, even though it produces ionising radiation. What applies to a given source depends on its category under the decree, and that category follows from the licensed radioactive activity and the categorisation rules under the decree, not from a meter reading or from the words \"class two\". For the lowest categories, four and five, only a few of the decree's articles apply.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Where does the security decree apply?","show":"Focus 1"},{"at":"That second part is us: our gamma projectors contain sealed ","show":"Focus 2"},{"at":"An X-ray set contains no radioactive substance, so an X-ray-","show":"Focus 3"},{"at":"For the lowest categories, four and five, only a few of the ","show":"Focus 4"}],"clip":"B1.2-S12-P2"},{"cue":"B1.2-S12-P3","text":"Now the role Bram asked about. Under the security decree the operator appoints, within its establishment or organisation, at least one delegate for radiological security, the ARB, who works for the operator in a durable way, whether or not as an employee. That appointment is subject to the Agency's approval: the Agency may approve it, with or without conditions, or refuse it, looking at the person's qualifications, experience, security training, and his status, position and means within the establishment. The ARB sets up and maintains the radiological security system on behalf of and under the responsibility of the operator, and where relevant does so in consultation with the head of the physical control service. So the ARB and I talk to each other, and we are two different appointments.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Now the role Bram asked about.","show":"Focus 1"},{"at":"Under the security decree the operator appoints, within its ","show":"Focus 2"},{"at":"The ARB sets up and maintains the radiological security syst","show":"Focus 3"},{"at":"So the ARB and I talk to each other, and we are two differen","show":"Focus 4"}],"clip":"B1.2-S12-P3"},{"cue":"B1.2-S12-P4","text":"One duty from that decree you should know even now: anyone who observes a malicious act must immediately inform the operator or the ARB. That belongs to every person, whatever their title. The later lesson on abnormal events shows how security incidents are reported onward. For today, notice how to recognise a request for a separate role, rather than one more routine task for the people you already know.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"One duty from that decree you should know even now: anyone w","show":"Focus 1"},{"at":"That belongs to every person, whatever their title.","show":"Focus 2"},{"at":"The later lesson on abnormal events shows how security incid","show":"Focus 3"},{"at":"For today, notice how to recognise a request for a separate ","show":"Focus 4"}],"clip":"B1.2-S12-P4"}],"sequence":{"cues_before_interaction":["B1.2-S12-P1","B1.2-S12-P2","B1.2-S12-P3","B1.2-S12-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S13","title":"Who answers Bram's question?","paragraphs":[{"cue":"B1.2-S13-P1","text":"Back to Bram's question: who is our delegate for radiological security for the sources we bring to his site? Our planner has drafted a reply, and the draft names Daniel, with the reasoning: he is the designated agent for that worksite and the source will be in his care that day. Luc, reading over the planner's shoulder, suggests my name instead: the ARB consults the head of the physical control service, so it must be me.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Back to Bram's question: who is our delegate for radiologica","show":"Focus 1"},{"at":"Our planner has drafted a reply, and the draft names Daniel,","show":"Focus 2"},{"at":"Luc, reading over the planner's shoulder, suggests my name i","show":"Focus 3"}],"clip":"B1.2-S13-P1"},{"cue":"B1.2-S13-P2","text":"On my desk lie two appointment documents side by side: the planning line that records Daniel's designation as radiation protection agent, and the ARB appointment with its field for the Agency's approval. Same company, two decrees behind the two pieces of paper. Read them, and tell the planner what to answer.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"On my desk lie two appointment documents side by side: the p","show":"Focus 1"},{"at":"Same company, two decrees behind the two pieces of paper.","show":"Focus 2"},{"at":"Read them, and tell the planner what to answer.","show":"Focus 3"}],"clip":"B1.2-S13-P2"}],"interaction":{"id":"B1.2-S13-Q01","type":"single_choice","reviewed_b12":true,"title_visible":"Who is our delegate for radiological security?","prompt_spoken_once":"What does the planner answer Bram?","situation_visible_text":"Bram asks who our delegate for radiological security is for the sources we bring to his site. The planner's draft names Daniel, the designated agent. Luc suggests Emilia, the head of the service. Two appointment documents lie on the desk.","options":[{"id":"a","text":"The name of the person our company appointed as delegate for radiological security, an appointment the Agency has approved; Daniel's designation and my function are different appointments under a different decree.","correct":true,"feedback":{"spoken":"Exactly. Bram asked for a role under the security decree, so the answer is the person who holds that appointment: appointed by the operator, approved by the Agency after looking at qualifications, experience, security training and position. Daniel's designation is a radiation-protection decision for one worksite; my appointment is the head of the service. The ARB consults me where relevant, and that contact is exactly what tells you the two are different people on the chart. The planner looks the name up and answers with that.","screen":"The ARB is a separate appointment, approved by the Agency. Agent and head of service are other appointments."},"clip":"B1.2-S13-Q01-a"},{"id":"b","text":"Daniel, because he is the designated agent for that worksite and the source is in his care on that day.","correct":false,"feedback":{"spoken":"The planner's reasoning starts from something true: on the day, the source is in Daniel's care, and as agent he checks that the protection rules are followed. His designation is a radiation-protection decision, recorded in our planning, for one worksite. The delegate for radiological security is an appointment under the security decree, made by the operator and approved by the Agency on security qualifications. Looking after a source well on Thursday is Daniel's job; being our ARB is somebody's appointment.","screen":"Agent designation is a planning decision for radiation protection. The ARB is an appointment under the security decree."},"clip":"B1.2-S13-Q01-b"},{"id":"c","text":"Emilia, because the delegate for radiological security works in consultation with the head of the physical control service, so the two functions meet in the same person.","correct":false,"feedback":{"spoken":"Luc has spotted a real link: the ARB sets up the security system in consultation with the head of the physical control service, where relevant. Consultation is between two functions, and it works precisely because they are two. Heading the service is an appointment under the general regulation; the ARB is an appointment under the security decree, each with its own conditions and its own approval. The same person can hold both only when both sets of conditions are met and both appointments have been made. In our company they are two people, and the planner names the right one.","screen":"Consultation links two functions; it does not merge them."},"clip":"B1.2-S13-Q01-c"}],"clip":"B1.2-S13-Q01"},"sequence":{"cues_before_interaction":["B1.2-S13-P1","B1.2-S13-P2"],"interaction_after_cue":"B1.2-S13-P2","interaction_id":"B1.2-S13-Q01","post_interaction_cues":[]}},{"id":"S14","title":"Bring the responsibilities together","paragraphs":[{"cue":"B1.2-S14-P1","text":"Let us return to the three messages, and now you can answer them yourself. Who is the agent on Thursday? A radiographer who will actually be there, trained as an agent, prepared for that installation, named by the company and written in the planning. Can the team use the revised check form? When the recognised expert, provided by the organisation we contract, has examined and approved it; until then the current version applies, whoever is on holiday. Can Daniel be the agent on his own? His certificate proves the theory; the training for the device he will use, the workplace instruction and the company's designation are established next to it, and then yes.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Let us return to the three messages, and now you can answer ","show":"Focus 1"},{"at":"A radiographer who will actually be there, trained as an age","show":"Focus 2"},{"at":"When the recognised expert, provided by the organisation we ","show":"Focus 3"},{"at":"His certificate proves the theory; the training for the devi","show":"Focus 4"}],"clip":"B1.2-S14-P1"},{"cue":"B1.2-S14-P2","text":"Underneath all three is the same habit: ask what a piece of evidence establishes and who holds the next decision. Today you have learned the conditions behind the names from the first lesson. Who may lead the service, and that leading means coordinating, with a direct line to the top. That approval of our procedures is the expert's task, placed by contract with an organisation that remains bound to us. That the Agency supervises the service itself. That the agent checks on the basis of approved procedures, and that a record and an approval answer different questions. That training comes in layers, each with its own evidence, and that designation is a separate decision. That when a check fails, three duties name three sets of people, and the service is the address they share. That a handover has four parts: observed, done, contacted, unknown. And that the delegate for radiological security is a different appointment, approved by the Agency, under a different decree.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"Underneath all three is the same habit: ask what a piece of ","show":"Focus 1"},{"at":"That approval of our procedures is the expert's task, placed","show":"Focus 2"},{"at":"That training comes in layers, each with its own evidence, a","show":"Focus 3"},{"at":"And that the delegate for radiological security is a differe","show":"Focus 4"}],"clip":"B1.2-S14-P2"},{"cue":"B1.2-S14-P3","text":"In the next lesson we leave the people for the paperwork that lets a company like ours exist at all: the licence, the bunker and its conformity, commissioning, and what happens when something about the installation changes. You will find the same people there, doing the things we have just taken apart. I'll see you then.","speaker":"Emilia","screen_text":[],"characters":[],"documents":[],"equipment":[],"start_visual":"Reviewed B1.2 scenario","beats":[{"at":"In the next lesson we leave the people for the paperwork tha","show":"Focus 1"},{"at":"You will find the same people there, doing the things we hav","show":"Focus 2"},{"at":"I'll see you then.","show":"Focus 3"}],"clip":"B1.2-S14-P3"}],"sequence":{"cues_before_interaction":["B1.2-S14-P1","B1.2-S14-P2","B1.2-S14-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}}]},{"id":"B1.3","title":"Licence, bunker and commissioning","scenes":[{"id":"S01","title":"Welcome back: from the people to the paperwork","paragraphs":[{"cue":"B1.3-S01-P1","speaker":"Emilia","text":"Welcome back. Last time we separated the people: the company as operator, my coordination, the recognised expert's approvals, the agent's checks, and the Agency looking in from outside. Today we look at the paperwork and the walls that let a company like ours work with radiation at all—and at what each document actually proves.","screen_text":["The installation file — at the control post"],"start_visual":"Emilia at the bunker control post (supplied X-ray control unit image EQ-XRAY-CONTROL-UNIT on the desk) opening the installation file: licence, acceptance report, bunker certificate tabs.","beats":[{"at":"the paperwork and the walls","show":"Installation file opened; bunker gate visible through the control-post window"}],"documents":["DOC-LICENCE","DOC-CERT-BUNKER"],"equipment":["EQ-XRAY-CONTROL-UNIT","EQ-BUNKER-REFERENCE"],"clip":"B1.3-S01-P1"},{"cue":"B1.3-S01-P2","speaker":"Emilia","text":"You will hear the phrase 'everything is approved' on many worksites. By the end of this lesson I want you to be able to replace it with something more precise: what our licence permits, what had to be favourable before an installation could be put into service, what makes a room a bunker in the sense of the law, what effective protection means in the regulation's own terms, and what happens when somebody wants to change something. You will not learn how to test or operate the equipment here. You will learn to say what the evidence supports.","screen_text":["What the licence permits · what was favourable before service · what makes a bunker · effective protection · changes"],"start_visual":"Five tabs of the file named one at a time.","beats":[{"at":"what our licence permits","show":"Tab 1"},{"at":"favourable before an installation","show":"Tab 2"},{"at":"what makes a room a bunker","show":"Tab 3"},{"at":"effective protection","show":"Tab 4"},{"at":"change something","show":"Tab 5"}],"clip":"B1.3-S01-P2"},{"cue":"B1.3-S01-P3","speaker":"Emilia","text":"I will use two installations: our own radiography bunker at the company's premises, and an X-ray cabinet at one of our clients, who inspects small castings in-house. The two sit in different classes, and that difference is a useful way into the licensing rules.","screen_text":["Our bunker (class II) · a client's X-ray cabinet (class III)"],"start_visual":"Bunker exterior image; then a small enclosed X-ray cabinet image (supplied if available, else original render labelled illustration).","beats":[{"at":"our own radiography bunker","show":"Bunker exterior"},{"at":"X-ray cabinet at one of our clients","show":"Cabinet image"}],"equipment":["EQ-BUNKER-REFERENCE"],"clip":"B1.3-S01-P3"}],"sequence":{"cues_before_interaction":["B1.3-S01-P1","B1.3-S01-P2","B1.3-S01-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S02","title":"Our licence: what it is and what it says","paragraphs":[{"cue":"B1.3-S02-P1","speaker":"Emilia","text":"Start with our own company. The general regulation sorts establishments into classes. Class two includes, among others, installations with X-ray devices whose nominal peak voltage exceeds 200 kilovolts, and establishments that hold or use radioactive sources for industrial radiography without being exempt. Both apply to us, so we are a class two establishment, and class two establishments must hold an establishment and operating licence granted by the Agency.","screen_text":["Class II: X-ray > 200 kV · sources for industrial radiography","Establishment and operating licence from the Agency"],"start_visual":"DOC-LICENCE full page (two-page facsimile, page 1): header 'Establishment and operating licence — teaching excerpt'; FANC logo as issuer shown outside the company, credited.","beats":[{"at":"Class two includes","show":"Classification extract thumbnail beside the page"},{"at":"must hold an establishment and operating licence","show":"Licence page 1 overview"}],"documents":["DOC-LICENCE","DOC-REG-EXTRACT"],"equipment":["EQ-FANC-LOGO"],"clip":"B1.3-S02-P1"},{"cue":"B1.3-S02-P2","speaker":"Emilia","text":"How did the company get it? The application went to the Agency after it had been examined and approved by a recognised expert in physical control of class one or two—either an employee of the future operator or an expert from a recognised organisation. For us that was the organisation we still contract. The regulation lists what the application contains; the point for you is that the dossier describes the establishment, its installations, its sources and its practices in enough detail for the Agency to decide.","screen_text":["Application examined and approved by a recognised expert before submission"],"start_visual":"Close-up: 'examined and approved by: recognised expert (organisation)' field, then back to the page.","beats":[{"at":"examined and approved by a recognised expert","show":"Field close-up"},{"at":"in enough detail for the Agency to decide","show":"Back to page"}],"clip":"B1.3-S02-P2"},{"cue":"B1.3-S02-P3","speaker":"Emilia","text":"When I read our licence, I read it for four things. Which installations and equipment it covers. Which sources, with their characteristics, it allows us to hold. Which practices it permits—industrial radiography in our bunker, radiography on clients' sites. And which conditions are attached. You met the first use of this document in the opening lesson: for a type of practice, the licence granted counts as proof of justification. But the licence is not a general permission to do anything with radiation under the company's name. Anything outside its scope is, for the moment, not licensed—and we will come back to that under 'changes'.","screen_text":["Installations · sources · practices · conditions","Proof of justification of the practice — not blanket permission"],"start_visual":"Four field close-ups in turn (installations; sources placeholders; authorised practices; conditions), then full page.","beats":[{"at":"Which installations and equipment","show":"Field: installations/equipment scope"},{"at":"Which sources","show":"Field: sources (placeholders)"},{"at":"Which practices","show":"Field: authorised practices"},{"at":"which conditions","show":"Field: conditions"},{"at":"not a general permission","show":"Full page with 'scope and conditions' label"}],"clip":"B1.3-S02-P3"}],"sequence":{"cues_before_interaction":["B1.3-S02-P1","B1.3-S02-P2","B1.3-S02-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S03","title":"A client's cabinet: the class III route","paragraphs":[{"cue":"B1.3-S03-P1","speaker":"Emilia","text":"Now the client. They want to inspect small castings themselves, so they have bought an enclosed X-ray cabinet. Its device does not exceed 200 kilovolts, it is not one of the installations listed for class two, and it is not exempt from declaration and licensing. Installations with devices that can produce ionising radiation and fall outside the class two list, without being exempt, place the establishment in class three. I am telling you that classification as a fact of this example; in real life it is the expert's dossier, not the look of the cabinet, that settles it.","screen_text":["Class III: devices outside the class II list, not exempt"],"start_visual":"Cabinet image; classification extract thumbnail.","beats":[{"at":"Installations with devices","show":"Extract thumbnail"},{"at":"the expert's dossier, not the look of the cabinet","show":"Text label"}],"documents":["DOC-REG-EXTRACT"],"clip":"B1.3-S03-P1"},{"cue":"B1.3-S03-P2","speaker":"Emilia","text":"For class three the route is different. The Agency grants the establishment and operating licence if the operator submits a declaration that meets the conditions set out in the regulation. That declaration, too, is addressed to the Agency in writing or in printable electronic form after it has been examined and approved by a recognised expert of class one or two—an employee of the future operator or an expert of a recognised organisation. The Agency then rules on the declaration within a set period—thirty calendar days after receiving the waste agency's reasoned opinion where that applies, or sixty calendar days after receiving the dossier, or a longer period that it has to justify.","screen_text":["Declaration (expert-approved) → Agency decision within 30 / 60 days or longer with reasons → licence"],"start_visual":"A chronological strip: 'declaration sent' (receipt) → 'Agency decision' (letter with FANC logo) → 'licence'. Only the first step is filled.","beats":[{"at":"the operator submits a declaration","show":"Receipt at step 1"},{"at":"The Agency then rules","show":"Step 2 outlined, empty"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.3-S03-P2"},{"cue":"B1.3-S03-P3","speaker":"Emilia","text":"So 'we sent the declaration' and 'we hold the licence' are two different statements separated by a decision of the Agency. The client's office manager emails me: 'We sent the declaration for the cabinet last week, so we are licensed now and can start as soon as the installer leaves.'","screen_text":["Sent ≠ licensed"],"start_visual":"The client's email line beside the strip: 'We sent the declaration last week, so we are licensed now.'","beats":[{"at":"The client's office manager emails me","show":"Email line visible"}],"clip":"B1.3-S03-P3"}],"interaction":{"id":"B1.3-I01","type":"single_choice","prompt_spoken_once":"The client writes that the declaration for the X-ray cabinet was sent last week, so they are licensed now. What has the client established?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Chronology: declaration sent (receipt) → Agency decision (pending) → licence.","options":[{"id":"submitted","text":"That the declaration was submitted; the licence is the Agency's decision.","correct":true,"feedback":{"spoken":"Yes. The receipt is real evidence of the first step: for class three the Agency grants the licence if the declaration meets the regulation's conditions, and it rules within a set period. Until the Agency's decision arrives, the client has no licence to read for scope and conditions—so the next step is to wait for that letter, not to start.","screen":"Submission proved; the licence is the Agency's decision, still pending."},"clip":"B1.3-I01-submitted"},{"id":"granted","text":"That the licence has been granted, because the declaration met the conditions.","correct":false,"feedback":{"spoken":"A declaration that meets the conditions is what the Agency needs in order to grant the licence, and an expert-approved declaration is a solid first step. It is not the licence. The Agency has thirty or sixty calendar days, or longer with justification, to rule. The client is reading the decision into the submission; the chronology shows the gap.","screen":"Conditions met → Agency may grant; the decision is a separate step."},"clip":"B1.3-I01-granted"},{"id":"use_on_arrival","text":"That the cabinet may be used as soon as the licence arrives.","correct":false,"feedback":{"spoken":"Even when the licence arrives, something true has happened—the client may build and fit out under it. But the regulation separates that from putting the installation into service. Commissioning needs a fully favourable acceptance that expressly permits it—the next part of the lesson—and the installer cannot supply it.","screen":"Licence → build and fit out; use needs the acceptance."},"clip":"B1.3-I01-use_on_arrival"}],"placement":"Chronological strip stays visible.","clip":"B1.3-I01-prompt"},"sequence":{"cues_before_interaction":["B1.3-S03-P1","B1.3-S03-P2","B1.3-S03-P3"],"interaction_after_cue":"B1.3-S03-P3","interaction_id":"B1.3-I01","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S04","title":"From licence to use: commissioning","paragraphs":[{"cue":"B1.3-S04-P1","speaker":"Emilia","text":"Here is the distinction the client missed, and it applies to our bunker as much as to their cabinet. Following the licence granted for a class two establishment—other than class IIA—or a class three establishment, the operator has the right, under its own responsibility, to build and fit out the installations in accordance with the licence. That is construction. Putting the installation into service is a separate step.","screen_text":["Licence granted → build and fit out (operator's responsibility) → commissioning: a separate step"],"start_visual":"Automatic sequence (plays with the narration, no exercise): licence → construction → commissioning; current point marked.","beats":[{"at":"build and fit out the installations","show":"Construction step current"},{"at":"Putting the installation into service is a separate step","show":"Commissioning step outlined"}],"clip":"B1.3-S04-P1"},{"cue":"B1.3-S04-P2","speaker":"Emilia","text":"The regulation says commissioning may take place only if two things hold. First, where the security decree applies, the acceptance of the radiological security system by the delegate for radiological security is favourable. Second, the acceptance under article 23.1.5 b) point 4—the recognised expert's acceptance—is fully favourable and expressly permits commissioning. And before commissioning, the operator of a class two establishment sends the Agency a document declaring that these conditions have been met.","screen_text":["Where the security decree applies: ARB's security acceptance favourable","Recognised expert's acceptance fully favourable and expressly permitting commissioning","Class II: declaration to the Agency beforehand"],"start_visual":"Conditional branch drawn only where applicable: security acceptance (sealed sources) joins the expert's acceptance; each document arrives at its point.","beats":[{"at":"where the security decree applies","show":"Conditional branch: security acceptance document"},{"at":"the recognised expert's acceptance","show":"Acceptance report document arrives"},{"at":"sends the Agency a document","show":"Declaration document; FANC logo"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.3-S04-P2"},{"cue":"B1.3-S04-P3","speaker":"Emilia","text":"What is an acceptance—an oplevering? The regulation defines it as the check that the installations or practices conform to the radiation regulations, to the establishment and operating licence, and, where there is one, to the safety report. Notice the three reference points. The expert is not asking 'does the equipment work?' in general. She is asking whether what was built matches what was licensed and what the regulation requires. A supplier's delivery note, an installer's sign-off and a manager's enthusiasm answer none of those questions.","screen_text":["Acceptance = conformity check against: the regulation · the licence · the safety report (where there is one)"],"start_visual":"Acceptance report page: three reference points as fields.","beats":[{"at":"The regulation defines it","show":"Acceptance page"},{"at":"Notice the three reference points","show":"Three fields highlighted in turn"}],"clip":"B1.3-S04-P3"},{"cue":"B1.3-S04-P4","speaker":"Emilia","text":"So for the client's cabinet the order is: licence from the Agency, construction and installation, the recognised expert's fully favourable acceptance expressly permitting commissioning, then use. For our bunker it was the same, with the security acceptance added because our projectors hold sealed sources. I keep the acceptance report with the licence, because together they are the answer to 'may this installation be used at all?'","screen_text":["Cabinet: licence → installation → expert's acceptance → use","Our bunker: + security acceptance (sealed sources)"],"start_visual":"Sequence shown twice: cabinet (no branch); bunker (with branch); installation file tabs 'licence' and 'acceptance' together.","beats":[{"at":"for the client's cabinet the order is","show":"Cabinet sequence"},{"at":"For our bunker it was the same","show":"Bunker sequence with security branch"},{"at":"together they are the answer","show":"File tabs together"}],"clip":"B1.3-S04-P4"}],"sequence":{"cues_before_interaction":["B1.3-S04-P1","B1.3-S04-P2","B1.3-S04-P3","B1.3-S04-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S05","title":"What makes a room a bunker","paragraphs":[{"cue":"B1.3-S05-P1","speaker":"Emilia","text":"Now the walls. In the industrial radiography decree a bunker is not any thick-walled room. It is a whole consisting of four parts: an enclosure—with or without a roof—whose walls shield the ionising radiation; various safety devices; lockable doors or gates; and a control post outside the enclosure holding the remote control of each radiography device. And one more sentence: a bunker has a valid conformity certificate drawn up by a recognised expert in physical control. Our company must make sure that the bunkers in which it carries out radiography have such a valid certificate—our own and any client's.","screen_text":["Enclosure with shielding walls (with or without roof)","Safety devices","Lockable doors or gates","Control post outside","Valid conformity certificate — recognised expert"],"start_visual":"Roofed bunker exterior from the owner's architectural reference (EQ-BUNKER-REFERENCE: block enclosure, mono-pitch roof, sliding gate with pedestrian door) → brief deliberate cutaway (roof lifts/fades 2 s) → control post → back to exterior. Labels at their phrases.","beats":[{"at":"whole consisting of four parts","show":"Exterior view, roof clearly visible"},{"at":"with or without a roof","show":"Cutaway: roof lifts; interior visible, nobody inside, no emission"},{"at":"various safety devices","show":"Roof returns; entrance hardware in frame"},{"at":"lockable doors or gates","show":"Gate and pedestrian door"},{"at":"control post outside","show":"Control post with EQ-XRAY-CONTROL-UNIT"},{"at":"valid conformity certificate","show":"DOC-CERT-BUNKER thumbnail at the control post"}],"documents":["DOC-CERT-BUNKER"],"equipment":["EQ-BUNKER-REFERENCE","EQ-XRAY-CONTROL-UNIT"],"clip":"B1.3-S05-P1"},{"cue":"B1.3-S05-P2","speaker":"Emilia","text":"'Various safety devices' is where the bells and buttons live. The Agency's technical regulation on safety means in industrial radiography sets the minimum a bunker has to have, and the safety logic of each bunker follows from its own risk analysis. Let me show you the hardware and the state each item is for. While a door or gate is closing, a signal sounds at the control post and inside the bunker—it begins with the closing, not after it, so that anyone inside or near the door is warned while there is still time. A visual signal comes on when, and only when, ionising radiation is present in the exposure room, visible from every point inside and at every entrance. While the set is emitting, access to the room is locked. A locked door must never trap a person, so at least one door or gate is a clearly marked evacuation exit that can always be opened by hand from the inside. At the entrance hangs a description of what the audible and visual alarms mean, and there is emergency lighting. And because this bunker is used with an X-ray set, two more things: a device enforces a safety walk-round before an exposure—nobody left behind—ending with the doors locked, within a time the recognised expert set; and there are emergency stops inside the room, placed so that one can be reached from any position without crossing the direct beam, and one at the control post.","screen_text":["Sounder: while a door or gate is closing","Lamp: when—and only when—radiation is present","Access locked while emitting","Evacuation exit opens by hand from inside","Alarm meaning described at the entrance · emergency lighting","X-ray: enforced walk-round · emergency stops inside (off the beam) and at the control post"],"start_visual":"Hardware close-ups in idle state, each with a separate labelled STATE ILLUSTRATION inset (no person inside, never a live emission with people): gate + sounders; entrance and inside lamps; gate lock; evacuation exit handle; alarm-meaning sign; emergency luminaire; walk-round acknowledgement point; emergency stops (inside, off the beam axis; control post).","beats":[{"at":"While a door or gate is closing","show":"Inset: gate in motion → sounders lit at control post and inside"},{"at":"A visual signal comes on when","show":"Inset: radiation present → lamps on; room empty"},{"at":"access to the room is locked","show":"Inset: bolt engaged"},{"at":"opened by hand from the inside","show":"Close-up: marked evacuation exit and inside handle"},{"at":"description of what the audible and visual alarms mean","show":"Close-up: sign at the entrance (sample rows)"},{"at":"emergency lighting","show":"Close-up: emergency luminaire"},{"at":"a device enforces a safety walk-round","show":"Inset: walk-round not completed in time → exposure cannot start"},{"at":"emergency stops inside the room","show":"Close-ups: inside stop off the beam axis; control-post stop"}],"equipment":["EQ-BUNKER-REFERENCE","EQ-XRAY-CONTROL-UNIT"],"clip":"B1.3-S05-P2"},{"cue":"B1.3-S05-P3","speaker":"Emilia","text":"The certificate turns those parts into proof. The recognised expert checked that the safety requirements are met, and the certificate also says which isotopes and activities, which X-ray voltages and which working configurations are allowed in here. It is valid for ten years at most, it is adapted when the bunker changes, and a copy goes to the Agency.","screen_text":["Certificate: description · permitted equipment and configurations · safety-logic reference · valid max. 10 years"],"start_visual":"DOC-CERT-BUNKER full page → close-up on permitted equipment/configuration fields (placeholders) → validity line → back to page.","beats":[{"at":"The certificate turns those parts into proof","show":"Full page"},{"at":"which isotopes and activities","show":"Close-up: permitted equipment/configurations (placeholders)"},{"at":"valid for ten years at most","show":"Validity line"}],"documents":["DOC-CERT-BUNKER"],"clip":"B1.3-S05-P3"},{"cue":"B1.3-S05-P4","speaker":"Emilia","text":"The decree also says where radiography takes place, and this is one of the activity-specific rules you are expected to know. Radiography of movable workpieces that fit within one cubic metre and weigh less than 500 kilograms is always carried out in a bunker. Both conditions together—size and weight. Larger or heavier workpieces are preferably radiographed in a bunker; if that is not reasonably feasible, then after a risk analysis by the client and by our company it may be done on the client's site in an irradiation infrastructure—fixed shielding intended to protect against the radiation. And if neither a bunker nor an irradiation infrastructure is reasonably feasible, radiography may, again after a risk analysis by both, be carried out elsewhere. The Agency can prohibit radiography at a location whose justification it finds insufficient.","screen_text":["Movable, within 1 m³ and under 500 kg → always in a bunker","Larger/heavier: bunker preferred → irradiation infrastructure → another place, after risk analyses","The Agency may prohibit a location"],"start_visual":"Small casting on the exposure table (interior, no emission); then the three tiers as short lines; FANC logo at 'The Agency can prohibit'.","beats":[{"at":"fit within one cubic metre","show":"Casting on the table"},{"at":"Larger or heavier workpieces","show":"Tier lines"},{"at":"The Agency can prohibit","show":"FANC logo"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.3-S05-P4"},{"cue":"B1.3-S05-P5","speaker":"Emilia","text":"You met the client's written justification of the location in the opening lesson. Here is its companion: on the basis of its own risk analysis, the client gives us the information we need to do our risk analysis for radiography at that place. So when a client says 'use our bunker', I want to see the certificate, and when a client says 'do it in the hall', I want to see the written reasoning for why neither a bunker nor an irradiation infrastructure is reasonably feasible for that workpiece, and the information for the risk analysis.","screen_text":["Client's bunker → certificate","Client's hall → documented assessment of both options + risk-analysis information"],"start_visual":"Two document thumbnails: DOC-CERT-BUNKER and DOC-LOC-JUST (from B1.1 S07).","beats":[{"at":"I want to see the certificate","show":"Certificate thumbnail"},{"at":"I want to see the written reasoning","show":"Location justification thumbnail"}],"documents":["DOC-CERT-BUNKER","DOC-LOC-JUST"],"clip":"B1.3-S05-P5"}],"sequence":{"cues_before_interaction":["B1.3-S05-P1","B1.3-S05-P2","B1.3-S05-P3","B1.3-S05-P4","B1.3-S05-P5"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S06","title":"Is it a bunker?","paragraphs":[{"cue":"B1.3-S06-P1","speaker":"Emilia","text":"At a new client's site everyone calls a concrete room at the back of the hall 'the bunker'. It has a heavy door and a control desk outside. The site supervisor says: 'It was built for this; the walls are half a metre thick.'","screen_text":["Concrete room · heavy door · control desk outside · 'half a metre thick'"],"start_visual":"Client's concrete room (original render, labelled illustration): heavy door, control desk outside; no lamp, no alarm sign, no certificate visible.","beats":[{"at":"everyone calls a concrete room","show":"Room view"},{"at":"the walls are half a metre thick","show":"Supervisor's line as a speech line; no dimension drawn"}],"clip":"B1.3-S06-P1"}],"interaction":{"id":"B1.3-I02","type":"single_choice","prompt_spoken_once":"Before I plan small workpieces in that room, what has to be true for it to be a bunker in the sense of the decree?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Concrete room with a heavy door and a control desk outside; the supervisor says the walls are half a metre thick.","options":[{"id":"certificate","text":"It has the required parts and safety features, and a valid conformity certificate drawn up by a recognised expert.","correct":true,"feedback":{"spoken":"Right. The decree describes a bunker by its parts—shielding enclosure, safety devices, lockable doors or gates, a control post outside—and then adds the certificate, drawn up by a recognised expert, that says those parts and the safety requirements were checked. With the certificate in hand I can plan the work; without it, the first thing I ask the client for is exactly that.","screen":"Parts + safety features + valid certificate from a recognised expert."},"clip":"B1.3-I02-certificate"},{"id":"walls","text":"The walls are thick enough that a meter reads nothing outside the room.","correct":false,"feedback":{"spoken":"That reading is useful: it tells me something about the shielding on the day it was taken. What it cannot tell me is whether the door locks during an exposure, whether someone inside can get out, or whether the set can be stopped from both sides—and none of that is in a meter. The certificate covers the whole set of features, which is why it is the thing I ask for.","screen":"A reading is one observation; the certificate covers all the features."},"clip":"B1.3-I02-walls"},{"id":"licence","text":"The room is listed as a radiography room in the client's licence.","correct":false,"feedback":{"spoken":"The licence is real evidence of something else: it tells me what the client is permitted to do and where. It answers 'may radiography happen here at all?'. The bunker definition asks a narrower question—does this enclosure have the required features, confirmed by a recognised expert's certificate? I need both documents, for two different questions.","screen":"Licence = permitted practice; certificate = this enclosure's conformity."},"clip":"B1.3-I02-licence"}],"placement":"Room view stays visible.","clip":"B1.3-I02-prompt"},"sequence":{"cues_before_interaction":["B1.3-S06-P1"],"interaction_after_cue":"B1.3-S06-P1","interaction_id":"B1.3-I02","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S07","title":"Effective protection: the regulation's own five factors","paragraphs":[{"cue":"B1.3-S07-P1","speaker":"Emilia","text":"Here is where the paperwork meets the physics. Article 27 says that undertakings must put protective means in place that make it possible to ensure effective protection as defined in the regulation. Devices and installations that do not, or no longer, meet the regulation's provisions must be taken out of use until the identified deficiencies have been corrected. Keep that second sentence; it comes back shortly.","screen_text":["Protective means → effective protection","No longer compliant → out of use until corrected"],"start_visual":"ARBIS 27 extract thumbnail; control post view.","beats":[{"at":"Article 27 says","show":"Extract thumbnail"},{"at":"taken out of use","show":"Label 2"}],"documents":["DOC-REG-EXTRACT"],"clip":"B1.3-S07-P1"},{"cue":"B1.3-S07-P2","speaker":"Emilia","text":"The article then names five safety factors as fundamental, used alone or together. Protection by distance: the measures needed to prevent people from unintentionally approaching the sources. In our work that is the protection perimeter, the controlled area marked out around an exposure. Protection by shielding the sources: in our trade the projector's shielded container and the collimator are shielding at work, and the regulation adds a condition for the case where shielding is the only protective means relied on—you will find it in the reference reader. Protection of rooms by screens, with any openings in the screens themselves protected: the bunker's walls and door. Protection by preventing contamination, a list of principles for unsealed and sealed sources alike—sealed sources preferred, the smallest quantities, no spreading, no loss or theft, and an accurate inventory that lets every source be located at any moment. And protection by limiting exposure time: the speed of the source movement, the speed of the operation, or the limitation of working time and the rotation of staff.","screen_text":["Distance — perimeter","Shielding — projector container, collimator","Screens — bunker walls and door","Preventing contamination — sealed sources, inventory","Time — exposure planning"],"start_visual":"One concrete visual per factor with a short label: perimeter kit at a worksite; gamma projector image (container, collimator); bunker wall and door; the source inventory sheet at the store; an exposure planning line. No folder or sun icons.","beats":[{"at":"Protection by distance","show":"EQ-PERIMETER-KIT at a worksite"},{"at":"Protection by shielding the sources","show":"EQ-GAMMA-PROJECTOR close-up"},{"at":"Protection of rooms by screens","show":"Bunker wall and door"},{"at":"Protection by preventing contamination","show":"Inventory sheet (placeholders)"},{"at":"protection by limiting exposure time","show":"Exposure planning line, no values"}],"equipment":["EQ-PERIMETER-KIT","EQ-GAMMA-PROJECTOR","EQ-BUNKER-REFERENCE"],"clip":"B1.3-S07-P2"},{"cue":"B1.3-S07-P3","speaker":"Emilia","text":"One more sentence from the same article, and it should shape how you think about your personal dosimeter. In the study and design of protective means, and in their use in existing installations, priority goes to collective protective means that limit the radiation and contamination level, rather than to individual protective means. The bunker, the interlocks and the perimeter protect everyone present; the dosimeter records what one person received. The dosimeter matters, but it is not where protection starts.","screen_text":["Collective means first; the dosimeter records"],"start_visual":"Bunker, gate lock and perimeter in one view; then Daniel's EPD close-up.","beats":[{"at":"priority goes to collective protective means","show":"Collective means view"},{"at":"the dosimeter records","show":"EPD close-up, left chest"}],"equipment":["EQ-EPD-LEFT-CHEST"],"clip":"B1.3-S07-P3"},{"cue":"B1.3-S07-P4","speaker":"Emilia","text":"So when I ask 'is the protection effective?' about an installation, I am not asking for a feeling. I am asking which of these factors the design relies on, whether each still works as accepted, and whether the collective means come first. That is also how the recognised expert's risk analysis and acceptance are organised, and why the agent's checks look at protective means, instruments and dosimeters together.","screen_text":["Which factors · still working as accepted · collective first"],"start_visual":"Emilia to camera.","beats":[{"at":"is the protection effective","show":"Three short labels"}],"clip":"B1.3-S07-P4"}],"sequence":{"cues_before_interaction":["B1.3-S07-P1","B1.3-S07-P2","B1.3-S07-P3","B1.3-S07-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S08","title":"A failed function and a missing record are different facts","paragraphs":[{"cue":"B1.3-S08-P1","speaker":"Emilia","text":"Now apply article 27's second sentence. Our bunker's door interlock is one of its safety devices. During the periodic test under the approved procedure, the interlock fails to stop the exposure sequence when the door is opened. That is a protective function that no longer meets the requirements, so the installation goes out of use until the deficiency is corrected. The licence does not make the result disappear, and neither does the week's schedule. The failed test is reported immediately—you know the duties from last lesson—and the correction is confirmed through the procedure and the expert's involvement, not by somebody saying 'it should be fine now'.","screen_text":["Case 1 — interlock FAILED its test → out of use until corrected → reported immediately"],"start_visual":"Case 1 state (red border + the words 'DEFECT ESTABLISHED'): control post; gate bolt shown not engaging in a labelled state illustration; Daniel at the control post, nobody inside; 'OUT OF USE' card.","beats":[{"at":"the interlock fails to stop the exposure sequence","show":"State illustration: bolt not engaging"},{"at":"goes out of use until the deficiency is corrected","show":"'OUT OF USE until corrected' card"},{"at":"reported immediately","show":"Daniel with phone"}],"characters":["Daniel"],"clip":"B1.3-S08-P1"},{"cue":"B1.3-S08-P2","speaker":"Emilia","text":"Here is a different fact that deserves the same care in language. This month's interlock test record cannot be found. We know that evidence is missing. We do not know whether the test was done and filed elsewhere, whether it was forgotten, or whether a fault was found and not written up. I will not fill in a pass because last month looked fine, and I will not report a defective interlock because a folder is incomplete. Both replace an open question with an invented answer.","screen_text":["Case 2 — this month's record NOT FOUND → result not established"],"start_visual":"Case 2 state (different border and words): DOC-CONTROL-TEST-PROGRAMME page, this month's line empty, last month's complete; NOT ESTABLISHED badge.","beats":[{"at":"This month's interlock test record cannot be found","show":"Programme page: empty line"},{"at":"I will not fill in a pass","show":"Last month's line visible, not copied"},{"at":"I will not report a defective interlock","show":"No defect card; NOT ESTABLISHED badge"}],"documents":["DOC-CONTROL-TEST-PROGRAMME"],"clip":"B1.3-S08-P2"},{"cue":"B1.3-S08-P3","speaker":"Emilia","text":"In our procedure, the relevant satisfactory test has to be established before the bunker is used again. Until it is, use is held—not because a defect has been proven, but because the required evidence is not there. Notice how much more useful the handover becomes when we name the actual gap: 'the result is not established; use is held under the procedure; please help locate or redo the test'. That gives the service something specific to do and leaves room for the facts to change when the record turns up.","screen_text":["Use HELD under the procedure — because the evidence is not there"],"start_visual":"Hold card DOC-HOLD-CARD placed at the control post (large held-work state); Emilia explains.","beats":[{"at":"use is held","show":"Hold card placed; HELD badge"},{"at":"please help locate or redo the test","show":"Hold card reason line"}],"documents":["DOC-HOLD-CARD"],"clip":"B1.3-S08-P3"},{"cue":"B1.3-S08-P4","speaker":"Emilia","text":"Here is how the second case went on that morning. Sofia, from the late shift, said she ran the test on Friday and that it passed, and simply never wrote it up. That is useful, and it is still not a record. My decision as head of service, under the procedure, was that the test is repeated, witnessed by Luc as supervisor, and the actual result is entered—result, date, both names. If it is satisfactory, I review the entry and only then does the hold come off. If it is not, we are in the first case, with a defect to correct. Nothing is released by memory or by a phone call; the record is.","screen_text":["Late-shift account ≠ record","Repeat the test under the procedure → record the actual result → head of service reviews → then the hold is lifted (or case 1)"],"start_visual":"Sofia gives her account at the control post (supplied pose); Luc and Daniel at the gate preparing the witnessed repeat; the programme page shows a new, still-empty line; the hold card stays. The outcome is deliberately not shown.","beats":[{"at":"Sofia, from the late shift","show":"Sofia at the control post"},{"at":"witnessed by Luc","show":"Luc at the gate"},{"at":"the actual result is entered","show":"Programme page: new empty line"},{"at":"the hold come off","show":"Hold card remains (no release shown)"}],"documents":["DOC-CONTROL-TEST-PROGRAMME","DOC-HOLD-CARD"],"characters":["Sofia","Luc","Daniel"],"clip":"B1.3-S08-P4"}],"sequence":{"cues_before_interaction":["B1.3-S08-P1","B1.3-S08-P2","B1.3-S08-P3","B1.3-S08-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]},"status_badges":[{"kind":"fact","label":"Fact (case 1)","explanation":"The interlock did not stop the exposure sequence during its periodic test: a protective function that no longer meets the requirements."},{"kind":"held","label":"Held (case 2)","explanation":"Bunker use is held under the company procedure because this month's satisfactory test is not established — not because a defect has been proven."},{"kind":"not_established","label":"Not established (case 2)","explanation":"Whether the test was done, filed elsewhere, forgotten, or failed and not written up is unknown; a colleague's recollection is not a record."}]},{"id":"S09","title":"Say what is known","paragraphs":[{"cue":"B1.3-S09-P1","speaker":"Emilia","text":"You are handing over the missing-record case, not the failed-test case. The hold card and the empty line are in front of you; nothing is known about the function either way.","screen_text":["Missing-record case — use held"],"start_visual":"Case 2 state with the hold card large.","beats":[{"at":"the missing-record case","show":"Hold card and empty line"}],"clip":"B1.3-S09-P1"}],"interaction":{"id":"B1.3-I03","type":"single_choice","prompt_spoken_once":"This month's interlock test record for the bunker cannot be found. What do you report?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Hold card: bunker use on hold — this month's interlock test result not established. Last month's line: satisfactory.","options":[{"id":"not_established","text":"The test result is not established; use is held under the procedure.","correct":true,"feedback":{"spoken":"Exactly. That says what is known, what has been done and what still needs resolving, and it tells the service what to do: locate the record if the test was done, or repeat the test under the procedure if it was not. It leaves room for the facts to change—and until then the bunker stays held, because the required evidence is not there.","screen":"Known · done · open — the service locates or repeats the test; hold stays."},"clip":"B1.3-I03-not_established"},{"id":"defective","text":"The interlock is defective and must be repaired before use.","correct":false,"feedback":{"spoken":"A missing record is an evidence gap, and the useful report names it as one. If you report a defect nobody has observed, the service goes after the wrong problem, and when the record turns up the report has to be withdrawn. The accurate line is 'not established; use held under the procedure'—which still keeps the bunker out of use until it is resolved.","screen":"No observed defect; report the gap, keep the hold."},"clip":"B1.3-I03-defective"},{"id":"last_month","text":"Last month's test passed, so the bunker can still be used.","correct":false,"feedback":{"spoken":"Last month's record is a true statement about last month, and it is right that it is in the programme. What the procedure asks for before use is this month's satisfactory test, and a remembered pass does not supply it. Reporting the old result as today's evidence removes the open condition; the accurate report keeps it there.","screen":"Last month answers last month; this month's test is what the procedure requires."},"clip":"B1.3-I03-last_month"}],"placement":"Hold card and programme page stay visible.","clip":"B1.3-I03-prompt"},"sequence":{"cues_before_interaction":["B1.3-S09-P1"],"interaction_after_cue":"B1.3-S09-P1","interaction_id":"B1.3-I03","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S10","title":"When something changes","paragraphs":[{"cue":"B1.3-S10-P1","speaker":"Emilia","text":"Installations do not stay as they were licensed. A team wants a second projector of a different model, a client asks us to bring a higher-energy X-ray set, the recognised organisation we contract changes. The general regulation says that every change to the establishment which the Agency considers to have a potential impact on radiation protection or safety must be declared to the Agency—and, for class two and three, every change with a potential impact on the security of radioactive substances. The Agency then decides whether the change requires a licence application under the relevant procedure, and for class two and three it may waive some formalities when the change does not move the establishment into a higher class.","screen_text":["Changes with potential impact → declared to the Agency → Agency decides"],"start_visual":"Change register DOC-CHANGE-REGISTER page; three example change lines appear; FANC logo at 'declared to the Agency'.","beats":[{"at":"Installations do not stay as they were licensed","show":"Register page"},{"at":"must be declared to the Agency","show":"FANC logo outside"}],"documents":["DOC-CHANGE-REGISTER"],"equipment":["EQ-FANC-LOGO"],"clip":"B1.3-S10-P1"},{"cue":"B1.3-S10-P2","speaker":"Emilia","text":"The Agency has set the criteria in a technical regulation on the declaration of changes, in force since 3 March 2022. For class two and three establishments other than class IIA it does two things. First, our physical control service keeps a list of all changes with a potential impact on radiation protection or radiological safety—for each one a short description, the approvals already given and still needed, and the status of implementation. That list is mine to keep, and it is where every proposal goes first. Second, certain changes must be declared to the Agency beforehand. Among them: using a radiation source, or holding a radioactive substance, in an installation not licensed for it; carrying out a practice not licensed; other changes that fall outside the inventory in the licence; the definitive cessation of a practice with sources; the departure of an internal recognised expert; and a change of the recognised organisation that provides our experts.","screen_text":["Service keeps the change list: description · approvals given / needed · status","Some changes: prior declaration"],"start_visual":"Close-up on the register columns, then the 'prior declaration' marker on the relevant lines only (not every line).","beats":[{"at":"keeps a list of all changes","show":"Register columns"},{"at":"certain changes must be declared","show":"Marker on the lines that need prior declaration; other lines unmarked"}],"clip":"B1.3-S10-P2"},{"cue":"B1.3-S10-P3","speaker":"Emilia","text":"The declaration is approved and countersigned by a recognised expert in physical control—except for the purely organisational criteria such as the expert's departure, the change of organisation, an address change without moving, or a name change of the legal entity. It gives the establishment's unique number and a description of the change, together with the updated parts of the licence dossier that the change affects. And the Agency informs the operator and the head of the physical control service of its decision. So nobody in our company—not the team, not me, not the supplier—approves a change of this kind. We recognise it, record it, bring in the expert and declare it; the Agency decides.","screen_text":["Declaration approved and countersigned by the recognised expert (except organisational criteria)","Agency informs operator and head of service"],"start_visual":"Declaration outline: expert countersignature field (role), unique establishment number placeholder; Agency decision letter outline.","beats":[{"at":"approved and countersigned by a recognised expert","show":"Countersignature field"},{"at":"except for the purely organisational criteria","show":"Lines without that field"},{"at":"the Agency decides","show":"Decision letter outline with FANC logo"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.3-S10-P3"}],"sequence":{"cues_before_interaction":["B1.3-S10-P1","B1.3-S10-P2","B1.3-S10-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S11","title":"A new X-ray set","paragraphs":[{"cue":"B1.3-S11-P1","speaker":"Emilia","text":"Our team proposes buying an additional X-ray set of a type that is not in our licence's equipment inventory, to use in the bunker for thicker sections. Everyone agrees it would be useful.","screen_text":["Proposed: additional X-ray set — not in the licence inventory"],"start_visual":"Supplied X-ray generator image EQ-XRAY-GENERATOR beside the licence's equipment-inventory field (placeholders) where this type is absent; register line 'proposal'.","beats":[{"at":"additional X-ray set","show":"Generator image"},{"at":"not in our licence's equipment inventory","show":"Inventory field close-up: type absent"}],"documents":["DOC-LICENCE","DOC-CHANGE-REGISTER"],"equipment":["EQ-XRAY-GENERATOR"],"clip":"B1.3-S11-P1"}],"interaction":{"id":"B1.3-I04","type":"single_choice","prompt_spoken_once":"The team wants to add an X-ray set that is not in our licence's equipment inventory. What happens before it can be used?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Licence inventory excerpt: this type absent. Change register: 'proposal'.","options":[{"id":"declare","text":"It is declared to the Agency beforehand, approved and countersigned by the recognised expert.","correct":true,"feedback":{"spoken":"Yes. Using a source that can emit ionising radiation in an installation not licensed for it is one of the changes that must be declared beforehand; the declaration is approved and countersigned by a recognised expert, and the Agency decides whether a licence application is needed. Until then the set is a proposal on our change list—that line stays as it is.","screen":"Prior declaration, expert countersignature, Agency decision; proposal until then."},"clip":"B1.3-I04-declare"},{"id":"list_only","text":"Emilia records it on the service's change list, and the set can then be used.","correct":false,"feedback":{"spoken":"Recording it on the list is required and it is the right first step—every change with a potential impact goes there. But the list is our administration, not the Agency's decision. For a device not in the licence inventory the technical regulation requires a prior declaration, countersigned by the recognised expert.","screen":"List entry required; declaration and decision still needed."},"clip":"B1.3-I04-list_only"},{"id":"covered","text":"Nothing further: our licence already covers X-ray radiography in general.","correct":false,"feedback":{"spoken":"The licence does cover X-ray radiography—with the equipment in its inventory, under its conditions. The inventory field in front of you is where this type is missing. A set outside that inventory is exactly the kind of change the regulation and the technical regulation single out for prior declaration. 'We do X-ray work' is not 'we are licensed for this set'.","screen":"Licensed for the inventory, not for every set."},"clip":"B1.3-I04-covered"}],"placement":"Generator image and inventory excerpt stay visible.","clip":"B1.3-I04-prompt"},"sequence":{"cues_before_interaction":["B1.3-S11-P1"],"interaction_after_cue":"B1.3-S11-P1","interaction_id":"B1.3-I04","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S12","title":"Useful knowledge from elsewhere, verified here","paragraphs":[{"cue":"B1.3-S12-P1","speaker":"Emilia","text":"One last kind of evidence. Several of you learned radiation physics abroad or from training material written for another country's rules. That knowledge does not become worthless in Belgium—how radiation attenuates in steel does not change at the border. But a check interval, an alarm setting or a 'you may start when' from another jurisdiction is not a Belgian requirement, and neither is a manufacturer's manual. What governs our installation is the Belgian regulation, our licence and its conditions, and the procedures approved by the recognised expert.","screen_text":["Physics travels; rules do not","Governs here: regulation · licence · expert-approved procedures"],"start_visual":"An equipment manual page (generic, no manufacturer) open beside the Belgian regulation extract and the company procedure page; the manual's 'check interval' line and the procedure's interval line pointed to as the type of discrepancy — no values shown.","beats":[{"at":"how radiation attenuates in steel","show":"Manual page: physics section"},{"at":"a check interval, an alarm setting","show":"Two interval lines side by side, values blanked"},{"at":"What governs our installation","show":"Regulation, licence, procedure thumbnails"}],"documents":["DOC-REG-EXTRACT","DOC-PROCEDURE-RECORD"],"clip":"B1.3-S12-P1"},{"cue":"B1.3-S12-P2","speaker":"Emilia","text":"So keep the physics, and treat the rule as a question: 'this is what I was taught elsewhere—what applies here?' If a manual and our procedure disagree, raise the discrepancy with the service and the expert rather than choosing the more convenient instruction. That habit is worth more than any single interval you could memorise.","screen_text":["Raise the discrepancy with the service and the expert"],"start_visual":"Emilia to camera.","beats":[{"at":"raise the discrepancy","show":"Label"}],"clip":"B1.3-S12-P2"}],"sequence":{"cues_before_interaction":["B1.3-S12-P1","B1.3-S12-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S13","title":"Bring the evidence back to the work","paragraphs":[{"cue":"B1.3-S13-P1","speaker":"Emilia","text":"We started with 'everything is approved'. You can now say something better: what the licence permits and under which conditions; that the client's class three licence is the Agency's decision on a declaration, not the sending of it; that commissioning needed a fully favourable acceptance expressly permitting it—plus the security acceptance where sealed sources are involved; what the decree requires before a room counts as a bunker and when small workpieces must be radiographed in one; which five safety factors the regulation builds effective protection on, with collective means first; and that a change outside the licence is recorded, declared with the expert's countersignature and decided by the Agency.","screen_text":["Licence · Agency decision · acceptance (+ security) · bunker definition + certificate · five factors · change declared"],"start_visual":"Installation file at the control post; each tab opens briefly at its phrase (visual recap, not a bullet page).","beats":[{"at":"what the licence permits","show":"Tab: licence"},{"at":"the Agency's decision on a declaration","show":"Tab: decision"},{"at":"commissioning needed a fully favourable acceptance","show":"Tab: acceptance"},{"at":"before a room counts as a bunker","show":"Tab: certificate"},{"at":"five safety factors","show":"Tab: factors"},{"at":"a change outside the licence","show":"Tab: change register"}],"clip":"B1.3-S13-P1"},{"cue":"B1.3-S13-P2","speaker":"Emilia","text":"None of this needs you to be the licensing authority. It needs you to read the right document for the right question, to say plainly when a result is not established, and to route a proposal through the people who decide. In the next lesson we add a second company to the picture: what changes when the worker's employer and the operator of the workplace are not the same organisation—as happens every time one of our radiographers enters a client's controlled area, or a subcontractor enters ours.","screen_text":["Next: a second company in the picture"],"start_visual":"Clara's file-carrying preview as the bridge.","beats":[{"at":"a second company","show":"Clara preview"}],"characters":["Clara"],"clip":"B1.3-S13-P2"}],"sequence":{"cues_before_interaction":["B1.3-S13-P1","B1.3-S13-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}}]},{"id":"B1.4","title":"External workers: protection across company lines","scenes":[{"id":"S01","title":"Welcome back: protection across company lines","paragraphs":[{"cue":"B1.4-S01-P1","speaker":"Emilia","text":"Welcome back. So far we have looked at our own company from the inside: our service, our licence, our bunker, our agents—with clients appearing at the edge of the picture, asking for radiography and justifying where it happens. Today the company line itself becomes the subject. Almost every week one of our radiographers walks into another operator's controlled area, and from time to time a radiographer employed by another company works in our bunker. Who makes sure the important information travels with the person?","screen_text":["A second company changes the information flow"],"start_visual":"Reception area with the hall and bunker gate behind; Clara enters in her approved file-carrying pose at 'a radiographer employed by another company'; Emilia at the desk.","beats":[{"at":"walks into another operator's controlled area","show":"Daniel preview at the hall door with his case"},{"at":"a radiographer employed by another company works in our bunker","show":"Clara enters with her file"}],"characters":["Emilia","Clara","Daniel"],"clip":"B1.4-S01-P1"},{"cue":"B1.4-S01-P2","speaker":"Emilia","text":"Belgian law has a short section for exactly this situation: the operational protection of external workers exposed to a risk of ionising radiation while working in a controlled area. Today I want you to be able to say what the worker's own employer must do, what the operator of the workplace must do, what a signed agreement between the two can and cannot change, and what the worker brings to the arrangement personally. We will use both directions: one of our people going out, and a visiting radiographer coming in.","screen_text":["Employer's duties · workplace operator's duties · what an agreement can change · what the worker brings"],"start_visual":"Four short labels in turn beside Clara's file.","beats":[{"at":"what the worker's own employer must do","show":"Label 1"},{"at":"what the operator of the workplace must do","show":"Label 2"},{"at":"signed agreement","show":"Label 3"},{"at":"what the worker brings","show":"Label 4"}],"clip":"B1.4-S01-P2"}],"sequence":{"cues_before_interaction":["B1.4-S01-P1","B1.4-S01-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S02","title":"Two directions, the same words","paragraphs":[{"cue":"B1.4-S02-P1","speaker":"Emilia","text":"First the words, because the law uses the same two terms whichever way the worker is travelling. The external undertaking is the company that employs the worker and sends him. The operator—or, where there is no operator, the head of the undertaking—is the party at whose premises the worker carries out an assignment involving an exposure risk. The external worker is the person in between.","screen_text":["External undertaking = employer who sends","Operator = where the assignment is carried out","External worker = the person in between"],"start_visual":"Two-lane view, both empty; the three terms appear as stable labels.","beats":[{"at":"The external undertaking","show":"Label 1"},{"at":"The operator","show":"Label 2"},{"at":"The external worker","show":"Label 3"}],"clip":"B1.4-S02-P1"},{"cue":"B1.4-S02-P2","speaker":"Emilia","text":"Direction one. Daniel is sent to a power station during an outage, to radiograph welds inside the plant's controlled area. There, Daniel is an external worker, our company is the external undertaking, and the power station is the operator. Notice that he does not stop being our designated agent for the radiography we perform: the decree asks for our agent on every worksite, and the Agency's guidance accepts that contractors bring their own agents for specific operations under the supervision of the operator's physical control service. Two roles run side by side—his, for our radiography; the plant's, for its controlled area—and this lesson is about how they are divided, not about one cancelling the other. Direction two. Clara, a radiographer employed by another inspection company, is subcontracted to work in our bunker for two weeks. In our bunker she is the external worker, her employer is the external undertaking, and we are the operator. Same words, roles reversed.","screen_text":["Direction 1 — Daniel out: we = external undertaking · plant = operator","Direction 2 — Clara in: her employer = external undertaking · we = operator"],"start_visual":"Lane 1 animates first: Daniel travels from our company to a power-station controlled area (labels stable); then lane 2: Clara arrives from her employer into our bunker. Labels 'employer' and 'workplace operator' stay fixed on each lane.","beats":[{"at":"Direction one","show":"Lane 1: Daniel travels out"},{"at":"our designated agent for the radiography we perform","show":"Small caption on Daniel: 'our agent for our radiography'"},{"at":"Direction two","show":"Lane 2: Clara arrives"},{"at":"roles reversed","show":"Both lanes with their fixed labels"}],"characters":["Daniel","Clara"],"clip":"B1.4-S02-P2"},{"cue":"B1.4-S02-P3","speaker":"Emilia","text":"A controlled area, in the regulation's definition, is an area subject to special rules for protection against ionising radiation and against the spread of contamination, and whose access is controlled; in licensed establishments, every area where three tenths of the annual dose limits for exposed workers could be exceeded must be a controlled area or part of one. The protection perimeter we mark out around an exposure is our controlled area on a worksite; the plant's marked zones are its controlled areas.","screen_text":["Controlled area: special rules, access controlled","Our perimeter on a worksite = our controlled area"],"start_visual":"Regulation extract thumbnail; perimeter kit image at the worksite lane.","beats":[{"at":"A controlled area","show":"Extract thumbnail"},{"at":"The protection perimeter we mark out","show":"EQ-PERIMETER-KIT in lane 1"}],"documents":["DOC-REG-EXTRACT"],"equipment":["EQ-PERIMETER-KIT"],"clip":"B1.4-S02-P3"},{"cue":"B1.4-S02-P4","speaker":"Emilia","text":"And the principle that governs the whole section is one sentence: the radiological control system for external workers provides protection equivalent to that enjoyed by the workers the operator employs permanently. Being there for two weeks, or for one shift, is not a reason for weaker arrangements. Keep that sentence in mind as we divide the duties.","screen_text":["Equivalent protection — however short the assignment"],"start_visual":"Both lanes; one sentence label.","beats":[{"at":"protection equivalent","show":"Label"}],"clip":"B1.4-S02-P4"}],"sequence":{"cues_before_interaction":["B1.4-S02-P1","B1.4-S02-P2","B1.4-S02-P3","B1.4-S02-P4"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S03","title":"What the worker's own employer must do","paragraphs":[{"cue":"B1.4-S03-P1","speaker":"Emilia","text":"Start with the employer, because its duties begin before anyone arrives. The external undertaking looks after the radiation protection and safety of its workers in accordance with chapter three of the regulation. In particular it ensures compliance with the general principles of radiation protection and the dose limits, and it organises the general information of article 25.1.1 for its workers—the information you met two lessons ago.","screen_text":["Employer: principles and limits · general information (25.1.1)"],"start_visual":"DOC-EXT-WORKER-FILE page 1 overview (page-shaped, two pages indicated).","beats":[{"at":"The external undertaking looks after","show":"Page 1 overview"}],"documents":["DOC-EXT-WORKER-FILE"],"clip":"B1.4-S03-P1"},{"cue":"B1.4-S03-P2","speaker":"Emilia","text":"Then, before an assignment with an exposure risk, it informs the operator—or the head of the undertaking, or the foreign undertaking—about three things, and the purpose of each is easy to see. Who the sending company is, so the operator knows whom it is dealing with: the name, the establishment unit and the enterprise number. Who the worker is, unambiguously: his identity data down to the national register number, so that dose records cannot be confused between two people with the same name. And what dose he has already received: the doses over the last five calendar years, shown per year, and the doses over the last twelve rolling months, shown with the monitoring period—so the operator can judge, before the task, whether a dose constraint is needed. Where exposure was not uniform or there was internal contamination, the file carries the corresponding equivalent and committed doses as well. The exact fields are in the reference reader.","screen_text":["Who sends — name, establishment unit, enterprise number","Who — identity data incl. national register number","Doses — five calendar years per year; twelve rolling months with period"],"start_visual":"Page 1 close-ups: sending-employer block (placeholders) → worker block (Clara; placeholders) → page 2 close-up: five-year section ('provided' ×5) → twelve-month section → back to page 2 overview.","beats":[{"at":"Who the sending company is","show":"Close-up: employer block"},{"at":"Who the worker is","show":"Close-up: worker block"},{"at":"what dose he has already received","show":"Page 2: five-year section"},{"at":"twelve rolling months","show":"Page 2: twelve-month section (content revealed in S04)"},{"at":"reference reader","show":"Reference reader control indicated"}],"documents":["DOC-EXT-WORKER-FILE"],"clip":"B1.4-S03-P2"},{"cue":"B1.4-S03-P3","speaker":"Emilia","text":"Two reporting periods, then: five calendar years, and twelve rolling months. They answer different questions, and an unlabelled number does not tell you which one you have. If the assignment is abroad, the employer also states the legal dose limits that apply there, and the information is transmitted in the way the Agency prescribes, using the radiation passport. So when Daniel is sent to the power station, it is my service that sends the plant his file before he arrives—and when Clara is sent to us, it is her employer's service I expect to hear from first.","screen_text":["Two periods, two questions","Abroad: legal limits there · radiation passport"],"start_visual":"Page 2 overview with both sections labelled; 'assignment abroad: not applicable' line.","beats":[{"at":"Two reporting periods","show":"Both sections pulse"},{"at":"If the assignment is abroad","show":"Abroad line"},{"at":"when Clara is sent to us","show":"Clara at the desk with the file"}],"characters":["Clara"],"clip":"B1.4-S03-P3"}],"sequence":{"cues_before_interaction":["B1.4-S03-P1","B1.4-S03-P2","B1.4-S03-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S04","title":"Clara's file arrives incomplete","paragraphs":[{"cue":"B1.4-S04-P1","speaker":"Emilia","text":"Clara's employer sent her file last week, and this morning Clara hands me the printed copy herself, with her agent-course certificate on top. Company details, her details, and her doses for the last five calendar years are there. The twelve-rolling-month section is blank. Our service has a dosimeter ready for her.","screen_text":["Five calendar years: provided","Twelve rolling months: NOT PROVIDED"],"start_visual":"Clara visibly hands the folder to Emilia (supplied poses: Clara offering, Emilia receiving with both hands); Emilia opens it; page 2 close-up: five-year section 'provided', twelve-month section 'NOT PROVIDED' — the blank section is the evidence, framed, with a NOT ESTABLISHED badge; certificate thumbnail on top; dosimeter on the desk.","beats":[{"at":"Clara hands me the printed copy","show":"Hand-over: the folder moves from Clara's hand to Emilia's"},{"at":"five calendar years are there","show":"Close-up: five-year section"},{"at":"twelve-rolling-month section is blank","show":"Close-up: NOT PROVIDED section framed; badge"},{"at":"a dosimeter ready for her","show":"EPD on the desk"}],"documents":["DOC-EXT-WORKER-FILE","DOC-CERT-AGENT"],"equipment":["EQ-EPD-LEFT-CHEST"],"characters":["Clara","Emilia"],"clip":"B1.4-S04-P1"}],"interaction":{"id":"B1.4-I01","type":"single_choice","prompt_spoken_once":"Clara's file has her doses for the last five calendar years but not for the last twelve rolling months. What do we do?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Page 2: five calendar years — provided; twelve rolling months — NOT PROVIDED. Certificate and our dosimeter on the desk.","options":[{"id":"ask","text":"Ask her employer for the twelve-month results and take note of them before she starts.","correct":true,"feedback":{"spoken":"Yes. The employer must send both periods before the assignment, and we as the operator must take note of her monitoring results before she starts. So I name the exact gap—twelve rolling months with the monitoring period—and ask her employer's service for it this morning. Clara does not have to repeat anything, and nobody guesses what the missing months would show. Her instruction on our bunker can begin meanwhile; it does not depend on that number.","screen":"Name the gap; ask the employer; take note before she starts."},"clip":"B1.4-I01-ask"},{"id":"zero","text":"Treat the missing twelve months as zero and issue our dosimeter.","correct":false,"feedback":{"spoken":"Our dosimeter will do its job: it records what Clara receives with us, from today. What it cannot do is tell me what she received elsewhere in the last twelve months, and that is the figure I need before deciding whether a dose constraint applies to her task. Writing zero turns an unknown into a claim nobody can support. The useful step is to ask her employer for the twelve-month section.","screen":"Unknown ≠ zero; the dosimeter records from today only."},"clip":"B1.4-I01-zero"},{"id":"certificate","text":"Accept her agent-course certificate as sufficient evidence of her dose history.","correct":false,"feedback":{"spoken":"Her certificate is real evidence of something—she passed the knowledge test for the agent training, which I am glad to see on the file. It simply contains no dosimetry, because it was never meant to. Dose history comes from her employer's monitoring, in the file. So I keep the certificate for what it shows, and I ask her employer for the twelve-month results.","screen":"Certificate = passed test; dose history comes from the employer's monitoring."},"clip":"B1.4-I01-certificate"}],"placement":"Page 2 with the framed NOT PROVIDED section stays visible.","clip":"B1.4-I01-prompt"},"sequence":{"cues_before_interaction":["B1.4-S04-P1"],"interaction_after_cue":"B1.4-S04-P1","interaction_id":"B1.4-I01","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."},"status_badges":[{"kind":"not_established","label":"Twelve rolling months: not provided","explanation":"The employer's file lacks the twelve-month monitoring results with their period. This is an evidence gap to be closed by the employer; it is not a dose of zero."}]},{"id":"S05","title":"What the operator of the workplace must do","paragraphs":[{"cue":"B1.4-S05-P1","speaker":"Emilia","text":"Now the other side. The operator—or, failing one, the head of the undertaking—at whose premises external workers carry out an assignment with an exposure risk is responsible for the operational aspects of their radiation protection in the controlled area and for the task to be performed. The regulation lists six things in particular.","screen_text":["Operator: operational aspects in the controlled area and for the task"],"start_visual":"Emilia and Clara walk from reception toward the bunker control post (supplied poses or a cut between two positions if no walking pose exists).","beats":[{"at":"responsible for the operational aspects","show":"Label"}],"characters":["Emilia","Clara"],"clip":"B1.4-S05-P1"},{"cue":"B1.4-S05-P2","speaker":"Emilia","text":"Ensuring that the general principles and the dose limits are respected. Organising the individual dosimetric monitoring of the external workers, as provided in article 30.6. Organising the specific training for the external workers—the workstation training of article 25.1.2, aimed at this area and this task. Making the necessary personal protective equipment available. Taking note, before the assignment, of the results of their individual dosimetric monitoring. And, where necessary, determining and enforcing dose constraints, taking into account the doses already received, the nature of the controlled area and the task.","screen_text":["Principles and limits · monitoring (30.6) · specific training (25.1.2) · PPE · take note of dose results · dose constraints where needed"],"start_visual":"One action at a time, not a six-card lecture: Emilia hands Clara our EPD (clip to chest); the instruction record DOC-INSTRUCTION-RECORD is opened at the control post; PPE shelf; the file's dose page; the planning line 'dose constraint: to be considered'.","beats":[{"at":"Organising the individual dosimetric monitoring","show":"EPD handed over and clipped"},{"at":"Organising the specific training","show":"Instruction record opened: bunker · bunker X-ray set"},{"at":"personal protective equipment","show":"PPE shelf"},{"at":"Taking note, before the assignment","show":"File page 2"},{"at":"dose constraints","show":"Planning line"}],"documents":["DOC-INSTRUCTION-RECORD","DOC-EXT-WORKER-FILE","DOC-PLANNING"],"equipment":["EQ-EPD-LEFT-CHEST"],"characters":["Emilia","Clara"],"clip":"B1.4-S05-P2"},{"cue":"B1.4-S05-P3","speaker":"Emilia","text":"Apply it in both directions. When Daniel enters the power station, the plant organises his site-specific training, reads his dose history, and decides whether a dose constraint applies for the outage work—unless an agreement says otherwise, which is the next scene. When Clara enters our bunker, that list is mine: I organise her monitoring with us, her instruction on our bunker and our procedures, her protective equipment, and I read her file before she starts. Notice what the list does not contain. It does not say 'check that she has a certificate and let her get on with it'. The specific training is about this place and this task, and no certificate from a classroom supplies it.","screen_text":["Daniel at the plant: the plant's list (unless an agreement says otherwise)","Clara with us: my list"],"start_visual":"Both lanes from S02 briefly; then Daniel's instruction record at the plant (outline) and Clara's with us.","beats":[{"at":"When Daniel enters the power station","show":"Lane 1"},{"at":"When Clara enters our bunker","show":"Lane 2"},{"at":"no certificate from a classroom supplies it","show":"Certificate thumbnail set aside from the instruction record"}],"characters":["Daniel","Clara"],"clip":"B1.4-S05-P3"}],"sequence":{"cues_before_interaction":["B1.4-S05-P1","B1.4-S05-P2","B1.4-S05-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S06","title":"What a signed agreement can change","paragraphs":[{"cue":"B1.4-S06-P1","speaker":"Emilia","text":"You may be thinking: our own service organises Daniel's dosimetry; surely the power station does not issue him a second dosimeter? The regulation foresees this. An external undertaking that intervenes continuously or repeatedly under a contract with an operator, or that has its own physical control service, or that is an external emergency service, may organise some or all of certain aspects of its workers' protection during assignments for that operator. Our company qualifies twice over: we work for the plant under a repeated contract, and we have our own physical control service.","screen_text":["Qualifying external undertaking: repeated contract · own physical control service · emergency service"],"start_visual":"DOC-AGREEMENT whole page (parties as roles; illustrative signature area, no names).","beats":[{"at":"The regulation foresees this","show":"Agreement page overview"},{"at":"Our company qualifies twice over","show":"Parties block"}],"documents":["DOC-AGREEMENT"],"clip":"B1.4-S06-P1"},{"cue":"B1.4-S06-P2","speaker":"Emilia","text":"Which aspects? The regulation names them: the specific training on the controlled area and the task; the individual dosimetric monitoring and the transfer of its results to the exposure register; and the provision of the necessary personal protective equipment. And it adds the condition that matters most in practice: these arrangements are laid down in an agreement signed by both parties.","screen_text":["Can be allocated: specific training · dosimetry + transfer to the register · PPE","Only in an agreement signed by both parties"],"start_visual":"Close-up on the three relevant clauses in turn, then the signature area (illustrative).","beats":[{"at":"the specific training on the controlled area","show":"Clause C"},{"at":"the individual dosimetric monitoring","show":"Clause A"},{"at":"protective equipment","show":"Clause B"},{"at":"signed by both parties","show":"Signature area (placeholders)"}],"clip":"B1.4-S06-P2"},{"cue":"B1.4-S06-P3","speaker":"Emilia","text":"So I read our agreement with the power station for what it actually allocates. Ours says: our company provides Daniel's individual dosimetry and transfers the results to the register, and provides his protective equipment; the plant provides the training specific to its controlled areas and the task. That is a sensible split—we know our dosimetry, they know their plant. What the agreement does not do is move every duty to us because we signed something. Each aspect is allocated by name, and each still has to be carried out by somebody.","screen_text":["Ours: dosimetry + register → us · PPE → us · site-specific training → the plant"],"start_visual":"Clauses A and B marked 'external undertaking'; clause C marked 'operator'; back to full page.","beats":[{"at":"Ours says","show":"Clauses A/B marked"},{"at":"the plant provides the training","show":"Clause C marked 'operator'"},{"at":"Each aspect is allocated by name","show":"Full page"}],"clip":"B1.4-S06-P3"}],"sequence":{"cues_before_interaction":["B1.4-S06-P1","B1.4-S06-P2","B1.4-S06-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S07","title":"Read the allocation","paragraphs":[{"cue":"B1.4-S07-P1","speaker":"Emilia","text":"A colleague at the plant sees our signed agreement and says: 'You people handle Daniel's protection, then—we're off the hook.'","screen_text":["'You people handle Daniel's protection, then—we're off the hook.'"],"start_visual":"Agreement page with clauses A/B/C visible; the colleague's line as a speech line.","beats":[{"at":"A colleague at the plant","show":"Speech line"}],"documents":["DOC-AGREEMENT"],"clip":"B1.4-S07-P1"}],"interaction":{"id":"B1.4-I02","type":"single_choice","prompt_spoken_once":"Our signed agreement allocates Daniel's dosimetry and protective equipment to our company. Who provides the training specific to the plant's controlled area?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Agreement: clause A dosimetry → external undertaking; clause B PPE → external undertaking; clause C specific training → operator.","options":[{"id":"plant","text":"The power station, because the agreement did not allocate that training to us.","correct":true,"feedback":{"spoken":"Right. The agreement can allocate specific training, dosimetry and protective equipment to the external undertaking, but only as far as it says. Read clause C on the page: it stays with the operator. The specific training stays where the regulation places it by default: with the operator at whose premises the work is done.","screen":"Clause C: operator. Only named aspects move."},"clip":"B1.4-I02-plant"},{"id":"us","text":"Our company, because signing the agreement moved all protection duties to the external undertaking.","correct":false,"feedback":{"spoken":"The signature did move two real things: Daniel's dosimetry and his protective equipment are ours under clauses A and B. A signed agreement allocates the aspects it names, and the regulation lists which aspects can be allocated at all. Clause C does not allocate site-specific training to us, so that duty did not move. Reading every duty into one signature is exactly the colleague's mistake.","screen":"A and B moved to us; C did not."},"clip":"B1.4-I02-us"},{"id":"none","text":"Nobody needs to: Daniel's agent course already covers controlled areas.","correct":false,"feedback":{"spoken":"The agent course is real theoretical training in radiation protection, and it is one reason Daniel can be our agent. The specific training the regulation requires is about this controlled area and this task—the plant's zones, its rules, its emergency instructions. A classroom certificate cannot supply it, which is why the regulation assigns it to the party who knows the place—here, the plant under clause C.","screen":"Theory ≠ site-specific training; the plant provides it."},"clip":"B1.4-I02-none"}],"placement":"Agreement page stays visible with the three clauses.","clip":"B1.4-I02-prompt"},"sequence":{"cues_before_interaction":["B1.4-S07-P1"],"interaction_after_cue":"B1.4-S07-P1","interaction_id":"B1.4-I02","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S08","title":"When the task changes","paragraphs":[{"cue":"B1.4-S08-P1","speaker":"Emilia","text":"Clara has been with us a week. She was instructed on the bunker and on the X-ray work she was brought in for—that is what her instruction record says. Then an assignment slip arrives: can she help with gamma exposures in hall two this afternoon? Clara says, sensibly: 'I've had the briefing, but it was for the bunker job.' That is exactly the right thing to say. Workstation training is given for a workstation and a function, and the regulation repeats it when the function, the work tool or the technology changes. Familiarity with our site does not stretch an instruction to a different task.","screen_text":["Instruction record: bunker · bunker X-ray set · casting radiography","Assignment slip: gamma exposures · hall two · this afternoon"],"start_visual":"DOC-ASSIGNMENT-SLIP beside DOC-INSTRUCTION-RECORD; Clara at the desk; the gamma projector image at 'gamma exposures'.","beats":[{"at":"that is what her instruction record says","show":"Instruction record close-up: area, equipment, task"},{"at":"an assignment slip arrives","show":"Slip close-up"},{"at":"gamma exposures in hall two","show":"EQ-GAMMA-PROJECTOR image"},{"at":"Clara says, sensibly","show":"Clara speech line"}],"documents":["DOC-ASSIGNMENT-SLIP","DOC-INSTRUCTION-RECORD"],"equipment":["EQ-GAMMA-PROJECTOR"],"characters":["Clara"],"clip":"B1.4-S08-P1"},{"cue":"B1.4-S08-P2","speaker":"Emilia","text":"So we do not let Clara decide alone that the earlier briefing is close enough, and we do not make her repeat the whole induction either. We name what has changed—different area, different equipment, different procedure—and we arrange the instruction and the review of her protection and monitoring that the change needs before she starts. The decision sits on the slip in front of you.","screen_text":["Changed: area · equipment · procedure"],"start_visual":"Slip and record side by side; the three differences highlighted between them.","beats":[{"at":"We name what has changed","show":"Three differences highlighted"}],"clip":"B1.4-S08-P2"}],"interaction":{"id":"B1.4-R01","type":"single_choice","prompt_spoken_once":"Before Clara carries out the changed task, what must be checked?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Instruction record: bunker, bunker X-ray set, casting radiography. Slip: gamma exposures, hall two, this afternoon.","options":[{"id":"coverage","text":"Whether her instruction covers this area, equipment and task — and, as it does not, arrange the specific instruction and protection review before she starts.","correct":true,"feedback":{"spoken":"Yes. The record covers the bunker and its X-ray set; the slip asks for gamma work in hall two—different area, different equipment, different procedure. So the specific instruction for that task and the review of her protection and monitoring are arranged first, with her employer under our agreement where it applies, and the existing role allocation stays as it is. Clara's own remark was the right start.","screen":"Record ≠ slip → arrange specific instruction and protection review first."},"clip":"B1.4-R01-coverage"},{"id":"covered","text":"Nothing: her bunker instruction and her agent certificate cover gamma work too.","correct":false,"feedback":{"spoken":"Both documents are genuine: the record proves instruction for the bunker X-ray work, and the certificate proves the theory test. Neither covers hall two or the gamma projector, and the regulation repeats workstation training when the tool or the technology changes. The slip describes a different task, so the instruction for it has to be arranged before she starts.","screen":"Record and certificate are real, but neither covers this task."},"clip":"B1.4-R01-covered"},{"id":"dosimeter","text":"Only her dosimeter: a new task needs a new dosimeter reading first.","correct":false,"feedback":{"spoken":"Her dosimeter keeps doing its job in hall two, and reviewing her monitoring is part of what the change needs. But a reading does not instruct anyone on a different area, equipment and procedure. The check that decides whether she may do the task is the coverage of her instruction—and that, the record shows, does not reach hall two.","screen":"Monitoring review is part of it; instruction coverage is the decisive check."},"clip":"B1.4-R01-dosimeter"}],"replaces":"B1.4 S08 R01 (free-text handover rehearsal) — replaced one-for-one as a decision on the assignment slip","placement":"Slip and record stay side by side.","clip":"B1.4-R01-prompt"},"sequence":{"cues_before_interaction":["B1.4-S08-P1","B1.4-S08-P2"],"interaction_after_cue":"B1.4-S08-P2","interaction_id":"B1.4-R01","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S09","title":"Who is responsible where","paragraphs":[{"cue":"B1.4-S09-P1","speaker":"Emilia","text":"Back to Daniel at the power station. He is our employee and our designated agent for this radiography job.","screen_text":["Daniel at the plant — our employee, our designated agent for this radiography job"],"start_visual":"Both lanes from S02 again, Daniel's lane active; the same fixed labels 'employer' / 'workplace operator'; Clara's lane shown for comparison.","beats":[{"at":"Back to Daniel at the power station","show":"Lane 1 active"}],"characters":["Daniel","Clara"],"clip":"B1.4-S09-P1"}],"interaction":{"id":"B1.4-I03","type":"single_choice","prompt_spoken_once":"Daniel radiographs welds inside a power station's controlled area. In the regulation's terms, who is responsible for the operational aspects of his protection there?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Lane 1: Daniel — employer: our company; workplace operator: the power station. Lane 2 (for comparison): Clara — employer: her company; workplace operator: us.","options":[{"id":"plant","text":"The power station, as the operator at whose premises he carries out the assignment.","correct":true,"feedback":{"spoken":"Yes. The operator at whose premises external workers carry out an assignment with an exposure risk is responsible for the operational aspects in the controlled area and for the task. That sits alongside, not instead of, the other roles: our company keeps its duties as his employer, our signed agreement allocates named aspects to us, and Daniel remains our designated agent for the radiography itself, working under the plant's arrangements. The question asked about one responsibility, and the regulation places that one on the plant.","screen":"Workplace operator = the plant; employer and agent duties continue beside it."},"clip":"B1.4-I03-plant"},{"id":"us","text":"Our company, because Daniel is our employee and we sent him there.","correct":false,"feedback":{"spoken":"As his employer we have real duties: compliance with principles and limits, general information, and the pre-assignment file with his dose history—the same file you read for Clara. But the operational aspects inside another operator's controlled area are placed on that operator, unless a signed agreement allocates a named aspect to us. Employment alone does not make us responsible for a plant we do not run.","screen":"Employer duties are real; operational aspects in the plant's area are the plant's."},"clip":"B1.4-I03-us"},{"id":"daniel","text":"Daniel himself, because he is our designated radiation protection agent for the job.","correct":false,"feedback":{"spoken":"Daniel's designation is real and it travels with him: the decree asks for our agent on every worksite, and his checks on our equipment and our procedure continue inside the plant. But an agent's duties are not the operator's responsibility for the operational aspects of protection in its controlled area—monitoring, site-specific training, dose constraints. Those the regulation places on the plant, with our agreement dividing named aspects. Two roles side by side, not one replacing the other.","screen":"Agent duties continue; the operator's responsibility is the plant's."},"clip":"B1.4-I03-daniel"}],"placement":"Lanes stay visible.","clip":"B1.4-I03-prompt"},"sequence":{"cues_before_interaction":["B1.4-S09-P1"],"interaction_after_cue":"B1.4-S09-P1","interaction_id":"B1.4-I03","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S10","title":"What the worker brings, and when the work is abroad","paragraphs":[{"cue":"B1.4-S10-P1","speaker":"Emilia","text":"The information travels partly because the worker carries it. Every worker and external worker must follow the instructions and the regulation, must not expose himself unnecessarily or damage or remove protective means, and reports immediately, at least to the physical control service, any irregularity or defect in the protective means. The article goes on: he contributes as far as possible to his own protection, and in particular he agrees to give the employer, the operator or the head of the undertaking information about his previous and current work that is relevant to ensuring effective and coherent protection for himself and for others. Clara telling us that her briefing covered a different job is that duty in action. The article also stresses the need and the duty to declare a pregnancy as early as possible.","screen_text":["Worker: follow instructions · report defects at once · share relevant information about own work · declare pregnancy early"],"start_visual":"Clara at the desk; ARBIS 26 extract thumbnail; her remark from S08 as a speech line at 'Clara telling us'.","beats":[{"at":"Every worker and external worker","show":"Extract thumbnail"},{"at":"Clara telling us that her briefing covered a different job","show":"Clara speech line"}],"documents":["DOC-REG-EXTRACT"],"characters":["Clara"],"clip":"B1.4-S10-P1"},{"cue":"B1.4-S10-P2","speaker":"Emilia","text":"One more direction: abroad. When we send a radiographer to an undertaking in another country, our company makes sure, through an agreement with the foreign undertaking, that the general principles, the dose limits and any agreed dose constraints are respected; that our worker is subject to individual dosimetric monitoring; that he receives the specific training before the assignment starts; and that he has the necessary protective equipment. And we transmit the results of his monitoring to the exposure register ourselves. The pre-assignment information goes with the radiation passport, in the way the Agency prescribes. I am not giving you a cross-border checklist today; I am showing you that the same questions travel: who has the information, who needs it, and who has agreed to do what.","screen_text":["Domestic assignment: file as read today","Abroad: agreement with the foreign undertaking · radiation passport"],"start_visual":"Two sequential document examples with clear scope labels: 'Assignment in Belgium' (DOC-EXT-WORKER-FILE) then 'Assignment abroad' (passport outline, placeholders). The passport is shown only under the 'abroad' label.","beats":[{"at":"One more direction: abroad","show":"Scope label switches to 'Assignment abroad'"},{"at":"radiation passport","show":"Passport outline (placeholders)"},{"at":"the same questions travel","show":"Back to the domestic file"}],"documents":["DOC-EXT-WORKER-FILE"],"clip":"B1.4-S10-P2"}],"sequence":{"cues_before_interaction":["B1.4-S10-P1","B1.4-S10-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S11","title":"One worker, connected responsibilities","paragraphs":[{"cue":"B1.4-S11-P1","speaker":"Emilia","text":"Daniel going out and Clara coming in show the same structure from both sides. The employer brings the general information, the identity data and the dose history for two reporting periods, and keeps responsibility for principles and limits. The operator of the workplace organises the operational protection in its controlled area: monitoring, specific training, protective equipment, reading the dose history, dose constraints where needed. A signed agreement between a qualifying external undertaking and the operator can move named aspects—and only those—between them. And the worker follows the instructions, reports defects at once and shares what is relevant about his own work.","screen_text":["Employer · workplace operator · agreement (named aspects) · worker"],"start_visual":"Both lanes with the four parties' labels pulsing in turn; Clara at the control post with Daniel; her file's missing section marked 'requested from employer — pending'.","beats":[{"at":"The employer brings","show":"Lane labels: employer"},{"at":"The operator of the workplace organises","show":"Lane labels: operator"},{"at":"A signed agreement","show":"Agreement thumbnail"},{"at":"the worker follows the instructions","show":"Clara"}],"characters":["Clara","Daniel"],"clip":"B1.4-S11-P1"},{"cue":"B1.4-S11-P2","speaker":"Emilia","text":"A missing result, an instruction that covered a different task, or a colleague reading a whole transfer into one signature should each lead to a precise handover, not a guess. Next time we look at what happens when something is actually wrong: the protective action, the internal information, and the statutory reporting to the Agency with its criteria and time limits—so that a message being passed on is never mistaken for every necessary action being done.","screen_text":["Next: protective action · internal information · statutory reporting"],"start_visual":"Bridge to B1.5: bunker control post with the warning lamp (off).","beats":[{"at":"Next time we look at what happens","show":"Control post view"}],"clip":"B1.4-S11-P2"}],"sequence":{"cues_before_interaction":["B1.4-S11-P1","B1.4-S11-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}}]},{"id":"B1.5","title":"When something is wrong: action, information and reporting","scenes":[{"id":"S01","title":"Welcome back: when an observation becomes a responsibility","paragraphs":[{"cue":"B1.5-S01-P1","speaker":"Emilia","text":"Welcome back. Last time we followed information across company lines, so that it would reach the right people before and after an assignment. Today we look at the moment when that connection becomes urgent: somebody notices that something is wrong. A defect, an unexpected event, a situation that could have hurt someone even though it did not.","screen_text":["A routine check → an unexpected observation"],"start_visual":"Bunker control post at the first word (control unit image, camera monitor showing the empty bunker interior, warning lamp off); Daniel at the post with his check sheet.","beats":[{"at":"somebody notices that something is wrong","show":"Camera monitor framed"}],"equipment":["EQ-XRAY-CONTROL-UNIT"],"characters":["Daniel"],"clip":"B1.5-S01-P1"},{"cue":"B1.5-S01-P2","speaker":"Emilia","text":"Those moments tempt us in two directions. One is to wait until we understand everything before saying anything. The other is to treat a message passed on as the job done. Both are mistakes, and Belgian law is quite specific about why. By the end of this lesson I want you to hold three lanes apart in your head and run them at the same time: the protective action, the information inside our protection organisation, and the statutory notification to the Agency with its criteria and time limits. And I want you to be able to give a first account that is useful precisely because it says what is not yet known.","screen_text":["Lane 1 protective action · Lane 2 internal information · Lane 3 statutory notification"],"start_visual":"Three parallel lanes appear, empty.","beats":[{"at":"the protective action","show":"Lane 1"},{"at":"the information inside our protection organisation","show":"Lane 2"},{"at":"statutory notification to the Agency","show":"Lane 3 with the FANC logo at its end"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.5-S01-P2"}],"sequence":{"cues_before_interaction":["B1.5-S01-P1","B1.5-S01-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S02","title":"Tuesday, 10:12, in the bunker","paragraphs":[{"cue":"B1.5-S02-P1","speaker":"Emilia","text":"Here is the case we will follow. Tuesday morning, Daniel is radiographing a batch of castings in our bunker with the X-ray set. He is at the control post outside; the exposure is running and the warning light is on. At twelve minutes past ten a colleague from the workshop, Tom—a fitter, not one of our exposed workers, so he wears no dosimeter—opens the bunker door to fetch a tool he had left inside. The door interlock should have cut the exposure the instant the door opened. It did not. Daniel sees the door move on the camera, stops the exposure from the control post and calls Tom back out. Tom was in the doorway for a few seconds.","screen_text":["Tuesday 10:12 · bunker · X-ray set in exposure","Door opened — interlock did not cut the exposure","Exposure stopped manually"],"start_visual":"Bunker layout with roof (plan + control post); state before: 'EXPOSURE RUNNING' lamp on in the plan, room empty. Tom is NOT depicted as a person: the door movement appears only on the control-post camera monitor as a door-open indication, and in text. Daniel at the control post presses stop (supplied pose or cut). State after: lamp off, 'OUT OF USE / HELD'.","beats":[{"at":"the exposure is running and the warning light is on","show":"Plan: lamp on; room empty"},{"at":"opens the bunker door","show":"Camera monitor: door-open indication only"},{"at":"It did not","show":"FACT badge: 'interlock did not cut the exposure'"},{"at":"stops the exposure from the control post","show":"Lamp off; HELD/OUT OF USE state"}],"equipment":["EQ-XRAY-CONTROL-UNIT","EQ-BUNKER-REFERENCE"],"characters":["Daniel"],"clip":"B1.5-S02-P1"},{"cue":"B1.5-S02-P2","speaker":"Emilia","text":"Stop there and notice what we know and what we do not. We know the time, the place, the equipment, what Tom did, what the interlock did not do, and what Daniel did. We do not know why the interlock failed, and we do not know what dose Tom received. Seconds in the doorway of a bunker with an X-ray set running is not something to wave away, and it is not something to dramatise either; it is something to have assessed by the people and methods that can do it. Guessing either way helps nobody. We also cannot say that the interlock worked properly yesterday just because nobody opened the door yesterday.","screen_text":["Known: time, place, equipment, what Tom did, what the interlock did not do, what Daniel did","Unknown: why it failed · Tom's dose"],"start_visual":"Two short columns beside the plan: Known / Unknown; NOT ESTABLISHED badges on cause and dose.","beats":[{"at":"notice what we know and what we do not","show":"Known column fills"},{"at":"We do not know why the interlock failed","show":"NOT ESTABLISHED: cause"},{"at":"what dose Tom received","show":"NOT ESTABLISHED: dose"}],"clip":"B1.5-S02-P2"},{"cue":"B1.5-S02-P3","speaker":"Emilia","text":"Daniel's first words to me on the phone were good ones: 'The interlock didn't cut the exposure when Tom opened the door. I've stopped the exposure and the bunker is out of use. Tom is out of the bunker and says he feels nothing unusual, but I don't know his dose. I don't know why it failed.' Observed, done, unknown. That is a first account someone can act on. Notice what he has not said: he has not blamed Tom, he has not reassured anyone about a dose he cannot know—feeling nothing says nothing about dose—and he has not diagnosed the interlock.","screen_text":["Observed · Done · Unknown"],"start_visual":"Daniel on the phone (supplied pose); the event record DOC-EVENT-RECORD first lines fill as he speaks.","beats":[{"at":"Daniel's first words to me","show":"Record: observation line"},{"at":"I've stopped the exposure","show":"Record: status line"},{"at":"I don't know his dose","show":"Record: unknowns"}],"documents":["DOC-EVENT-RECORD"],"characters":["Daniel"],"clip":"B1.5-S02-P3"}],"sequence":{"cues_before_interaction":["B1.5-S02-P1","B1.5-S02-P2","B1.5-S02-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]},"status_badges":[{"kind":"fact","label":"Interlock did not cut the exposure","explanation":"Observed by Daniel at 10:12: the door opened and the exposure continued until he stopped it manually from the control post."},{"kind":"held","label":"Bunker out of use","explanation":"A safety device no longer meets the requirements; the installation stays out of use until the deficiency is corrected and the checks required by the procedure and the expert are done."},{"kind":"not_established","label":"Cause and Tom's dose not established","explanation":"Why the interlock failed and what dose Tom received are for the expert's study and the proper dosimetry methods; 'feels nothing unusual' says nothing about dose."}]},{"id":"S03","title":"Lane one and lane two: protect, and inform the right people","paragraphs":[{"cue":"B1.5-S03-P1","speaker":"Emilia","text":"Lane one is the protective action, and most of it has already happened because it was in Daniel's instructions. The exposure is stopped. The installation stays out of use—you know from the lesson on effective protection that a device or installation that no longer meets the requirements is taken out of use until the deficiency is corrected. Tom stays available and the facts the expert will need to assess his dose are preserved under our response procedure—where he stood, for how long, the set's settings and the exposure log, nothing changed on the control panel. Nobody tests the interlock by opening the door again during an exposure. The agent's duties include taking the prescribed urgent measures in an incident and passing the information on immediately; none of that is an invitation to investigate the fault himself.","screen_text":["Lane 1 — protective action: exposure stopped · bunker out of use · Tom available · facts preserved · no re-test by opening the door"],"start_visual":"Lane 1 fills with Daniel's actions at the control post (nothing touched on the panel; exposure log preserved).","beats":[{"at":"The exposure is stopped","show":"Lane 1 step"},{"at":"stays out of use","show":"Lane 1 step"},{"at":"Nobody tests the interlock by opening the door again","show":"Lane 1: crossed text 'no re-test'"}],"characters":["Daniel"],"clip":"B1.5-S03-P1"},{"cue":"B1.5-S03-P2","speaker":"Emilia","text":"Lane two is information inside the protection organisation, and it runs at the same time as lane one, not after it. The agent informs the head of the physical control service and the recognised expert of every abnormal situation—so Daniel calls me and leaves the agreed message for the expert at the organisation we contract; as the radiographer who stopped the work he also tells Luc, his supervisor. I do not assume the message landed: I call the expert myself and I brief our head of establishment, because he is the one who will notify the Agency. Then my own duties start. Whenever an event occurs that could endanger the safety or health of people, the head of the physical control service immediately takes all useful measures against the danger discovered, where appropriate in consultation with the recognised expert. And he warns the recognised physician in charge of the workers' medical surveillance in three cases: whenever an exposed worker has to be subjected to an emergency exposure; whenever a person, exposed worker or not, has received an accidental exposure exceeding the dose limits; and whenever an accident occurs that involves a serious exposure hazard. We do not know Tom's dose yet, so I will be speaking to the physician about Tom today rather than waiting for a number to tell me whether I must.","screen_text":["Lane 2 — Daniel → Emilia, expert (message), Luc","Emilia → expert (direct), head of establishment, physician"],"start_visual":"Lane 2 fills in parallel with lane 1 (no arrow from lane 1 to lane 2): Daniel's calls (Emilia, expert message, Luc); Emilia's calls (expert direct, head of establishment, physician). Each person performs a distinct action: Daniel phone; Luc at the hall door; Emilia at her desk.","beats":[{"at":"Lane two is information","show":"Lane 2 appears beside lane 1"},{"at":"Daniel calls me","show":"Daniel → Emilia"},{"at":"tells Luc, his supervisor","show":"Daniel → Luc (Luc at the hall door)"},{"at":"I call the expert myself","show":"Emilia → expert: 'reached' only when confirmed"},{"at":"I brief our head of establishment","show":"Emilia → head of establishment"},{"at":"warns the recognised physician","show":"Emilia → physician (role, no person)"}],"characters":["Daniel","Luc","Emilia"],"clip":"B1.5-S03-P2"},{"cue":"B1.5-S03-P3","speaker":"Emilia","text":"The regulation then gives the recognised expert a job—a thorough study of the circumstances and of the doses received, using the proper methods of individual dosimetry, ending in a report to the operator recommending measures to correct the shortcoming and prevent a repeat. And it tells the operator, or failing one the head of the undertaking, to warn as soon as possible the Agency—communicating according to the modalities and criteria the Agency has set—the government's coordination and crisis centre and the 100 emergency call system, and, where an accident involves a serious exposure hazard, the mayor and the emergency services as well. Which of those calls our event requires is written in our emergency procedure, drawn up with the expert; the Agency's 'modalities and criteria' are the subject of the rest of this lesson. What matters now is that these duties run alongside each other. We do not wait for a written report before protecting Tom, and telling me does not complete anyone's notification to the Agency.","screen_text":["Expert: study of circumstances and doses → report to the operator","Operator: warn the Agency (per its criteria), crisis centre, 100 — mayor and emergency services where a serious hazard","Duties run alongside each other"],"start_visual":"Lane 3 outlined with the FANC logo; the emergency procedure thumbnail; no arrows between lanes.","beats":[{"at":"gives the recognised expert a job","show":"Expert step in lane 2"},{"at":"to warn as soon as possible the Agency","show":"Lane 3 with FANC logo"},{"at":"run alongside each other","show":"All three lanes shown parallel"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.5-S03-P3"}],"sequence":{"cues_before_interaction":["B1.5-S03-P1","B1.5-S03-P2","B1.5-S03-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S04","title":"Daniel's next step","paragraphs":[{"cue":"B1.5-S04-P1","speaker":"Emilia","text":"Put yourself beside Daniel at the control post, a minute after he stopped the exposure. The cause is unknown; his instruction says the bunker stays out of use and the service is called.","screen_text":["Cause unknown · bunker out of use · service to be called"],"start_visual":"Control post with the HELD state and the NOT ESTABLISHED badge; Daniel beside the control unit.","beats":[{"at":"a minute after he stopped the exposure","show":"Control post state"}],"characters":["Daniel"],"clip":"B1.5-S04-P1"}],"interaction":{"id":"B1.5-I01","type":"single_choice","prompt_spoken_once":"The interlock failed to stop the exposure when the door opened, and Daniel has stopped the exposure. What does he do next?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Exposure stopped manually; bunker out of use; cause and dose not established.","options":[{"id":"keep","text":"Keep the bunker out of use, keep Tom and the exposure facts available, and call the service at once.","correct":true,"feedback":{"spoken":"Yes. That is lane one and lane two together: the protective action his instruction assigns, Tom and the facts needed for the dose assessment kept available, and the head of service and the expert informed immediately—Luc too, as his supervisor. He reports what he saw and leaves the cause and the dose to the people and methods that can establish them.","screen":"Out of use · facts preserved · service called now."},"clip":"B1.5-I01-keep"},{"id":"rerun","text":"Re-run the exposure with the door open to confirm the interlock fault before reporting it.","correct":false,"feedback":{"spoken":"The wish to be sure is understandable, and the fault will be investigated—by the people and procedures authorised for it, after the installation has been taken out of use. Reproducing it means repeating the exposure with the protection defeated: a new risk created on purpose. The report does not need a demonstrated cause to be worth making; it needs the observation.","screen":"No re-test with the door open; report the observation."},"clip":"B1.5-I01-rerun"},{"id":"finish","text":"Finish the batch carefully and note the interlock for the expert's next visit.","correct":false,"feedback":{"spoken":"Noting it for the expert is part of what happens—the expert does hear, through the service, today. But an installation whose safety device has just failed no longer meets the requirements and stays out of use until corrected; finishing the batch is exactly what the rule forbids, and an abnormal situation is reported immediately, not kept for a scheduled visit.","screen":"Out of use until corrected; report immediately."},"clip":"B1.5-I01-finish"}],"placement":"Control post state stays visible.","clip":"B1.5-I01-prompt"},"sequence":{"cues_before_interaction":["B1.5-S04-P1"],"interaction_after_cue":"B1.5-S04-P1","interaction_id":"B1.5-I01","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S05","title":"Give the facts their own place","paragraphs":[{"cue":"B1.5-S05-P1","speaker":"Emilia","text":"Before we reach the Agency, let us make Daniel's account useful to someone who was not there. 'Something went wrong this morning' helps nobody. 'At 10:12, bunker one, X-ray set in exposure, the door interlock did not cut the exposure when the door was opened; exposure stopped manually; bunker out of use' gives the next person facts to work with. Two times matter: when the event happened and when it was discovered. Here they coincide; with a slow leak or a mislabelled source they might be weeks apart, and the reporting clock runs from the event or from its discovery.","screen_text":["What · where · when (happened; discovered)"],"start_visual":"DOC-EVENT-RECORD page: observation field close-up with time/place/equipment/what; 'discovered at' field.","beats":[{"at":"At 10:12, bunker one","show":"Observation field"},{"at":"Two times matter","show":"Event time / discovery time fields"}],"documents":["DOC-EVENT-RECORD"],"clip":"B1.5-S05-P1"},{"cue":"B1.5-S05-P2","speaker":"Emilia","text":"If Daniel suspects a cause—he thinks the door switch has been sticking—he may say so, labelled as a suspicion with his reason. A suspicion is not a finding. The same discipline applies to dose. 'Not yet established' is an honest description of Tom's dose; it must not be turned into a zero because a form has a box. I might ask Daniel: what did you see yourself, what did Tom tell you, and what has already been done? Those three questions keep the record clean. Our teaching record is a handover aid; the statutory notification has its own prescribed contents, which we will come to.","screen_text":["Suspected cause — labelled as suspicion","Dose: not yet established"],"start_visual":"Close-ups: suspected-cause field ('suspected: door switch sticking — reason'); dose field 'not yet established'; status badges on the form support understanding without dominating it.","beats":[{"at":"labelled as a suspicion","show":"Suspected-cause field"},{"at":"'Not yet established' is an honest description","show":"Dose field; NOT ESTABLISHED badge"},{"at":"what did you see yourself","show":"Three question labels"}],"documents":["DOC-EVENT-RECORD"],"clip":"B1.5-S05-P2"}],"sequence":{"cues_before_interaction":["B1.5-S05-P1","B1.5-S05-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S06","title":"Lane three: who notifies the Agency, and for which establishments","paragraphs":[{"cue":"B1.5-S06-P1","speaker":"Emilia","text":"Lane three is the statutory notification, and its rules are in a technical regulation of the Agency: the regulation of 17 June 2020 setting the criteria for notifying significant events, as amended. What is a significant event? Any event—including a human error, a near-miss, an accident, an unauthorised act—that has consequences, even potential consequences, for safety, security, radiation protection or the environment. Tom's few seconds in the doorway are a significant event whatever his dose turns out to be, because the consequences could have been serious.","screen_text":["Significant event: consequences, even potential, for safety, security, radiation protection or the environment"],"start_visual":"Lane 3 with the actual FANC logo; the technical-regulation extract thumbnail (17 June 2020, as amended).","beats":[{"at":"the regulation of 17 June 2020","show":"Extract thumbnail"},{"at":"What is a significant event","show":"Definition label"}],"documents":["DOC-REG-EXTRACT"],"equipment":["EQ-FANC-LOGO"],"clip":"B1.5-S06-P1"},{"cue":"B1.5-S06-P2","speaker":"Emilia","text":"Who is covered? All class two and three establishments, with one exception for establishments whose physical control is exercised by a shared service that also serves a class one establishment—they follow the class one route. Import, transit and export, and the transport of class seven dangerous goods, have their own criteria in the same regulation, and so do persons subject to the security decree. So a site event and a transport event are not the same route; today we stay with the establishment route.","screen_text":["Scope: class II and III establishments (exception: shared service with class I) · separate routes for transport and security"],"start_visual":"Scope label; transport/security routes shown as separate thin lanes, not followed.","beats":[{"at":"All class two and three establishments","show":"Scope label"},{"at":"not the same route","show":"Separate thin lanes"}],"clip":"B1.5-S06-P2"},{"cue":"B1.5-S06-P3","speaker":"Emilia","text":"Who notifies? The head of the establishment or the head of the undertaking. For the security rubrics, the delegate for radiological security may also notify on the operator's behalf. Notice who is not named: the head of the physical control service, and the agent. In our company the operator has designated our managing director as head of the establishment; I prepare the notification with him and make sure he has the facts, but my title does not silently make me the notifier, and Daniel's call to me does not make the notification happen. For the exercises that follow, the applicable scope is given and the responsible assessment has identified the criteria; your job is to use the rules correctly, not to classify every event yourself.","screen_text":["Notifier: head of the establishment or of the undertaking (ARB for security rubrics)","Not the head of service · not the agent"],"start_visual":"Role caption 'head of establishment — notifier' (role only, no new face) beside the FANC logo; Emilia caption 'prepares with him'.","beats":[{"at":"Who notifies","show":"Notifier caption"},{"at":"Notice who is not named","show":"Text: 'not the head of service, not the agent'"},{"at":"Daniel's call to me does not make the notification happen","show":"Lane 2 → lane 3: no arrow"}],"clip":"B1.5-S06-P3"}],"sequence":{"cues_before_interaction":["B1.5-S06-P1","B1.5-S06-P2","B1.5-S06-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S07","title":"Use the criterion, not a remembered number","paragraphs":[{"cue":"B1.5-S07-P1","speaker":"Emilia","text":"The regulation's table lists the events to be notified, and for each one two things: whether successful direct contact with the Agency is required and by when, and whether an INES evaluation applies. Here is a small dated extract. Read the condition on the left as carefully as the deadline beside it; a remembered deadline without its condition is easy to apply to the wrong event.","screen_text":["Criterion → direct contact (by when?) · INES evaluation?"],"start_visual":"DOC-CRITERION-EXTRACT (one readable excerpt with its source and date), two columns explained.","beats":[{"at":"The regulation's table lists","show":"Extract page"},{"at":"Read the condition on the left","show":"Condition column highlighted"}],"documents":["DOC-CRITERION-EXTRACT"],"clip":"B1.5-S07-P1"},{"cue":"B1.5-S07-P2","speaker":"Emilia","text":"Criterion 1.5: loss or failure of equipment that fulfils a safety function. Direct contact no later than the next working day; INES evaluation yes. Criterion 1.4: non-compliance with the safety logic, or application of an unsuitable safety logic, that leads or may lead to unforeseen behaviour of the installation. Direct contact immediately; INES evaluation yes. Those are two different descriptions. An interlock that fails is equipment with a safety function; whether the way it was wired or bypassed also amounts to a safety-logic failure is a question for the responsible assessment with the expert, not for Daniel at the control post.","screen_text":["1.5 — equipment with a safety function fails: next working day · INES yes","1.4 — safety logic not complied with / unsuitable: immediately · INES yes"],"start_visual":"Two rows close-up in turn.","beats":[{"at":"Criterion 1.5","show":"Row 1.5"},{"at":"Criterion 1.4","show":"Row 1.4"},{"at":"a question for the responsible assessment","show":"Text label"}],"clip":"B1.5-S07-P2"},{"cue":"B1.5-S07-P3","speaker":"Emilia","text":"Alongside the direct-contact column stands a separate duty. For every event that meets one or more criteria, a written notification is sent by the notifier within 48 hours of the event or its discovery—or sooner if the Agency asks—to the Agency's event address. The written notification does not replace an immediate call or a next-working-day contact, and a call does not replace the written notification. In real work, our procedure holds the current complete table and the Agency's contact details; if the regulation changes, the training and the procedure are checked against the new text. This extract is for learning the mechanism.","screen_text":["Written notification within 48 h — every notifiable event — separate from the call"],"start_visual":"Separate line under the extract: '48 h written notification'.","beats":[{"at":"a written notification is sent","show":"48 h line"},{"at":"our procedure holds the current complete table","show":"Procedure thumbnail"}],"clip":"B1.5-S07-P3"}],"sequence":{"cues_before_interaction":["B1.5-S07-P1","B1.5-S07-P2","B1.5-S07-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S08","title":"When two criteria apply","paragraphs":[{"cue":"B1.5-S08-P1","speaker":"Emilia","text":"Add one established fact to our case: the responsible assessment, with the expert, concludes that both criterion 1.5 and criterion 1.4 apply. Not guessed from the first phone call—established. The regulation says what happens when an event meets several criteria: the strictest requirements for direct contact apply.","screen_text":["Established by the responsible assessment with the expert: 1.5 AND 1.4 apply"],"start_visual":"One visible timeline (10:12 event → now) with both criteria placed on it; their contact requirements shown as two markers (next working day; immediately).","beats":[{"at":"both criterion 1.5 and criterion 1.4 apply","show":"Both markers on the timeline"},{"at":"the strictest requirements for direct contact apply","show":"'immediately' marker emphasised"}],"clip":"B1.5-S08-P1"}],"interaction":{"id":"B1.5-I02","type":"single_choice","prompt_spoken_once":"The responsible assessment establishes that both criterion 1.5, next working day, and criterion 1.4, immediately, apply. By when must successful direct contact be made?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Timeline: event 10:12; criteria 1.5 (next working day) and 1.4 (immediately) both established.","options":[{"id":"immediately","text":"Immediately — the stricter requirement governs when several criteria apply.","correct":true,"feedback":{"spoken":"Exactly. When an event meets more than one criterion, the strictest requirements for direct contact apply. Criterion 1.4 requires immediate contact, so that is the point on the timeline—and the written notification within 48 hours remains a separate duty that the call does not discharge.","screen":"Strictest governs: immediately. 48 h written notification stays separate."},"clip":"B1.5-I02-immediately"},{"id":"next_day","text":"By the next working day — the equipment criterion was identified first.","correct":false,"feedback":{"spoken":"Criterion 1.5 is genuinely met, and on its own it would give the next working day. But the order in which criteria were identified changes nothing. Once both apply, the regulation applies the strictest direct-contact requirement, and criterion 1.4 says immediately. Choosing the gentler deadline because it was noticed first is exactly the error the rule is written to prevent.","screen":"Order of identification is irrelevant; the strictest applies."},"clip":"B1.5-I02-next_day"},{"id":"48h","text":"Within 48 hours — the written notification covers both criteria.","correct":false,"feedback":{"spoken":"The 48-hour written notification is a real and separate obligation that applies to every notifiable event, so it is on the timeline too. It does not replace the direct-contact requirement in the table, which here is immediate. Sending a document on time is not the same as speaking to the Agency's duty officer now.","screen":"Written notification is separate; direct contact is immediate."},"clip":"B1.5-I02-48h"}],"placement":"Timeline stays visible.","clip":"B1.5-I02-prompt"},"sequence":{"cues_before_interaction":["B1.5-S08-P1"],"interaction_after_cue":"B1.5-S08-P1","interaction_id":"B1.5-I02","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S09","title":"A message left is not successful direct contact","paragraphs":[{"cue":"B1.5-S09-P1","speaker":"Emilia","text":"Our head of establishment calls the Agency's general duty roster and reaches voicemail. He leaves a message. Is the immediate direct contact made? The regulation defines successful direct contact as contact with the person on duty in the Agency's general duty roster, with a view to a direct, oral and understandable notification of the event. And it says in so many words what does not count: a message on the Agency's answering machine or a mobile, a text, an email, a fax—or speaking to a person who is not on duty in that roster at the time.","screen_text":["Successful direct contact = direct, oral, understandable, with the person on the duty roster","Not: voicemail, text, email, fax, someone off duty"],"start_visual":"Two clear phone/log states beside each other: 'Attempt 1 — voicemail' (unsuccessful) and 'Successful direct contact' (empty, not yet); no real numbers; no simulated call audio.","beats":[{"at":"reaches voicemail","show":"Log state: attempt — voicemail"},{"at":"The regulation defines successful direct contact","show":"Definition label"},{"at":"what does not count","show":"List of non-counting forms"}],"clip":"B1.5-S09-P1"},{"cue":"B1.5-S09-P2","speaker":"Emilia","text":"So 'I left a detailed message' and 'the required contact succeeded' are different statements, and the record must say which one is true. The regulation adds that the notifier makes as many attempts as needed to actually obtain successful direct contact. There is no rule that two attempts are enough, and no rule that a written message closes the duty. Meanwhile lane one and lane two keep running: the expert's dose assessment for Tom is under way, the bunker stays out of use, the physician has been called. Daniel does not have to take over the notification. But his handover must not say 'the Agency has been notified' if what has happened is a voicemail.","screen_text":["'Left a message' ≠ 'contact succeeded' · as many attempts as needed","Lanes 1 and 2 keep running"],"start_visual":"Log: attempt lines; lanes 1–2 markers active; Daniel's handover line 'Agency: attempts ongoing'.","beats":[{"at":"as many attempts as needed","show":"Attempt lines"},{"at":"Meanwhile lane one and lane two keep running","show":"Lane markers"},{"at":"if what has happened is a voicemail","show":"Record line: 'Agency: not yet reached'"}],"clip":"B1.5-S09-P2"}],"interaction":{"id":"B1.5-I03","type":"single_choice","prompt_spoken_once":"The head of establishment calls the Agency's duty roster and reaches only voicemail. What does the contact record say, and what happens next?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Log: attempt 1 — voicemail. Successful direct contact: not yet.","options":[{"id":"unsuccessful","text":"An unsuccessful attempt is recorded, and calls continue until someone on the duty roster answers.","correct":true,"feedback":{"spoken":"Yes. That records what actually happened and keeps the obligation open. The regulation defines successful direct contact as direct, oral and understandable contact with the person on duty, and requires as many attempts as needed. Protective action and internal information continue in parallel.","screen":"Record the attempt; keep calling; lanes 1–2 continue."},"clip":"B1.5-I03-unsuccessful"},{"id":"successful","text":"Successful contact is recorded, because the voicemail contained all the information.","correct":false,"feedback":{"spoken":"A complete voicemail is good practice and may help the duty officer later. But the content of the message does not change its status: the regulation says explicitly that a message on the answering machine is not successful direct contact. Recording it as such would make the file say something that did not happen.","screen":"Voicemail is not direct contact, however complete."},"clip":"B1.5-I03-successful"},{"id":"written","text":"The written notification is sent at once and the contact is treated as made.","correct":false,"feedback":{"spoken":"Sending the written notification early is fine—it is due within 48 hours anyway, and doing it now is not wrong. It is a separate duty. It does not satisfy the direct-contact requirement, which is about speaking to the duty officer. The calls must go on until one succeeds.","screen":"Written notification is separate; calls continue."},"clip":"B1.5-I03-written"}],"placement":"Log states stay visible.","clip":"B1.5-I03-prompt"},"sequence":{"cues_before_interaction":["B1.5-S09-P1","B1.5-S09-P2"],"interaction_after_cue":"B1.5-S09-P2","interaction_id":"B1.5-I03","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S10","title":"Write what is known, without waiting for the final explanation","paragraphs":[{"cue":"B1.5-S10-P1","speaker":"Emilia","text":"Move the case forward: direct contact has succeeded and is recorded. Now the written notification, within 48 hours of the event or its discovery. The regulation says what it must contain at minimum, and the list has a logic you already know from Daniel's first account: what happened, where and when, and when it was discovered; what equipment and sources were involved; what the actual consequences are, including doses where they are known; what the suspected causes are—suspected, the regulation's own word; what urgent measures were taken; who is managing the event; and, where it applies, the physician's follow-up proposal and the INES level the recognised expert proposes. It ends with the notifier's name and signature and with anything else the Agency asks for. The complete list is in the reference reader; what I want you to hear is that it is built from facts known at that moment.","screen_text":["Initial notification: facts known at that moment · suspected causes · measures taken"],"start_visual":"DOC-NOTIFICATION readable sample page: fields filled with the case; 'Dose: under assessment' and 'Suspected cause' explicitly marked; nothing below the fold.","beats":[{"at":"what happened, where and when","show":"Fields: what/where/when"},{"at":"what the suspected causes are","show":"Suspected-cause field"},{"at":"including doses where they are known","show":"Dose field: 'under assessment'"},{"at":"reference reader","show":"Reference reader control indicated"}],"documents":["DOC-NOTIFICATION"],"clip":"B1.5-S10-P1"},{"cue":"B1.5-S10-P2","speaker":"Emilia","text":"Two phrases in that requirement carry the whole idea: 'suspected causes' and 'on the basis of the facts known at that moment'. The initial notification is not the investigation report. If we waited for every answer, we would miss the 48 hours. Equally, it must not present a convenient assumption as a result. Someone says: 'Put zero for Tom's dose, otherwise the form looks unfinished.' We do not know that zero is true; the expert's dose assessment is under way.","screen_text":["'Put zero for Tom's dose, otherwise the form looks unfinished.'"],"start_visual":"Colleague's suggestion as a speech line beside the dose field.","beats":[{"at":"Someone says","show":"Speech line"}],"clip":"B1.5-S10-P2"}],"interaction":{"id":"B1.5-I04","type":"single_choice","prompt_spoken_once":"The written notification is due, but Tom's dose and the cause of the interlock failure are not yet established. What does the notifier do?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Notification sample: dose — under assessment; cause — suspected (door switch), not established; measures — listed.","options":[{"id":"send_known","text":"Send it on time with the known facts, the unknowns named and the measures taken.","correct":true,"feedback":{"spoken":"Right. The regulation asks for the facts known at that moment, suspected causes labelled as such, and the measures taken. 'Dose under assessment' is a true statement on the form in front of you; the dosimetry result and the cause follow in the investigation and the final report, which have their own requirements.","screen":"On time, true, unknowns named."},"clip":"B1.5-I04-send_known"},{"id":"hold","text":"Hold it until the expert has established the dose and the cause.","correct":false,"feedback":{"spoken":"The expert's study is real and it will produce those answers—in the final report, due within two calendar months. The written notification has its own deadline—48 hours from the event or its discovery—and is explicitly based on the facts known at that moment. Waiting confuses the initial notification with the final report.","screen":"48 h notification ≠ final report; send now with what is known."},"clip":"B1.5-I04-hold"},{"id":"zero","text":"Enter zero dose and no consequences so the form is complete, and correct it later.","correct":false,"feedback":{"spoken":"The wish for a complete-looking form is understandable, and the form is complete when every field is true. An unknown is not a zero: that entry would make a factual claim nobody can support, in a document sent to the regulator. The honest form says the dose is under assessment, and the later report carries the result.","screen":"Unknown ≠ zero; 'under assessment' is the complete entry."},"clip":"B1.5-I04-zero"}],"placement":"Notification sample stays visible with the dose field framed.","clip":"B1.5-I04-prompt"},"sequence":{"cues_before_interaction":["B1.5-S10-P1","B1.5-S10-P2"],"interaction_after_cue":"B1.5-S10-P2","interaction_id":"B1.5-I04","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S11","title":"No INES rating does not mean no notification","paragraphs":[{"cue":"B1.5-S11-P1","speaker":"Emilia","text":"Two more things on the extract. First, a trap. Look at criterion 1.22: repeated non-compliance with the deadlines for implementing actions proposed by the recognised expert. Keep all of that wording; it is not a label for any late action. For that criterion the table says direct contact not required and INES evaluation no. Yet the written notification within 48 hours still applies, because it applies to every event that meets a criterion. 'No' in one column is never 'no reporting' across the row.","screen_text":["1.22 — direct contact not required · INES no · written notification still within 48 h"],"start_visual":"Criterion extract: row 1.22 shown over the same incident file (concise, not a badge wall).","beats":[{"at":"Look at criterion 1.22","show":"Row 1.22"},{"at":"'No' in one column is never 'no reporting'","show":"48 h line pulses"}],"documents":["DOC-CRITERION-EXTRACT"],"clip":"B1.5-S11-P1"},{"cue":"B1.5-S11-P2","speaker":"Emilia","text":"Second, INES, the international scale of nuclear and radiological events. Where the table says yes, or where the Agency so judges, the recognised expert proposes an INES level in the written notification and the Agency approves it. For an event meeting several criteria the level follows the most penalising one. A confirmed level 1 or higher means the head of the establishment proposes a communication for publication on the Agency's website; level 2 or higher also means a press release. Daniel does not rate the event, and a low rating is not permission to use the bunker again.","screen_text":["INES: expert proposes, Agency approves · most penalising criterion · level 1+: web communication; level 2+: press release","A low rating is not permission to use the bunker again"],"start_visual":"Notification sample's 'proposed INES level' field; HELD state remains on the bunker plan.","beats":[{"at":"the recognised expert proposes an INES level","show":"INES field"},{"at":"not permission to use the bunker again","show":"HELD state pulses"}],"documents":["DOC-NOTIFICATION"],"clip":"B1.5-S11-P2"}],"sequence":{"cues_before_interaction":["B1.5-S11-P1","B1.5-S11-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S12","title":"A security event follows its own route","paragraphs":[{"cue":"B1.5-S12-P1","speaker":"Emilia","text":"A failed interlock is a safety problem. A different kind of event needs a different route, and it must not get lost inside a technical-fault report. Suppose, in a separate example, that a gamma projector containing a sealed source is found to be missing from the locked storage at a client's site, or that someone has tried to take it. The source is a radioactive substance subject to the security decree, so three things happen that have nothing to do with interlocks.","screen_text":["Separate example: a sealed source missing from locked storage at a client's site"],"start_visual":"Separate source-security context: a locked storage cabinet at a client's site (no confidential arrangement), gamma projector image with 'sealed source'; clearly labelled 'different example'.","beats":[{"at":"Suppose, in a separate example","show":"Context switch label"},{"at":"The source is a radioactive substance","show":"EQ-GAMMA-PROJECTOR image"}],"equipment":["EQ-GAMMA-PROJECTOR"],"clip":"B1.5-S12-P1"},{"cue":"B1.5-S12-P2","speaker":"Emilia","text":"First, under the security decree, any person who observes a malicious act informs the operator or the delegate for radiological security immediately—that duty belongs to everyone on the site, whatever their title. Second, the operator, or the ARB on the operator's instruction, reports every malicious act and every unauthorised access or attempt at access to the competent police services, and any other security incident the operator judges should go to them. Third, every security incident the operator reports to the police is also reported to the Agency. And after the event, the operator draws up an evaluation report on causes, consequences and additional measures, available to the Agency at all times.","screen_text":["Anyone → operator or ARB immediately","Operator / ARB → police","Police-reported incidents → also the Agency","Evaluation report afterwards"],"start_visual":"Security route lane with roles only (ARB caption, police, Agency logo); no arrows to the safety lanes.","beats":[{"at":"any person who observes a malicious act","show":"Role: anyone → operator/ARB"},{"at":"competent police services","show":"Police step"},{"at":"also reported to the Agency","show":"FANC logo"}],"equipment":["EQ-FANC-LOGO"],"clip":"B1.5-S12-P2"},{"cue":"B1.5-S12-P3","speaker":"Emilia","text":"The Agency's table has rubrics for this. Criterion 1bis.2 has two branches: acts, threats or attempts of theft, unauthorised possession or malicious use of radioactive substances subject to the decree's security measures; and the loss of such substances if it has been reported to the police under the decree. Direct contact immediately; INES evaluation yes. Read the condition carefully: the police-report condition sits on the loss branch, not on the theft-or-threat branch. A credible threat is notified immediately; nobody waits for a police file before responding to it. For these security rubrics the ARB may make the notification on the operator's behalf, and the security incident may well also be a safety event—both routes then run.","screen_text":["1bis.2 — theft/threat/attempt: immediately · loss: if reported to the police — immediately · INES yes","ARB may notify for security rubrics; both routes may run"],"start_visual":"Criterion extract row 1bis.2 with its two branches.","beats":[{"at":"Criterion 1bis.2 has two branches","show":"Row with two branches"},{"at":"both routes then run","show":"Safety and security lanes shown in parallel"}],"documents":["DOC-CRITERION-EXTRACT"],"clip":"B1.5-S12-P3"}],"sequence":{"cues_before_interaction":["B1.5-S12-P1","B1.5-S12-P2","B1.5-S12-P3"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S13","title":"From the first account to the final report, and back to work","paragraphs":[{"cue":"B1.5-S13-P1","speaker":"Emilia","text":"Back in our bunker, a few weeks on. The expert has studied the circumstances and assessed Tom's dose, and the interlock fault has been found. The work is not finished when the notification has gone. The regulation requires a final report within two calendar months of the event or its discovery, or another period the Agency sets, to the same address. Where the first notification said 'suspected', this one says 'established': the causes, the doses, a detailed description. And it adds what the first could not contain—the preventive measures decided to correct every shortcoming and prevent a repeat, the lessons learned and the action plan, and, where it applies, the approval of the recognised expert and of the class seven safety adviser. The full list is in the reference reader.","screen_text":["Initial notification (48 h) → investigation → final report (two calendar months)"],"start_visual":"Timeline: initial notification → investigation → final report; DOC-FINAL-REPORT structure fields in turn.","beats":[{"at":"a final report within two calendar months","show":"Final report marker"},{"at":"'established'","show":"Fields: established causes, doses"},{"at":"the preventive measures","show":"Fields: measures, lessons, action plan"}],"documents":["DOC-FINAL-REPORT"],"clip":"B1.5-S13-P1"},{"cue":"B1.5-S13-P2","speaker":"Emilia","text":"That is not the initial form sent again with a later date. 'Tom will be more careful' is not a cause analysis of a failed interlock. And an acknowledgement from the Agency does not put the bunker back in service. Return to use follows the correction of the deficiency and the checks our procedure and the expert require—the same logic you met with the failed interlock test in the licensing lesson. One more route, specific to our trade: when radiographers stop a worksite because safe working is not possible and the situation cannot be resolved, our company contacts the Agency immediately under the industrial radiography decree. That is a different trigger from the event table, and it lives in the same procedure.","screen_text":["Return to use: a separate conditional decision after correction and the required checks","Stopped worksite that cannot be resolved → company contacts the Agency immediately"],"start_visual":"Resumption shown as a separate conditional gate beside the timeline (not a progress arrow); HELD state until the gate; the KB IR route as its own thin lane.","beats":[{"at":"does not put the bunker back in service","show":"Conditional gate, closed"},{"at":"Return to use follows","show":"Gate conditions listed: correction · checks under procedure and expert"},{"at":"One more route, specific to our trade","show":"Thin lane: company → Agency (KB IR)"}],"clip":"B1.5-S13-P2"}],"sequence":{"cues_before_interaction":["B1.5-S13-P1","B1.5-S13-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S14","title":"Correct the draft before it is handed over","paragraphs":[{"cue":"B1.5-S14-P1","speaker":"Emilia","text":"Let us hand the case to a colleague who has just arrived. They need more than 'it's been dealt with'. Go back to Tuesday afternoon, before the expert's findings—that is the moment a handover is hardest and most useful. A draft handover record is on the desk. Most of its lines are genuine facts from the day: the interlock did not cut the exposure at 10:12; the exposure was stopped manually and the bunker is out of use; Tom is available and the exposure facts are preserved; the expert was briefed and confirmed she had the facts; direct contact with the Agency succeeded at 10:40 and the written notification went this afternoon. One line is not a fact.","screen_text":["Draft handover — Tuesday afternoon"],"start_visual":"DOC-EVENT-RECORD draft page with its lines readable; the dose line reads 'Dose: zero'.","beats":[{"at":"A draft handover record is on the desk","show":"Draft page"},{"at":"One line is not a fact","show":"Lines selectable"}],"documents":["DOC-EVENT-RECORD"],"clip":"B1.5-S14-P1"},{"cue":"B1.5-S14-P2","speaker":"Emilia","text":"Here it is, read once: 'Bunker one is out of use after the door interlock failed to cut an exposure at 10:12; exposure stopped manually. Tom, a workshop fitter with no dosimeter, was in the doorway for seconds; his dose is not yet established and is being assessed by the expert; the physician has been informed. Expert informed and briefed. Direct contact with the Agency succeeded at 10:40 and the written notification went this afternoon. Open: cause, Tom's dose, and the checks before return to use.'","screen_text":["Observation · protective and work status · actual reporting status · open items"],"start_visual":"Corrected record page; the four headings pulse as read. Plays after the activity.","beats":[{"at":"Open: cause","show":"Open-items line"}],"documents":["DOC-EVENT-RECORD"],"clip":"B1.5-S14-P2"}],"interaction":{"id":"B1.5-R01","type":"single_choice","prompt_spoken_once":"Which entry needs correcting before this handover is sent?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Draft lines: interlock did not cut the exposure at 10:12 · exposure stopped manually, bunker out of use · Tom available, facts preserved · expert briefed and confirmed · direct contact with the Agency succeeded at 10:40 · written notification sent · Dose: zero","options":[{"id":"dose_zero","text":"'Dose: zero' — replace with 'Dose: not yet established — under assessment by the expert'.","correct":true,"feedback":{"spoken":"Yes. Nobody has established Tom's dose; the expert's assessment is under way, and 'feels nothing unusual' says nothing about dose. The corrected line states the unknown as an unknown. Every other line records something that actually happened. Here is the handover read once in full.","screen":"Unknown stated as unknown; the rest are recorded facts."},"clip":"B1.5-R01-dose_zero"},{"id":"contact","text":"'Direct contact with the Agency succeeded at 10:40' — replace with 'Agency notified by voicemail'.","correct":false,"feedback":{"spoken":"In this case the direct contact did succeed, at 10:40, after the earlier voicemail attempt—so the line is a recorded fact and stays. The entry that claims something nobody has established is the dose line: 'zero' is a number the case does not have. Correct that one.","screen":"Contact succeeded on record; the dose line is the unsupported entry."},"clip":"B1.5-R01-contact"},{"id":"out_of_use","text":"'Bunker out of use' — replace with 'Bunker cleared for use after the stop'.","correct":false,"feedback":{"spoken":"The bunker is out of use and must stay so until the deficiency is corrected and the required checks are done; nothing on Tuesday afternoon cleared it. That line is accurate. The entry that invents a result is 'Dose: zero'—that is the one to correct.","screen":"Out of use is accurate; 'Dose: zero' is the invented entry."},"clip":"B1.5-R01-out_of_use"}],"replaces":"B1.5 S14 R01 (free-text handover rehearsal) — replaced one-for-one as a single correction task","placement":"Draft page stays visible; on the correct answer the dose line updates and Emilia reads the concise handover once (S14-P2).","clip":"B1.5-R01-prompt"},"sequence":{"cues_before_interaction":["B1.5-S14-P1"],"interaction_after_cue":"B1.5-S14-P1","interaction_id":"B1.5-R01","post_interaction_cues":[{"cue":"B1.5-S14-P2","condition":"only after the correct entry has been selected (the corrected dose line is shown first)"}],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S15","title":"A clear response does not need to know everything","paragraphs":[{"cue":"B1.5-S15-P1","speaker":"Emilia","text":"When something is wrong, a clear response begins with an accurate observation. The protective action in your instructions comes first; the head of service and the expert hear immediately; the statutory notification follows its own criteria, with successful direct contact meaning a real conversation with the duty officer and the written notification due within 48 hours whatever the table says about contact or INES. The initial notification says what is known; the investigation and the final report, within two calendar months, develop the full account. Security events have their own route through the operator or the ARB, the police and the Agency.","screen_text":["Protect · inform · notify (direct contact + 48 h) · final report · security route"],"start_visual":"Back at the control post with the record visible; the three lanes recap briefly.","beats":[{"at":"The protective action in your instructions","show":"Lane 1"},{"at":"the statutory notification","show":"Lane 3"},{"at":"Security events have their own route","show":"Security lane"}],"clip":"B1.5-S15-P1"},{"cue":"B1.5-S15-P2","speaker":"Emilia","text":"Keep the three lanes with you, and keep the habit of saying 'not yet established' when that is the truth. In the final lesson of this module we bring the whole Belgian picture together around practical decisions: who is responsible, what evidence is needed, and what to do when the information in front of you is incomplete—with a visiting radiographer, a changed task and a client who would like you to hurry.","screen_text":["Next: one ordinary Thursday"],"start_visual":"Bridge: the job planner page DOC-PLANNER with Thursday marked.","beats":[{"at":"In the final lesson","show":"Planner thumbnail"}],"documents":["DOC-PLANNER"],"clip":"B1.5-S15-P2"}],"sequence":{"cues_before_interaction":["B1.5-S15-P1","B1.5-S15-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}}]},{"id":"B1.6","title":"One Thursday: the Belgian framework in practice","scenes":[{"id":"S01","title":"Welcome to the last lesson of this module","paragraphs":[{"cue":"B1.6-S01-P1","speaker":"Emilia","text":"Welcome back. Over five lessons we have looked at Belgian radiation protection from five directions: why a practice must be justified, optimised and kept within limits; who does what in and around our company; what the licence, the bunker and the acceptance prove; how protection follows a worker across company lines; and what happens when something is wrong. Today nothing new arrives from the regulation. Instead I want to spend one ordinary Thursday with you, and watch the five lessons turn into decisions.","screen_text":["Thursday — today"],"start_visual":"DOC-PLANNER week view with Thursday clearly marked as the current day; Daniel, Clara and the vessel image as familiar elements, no re-introduction.","beats":[{"at":"five lessons","show":"Planner week view"},{"at":"one ordinary Thursday","show":"Thursday marked current"}],"documents":["DOC-PLANNER"],"characters":["Daniel","Clara"],"clip":"B1.6-S01-P1"},{"cue":"B1.6-S01-P2","speaker":"Emilia","text":"This is practice, not an examination. The day has a job prepared earlier in the week, a client in a hurry to add to it, a visiting radiographer, a worksite that does not behave, and a planner who wants to make next time easier. In each case I will ask you a short question with a direct answer. A good answer explains the reason for a decision; it does not reach for the most reassuring document, and it does not ask for everything to be checked again.","screen_text":["08:10 · 08:40 · 10:30 · 11:40 · 12:00 · 15:00"],"start_visual":"Thursday's time marks appear on the planner.","beats":[{"at":"a job prepared earlier in the week","show":"Tuesday/Wednesday entries"},{"at":"a client in a hurry","show":"08:10 mark"}],"clip":"B1.6-S01-P2"}],"sequence":{"cues_before_interaction":["B1.6-S01-P1","B1.6-S01-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S02","title":"08:10 — a prepared job, and a client in a hurry","paragraphs":[{"cue":"B1.6-S02-P1","speaker":"Emilia","text":"Today's job was not born this morning. On Tuesday Bram, the client's maintenance manager, asked us to radiograph two welds on a large pressure vessel that had failed its visual inspection. The same afternoon we received, in writing, what the decree requires from him: his justification of the technique—why radiography and not another method—and his justification of the location, together with the information from his own risk analysis and the job details, numbers and dimensions included. The decree wants that information at least twenty-four hours before the work, so that we have time to prepare the worksite; we had it on Tuesday for a job on Thursday. As head of service I checked that the choice of technique had been justified by someone competent in the different non-destructive methods, and on Wednesday we completed our own risk analysis.","screen_text":["Tuesday: request + written justifications + job details","Wednesday: our risk analysis","≥ 24 h before the work"],"start_visual":"Planner: Tuesday entry opens the original request DOC-REQ and the two justifications (thumbnails); Wednesday entry: our risk analysis line; current day Thursday.","beats":[{"at":"On Tuesday Bram","show":"Tuesday entry: DOC-REQ thumbnail"},{"at":"his justification of the technique","show":"DOC-TECH-JUST thumbnail"},{"at":"his justification of the location","show":"DOC-LOC-JUST thumbnail"},{"at":"at least twenty-four hours before","show":"24 h marker between Tuesday and Thursday"},{"at":"on Wednesday we completed","show":"Wednesday entry"}],"documents":["DOC-PLANNER","DOC-REQ","DOC-TECH-JUST","DOC-LOC-JUST"],"characters":["Bram"],"clip":"B1.6-S02-P1"},{"cue":"B1.6-S02-P2","speaker":"Emilia","text":"Nothing about the location was decided by habit either. The vessel is installed in the hall and cannot be moved, so the rule for small movable workpieces—always in a bunker—does not apply to it. For a larger or heavier workpiece the decree still prefers a bunker, then an irradiation infrastructure on the client's site, and only when neither is reasonably feasible, another place. Bram's written assessment answers that for both options, with reasons: dismantling and transport to a bunker for two repair welds assessed and judged unreasonable; no irradiation infrastructure present, and arranging fixed shielding around the vessel for these welds assessed—access, crane traffic, duration—and judged not reasonably feasible. Only on that documented assessment, plus a risk analysis by the client and by us, does the hall become the place, and both analyses say so in writing. Notice what the reasoning rests on: the assessed constraints of this vessel and this site, not on the fact that the vessel is fixed or that the client happens not to own an irradiation infrastructure. Had radiography in a shielded structure been reasonably feasible, the hall would not have been the answer.","screen_text":["Location: both options assessed with reasons → neither reasonably feasible → the hall, after both risk analyses"],"start_visual":"DOC-LOC-JUST overview → close-up on the two assessment blocks → conclusion → back to the planner.","beats":[{"at":"Bram's written assessment","show":"DOC-LOC-JUST overview"},{"at":"dismantling and transport","show":"Bunker block"},{"at":"arranging fixed shielding","show":"Infrastructure block"},{"at":"Only on that documented assessment","show":"Conclusion line"}],"documents":["DOC-LOC-JUST"],"clip":"B1.6-S02-P2"},{"cue":"B1.6-S02-P3","speaker":"Emilia","text":"Then, at ten past eight on Thursday, the manager calls again. The visual inspection of the next vessel has thrown up a doubtful nozzle weld. 'You're here anyway—can you add it today?' That is where the pressure arrives, and the three questions from the opening lesson still have to be asked. Is this use of radiation justified? For the two welds, yes, in writing. For the nozzle weld, nothing is in writing yet. How will exposure be kept as low as reasonably achievable? Our plan covers two welds in known positions; a third weld on another vessel changes geometry, perimeter and time. Are the limits respected? A forecast below a limit is the third question, not the first two. And the decree is specific about timing: the client's written information comes at least twenty-four hours before, and neither the client nor the site employer may impose time constraints that prevent us from working safely. So my answer to the manager is not a refusal of the work; it is a refusal of the timing. Send the written justification and the job details for the nozzle weld today, and we plan it for the next slot with its own risk analysis.","screen_text":["08:10 — new request: nozzle weld on the next vessel","Prepared scope: two welds on V-2"],"start_visual":"08:10 on the planner: Bram's phone request appears as a second request slip (DOC-REQ 'nozzle weld, next vessel') beside the original — visibly outside the prepared scope; the three question labels from B1.1 return.","beats":[{"at":"the manager calls again","show":"Second request slip appears beside the original"},{"at":"Is this use of radiation justified","show":"Label 1"},{"at":"How will exposure be kept","show":"Label 2"},{"at":"Are the limits respected","show":"Label 3"},{"at":"a refusal of the timing","show":"Slip marked 'next slot — written justification and job details needed'"}],"documents":["DOC-REQ"],"characters":["Bram"],"clip":"B1.6-S02-P3"}],"interaction":{"id":"B1.6-I01","type":"single_choice","prompt_spoken_once":"At 08:10 the client asks us to add a third weld, on another vessel, to today's prepared job. What applies?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Original request: two welds on V-2, justified and prepared since Tuesday. New request: nozzle weld on the next vessel, today.","options":[{"id":"timing","text":"His written justification and job details must reach us at least 24 hours before; the weld goes to a later slot.","correct":true,"feedback":{"spoken":"Yes. The decree requires the client's correct written information at least twenty-four hours in advance so that the worksite can be prepared, and the location justification is given per type of assignment with risk-analysis information for our own analysis. Today's two welds were prepared that way; the nozzle weld is a new job, and urgency does not shorten the rule—the client may not impose time constraints that prevent safe work. Bram sends the papers today; we plan the next slot.","screen":"New job → written justification + job details ≥ 24 h before → next slot."},"clip":"B1.6-I01-timing"},{"id":"covered","text":"Add it today: the hall's justification and our risk analysis for the two welds cover any weld there.","correct":false,"feedback":{"spoken":"The justification and the two risk analyses are real and they do cover today's work—two welds in known positions on one vessel. A weld on another vessel changes the geometry, the perimeter and the exposure time, and the decree's twenty-four-hour written information has not been given for it. 'Same hall' is not 'same assignment'.","screen":"Prepared for two welds on V-2; a different vessel is a different assignment."},"clip":"B1.6-I01-covered"},{"id":"dose","text":"Add it today if our dose estimate for the hall stays below the limit.","correct":false,"feedback":{"spoken":"A forecast below a limit answers the third question, and it is worth having. It does not justify the new weld, it does not replace the client's written information for preparing the worksite, and it does not show how exposure for that weld will be kept as low as reasonably achievable. You met this in the opening lesson: a reassuring number cannot stand in for the other two questions.","screen":"Forecast = dose limitation only."},"clip":"B1.6-I01-dose"}],"placement":"Both request slips stay visible on the planner.","clip":"B1.6-I01-prompt"},"sequence":{"cues_before_interaction":["B1.6-S02-P1","B1.6-S02-P2","B1.6-S02-P3"],"interaction_after_cue":"B1.6-S02-P3","interaction_id":"B1.6-I01","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S03","title":"08:40 — who goes, and who is the agent","paragraphs":[{"cue":"B1.6-S03-P1","speaker":"Emilia","text":"Planning for the two welds was finished on Wednesday, but one line is open again this morning because a colleague has called in sick: who goes with Daniel? Radiography outside a bunker is done by at least two radiographers, so the team is two people. Available are Daniel, and Clara, the subcontracted radiographer you met two lessons ago, who has been working in our bunker. Clara has more worksite experience than Daniel. The planner suggests sending both and 'letting Clara be the agent, since she has done more of this'.","screen_text":["Team: two radiographers outside a bunker","Available: Daniel (our staff, trained) · Clara (external, instructed on our bunker)"],"start_visual":"Dispatch planning DOC-PLANNING: team lines with correct employment and instruction status captions: Daniel — our staff, agent-trained; Clara — external worker, instruction: bunker X-ray set. Designated-agent line empty.","beats":[{"at":"who goes with Daniel","show":"Planning sheet"},{"at":"Available are Daniel, and Clara","show":"Two team lines with status captions"},{"at":"letting Clara be the agent","show":"Planner's suggestion as a speech line"}],"documents":["DOC-PLANNING"],"characters":["Daniel","Clara"],"clip":"B1.6-S03-P1"},{"cue":"B1.6-S03-P2","speaker":"Emilia","text":"Two different rules answer that. First, the decree says the company designates on every worksite a radiation protection agent from the industrial radiographers present who belong to its staff and have followed the agent training. Clara is an external worker here; she is not on our staff, however experienced—her own employer may well designate her on its jobs, but not we on ours. Second, Clara's specific instruction with us covered the bunker and the bunker X-ray set; the client's hall with the portable X-ray set is a different place, different equipment and a different task, so her workstation training does not stretch to it without the instruction the change requires—and the operational protection of an external worker on a job we run is a question I settle with her employer under our agreement, not by assuming.","screen_text":["Rule 1: agent from the company's own trained radiographers present","Rule 2: instruction covers the task it was given for"],"start_visual":"Two criteria labels; Clara's instruction record thumbnail (bunker scope) at rule 2.","beats":[{"at":"Two different rules answer that","show":"Criteria labels"},{"at":"Clara is an external worker here","show":"Clara's status caption pulses"},{"at":"Clara's specific instruction with us covered the bunker","show":"DOC-INSTRUCTION-RECORD thumbnail"}],"documents":["DOC-INSTRUCTION-RECORD"],"clip":"B1.6-S03-P2"},{"cue":"B1.6-S03-P3","speaker":"Emilia","text":"So the decision is: Daniel is designated as the agent for the worksite, recorded in the planning. Clara comes as the second radiographer only if her employer and I arrange the instruction for this task first—which, since the job is prepared and the procedure is written, we can do this morning; otherwise she stays on the bunker job she was prepared for and a colleague from another team goes. Nobody's experience is being disrespected. Experience makes a person eligible for things; it does not designate them.","screen_text":["Designated agent: Daniel — recorded","Clara: second radiographer only after the instruction for this task is arranged"],"start_visual":"Designated-agent line fills 'Daniel'; Clara's line gets 'instruction for this task: to arrange with her employer'.","beats":[{"at":"Daniel is designated as the agent","show":"Agent line filled"},{"at":"Clara comes as the second radiographer only if","show":"Clara line annotated"}],"clip":"B1.6-S03-P3"}],"interaction":{"id":"B1.6-I02","type":"single_choice","prompt_spoken_once":"Two radiographers are available for the client's worksite. Who can be the designated radiation protection agent there?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Daniel — our staff, agent-trained, present. Clara — external worker, instructed on our bunker only. Emilia — head of service, not on site.","options":[{"id":"daniel","text":"Daniel — a trained radiographer on our own staff who will be present on the site.","correct":true,"feedback":{"spoken":"Right. The company designates the worksite agent from the industrial radiographers present who belong to its staff and have followed the agent training. Daniel meets all three conditions, and the designation is recorded on the planning sheet in front of you.","screen":"Own staff · trained · present → designated and recorded."},"clip":"B1.6-I02-daniel"},{"id":"clara","text":"Clara — she has far more worksite experience than anyone else available.","correct":false,"feedback":{"spoken":"Experience is real and it matters for how well the job goes. The decree still requires the worksite agent to be one of the company's own radiographers. Clara is an external worker here, employed by another company, so she cannot be our designated agent—her own employer may designate her on its jobs. And her instruction with us covered the bunker, not this task.","screen":"External worker → not our designated agent; experience ≠ designation."},"clip":"B1.6-I02-clara"},{"id":"emilia","text":"Emilia — as head of the physical control service she is the agent on every worksite.","correct":false,"feedback":{"spoken":"Heading the service is a real function and it is mine: I make sure the designation has been made and recorded. It is a different function from being the agent on a worksite. The agent is designated among the radiographers who are actually present; coordinating the service is not the same as holding that designation.","screen":"Head of service coordinates; the agent is designated among those present."},"clip":"B1.6-I02-emilia"}],"placement":"Planning sheet stays visible.","clip":"B1.6-I02-prompt"},"sequence":{"cues_before_interaction":["B1.6-S03-P1","B1.6-S03-P2","B1.6-S03-P3"],"interaction_after_cue":"B1.6-S03-P3","interaction_id":"B1.6-I02","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S04","title":"10:30 — before the first exposure","paragraphs":[{"cue":"B1.6-S04-P1","speaker":"Emilia","text":"On site, Daniel and Clara set up as the approved procedure says: the perimeter marked out so it can be watched for the whole job, the warning signs placed, the client's contact person named and present, each radiographer's electronic dosimeter and the survey meter function-tested, and a last-minute risk analysis before the first exposure. The decree asks for exactly these preparations, and each is also one of the agent's frequent and systematic checks—that the rules and procedures are followed, that the protective means and instruments are available and working—carried out on the basis of a procedure the recognised expert approved. The record Daniel keeps is his observation on that day; it is not a new approval, and it does not need to be.","screen_text":["Perimeter marked and watchable · signs · contact person present · dosimeter and survey meter function-tested · last-minute risk analysis"],"start_visual":"Client's hall with the supplied equipment imagery: portable X-ray generator on its stand, control unit, perimeter kit with trefoil signs; Daniel with handheld, EPD and TLD; Clara at the boundary; Bram present; a concise approved check-record view (DOC-CHECK-SHEET lines ticked as the narration names them — only what the script establishes).","beats":[{"at":"the perimeter marked out","show":"EQ-PERIMETER-KIT and the perimeter line on DOC-SITE-PLAN"},{"at":"the warning signs placed","show":"Trefoil signs"},{"at":"the client's contact person named and present","show":"Bram marker"},{"at":"electronic dosimeter and the survey meter function-tested","show":"Check-record lines: EPD · survey meter — function-tested"},{"at":"a last-minute risk analysis","show":"Check-record line: LMRA"}],"documents":["DOC-CHECK-SHEET","DOC-SITE-PLAN"],"equipment":["EQ-XRAY-GENERATOR","EQ-XRAY-CONTROL-UNIT","EQ-PERIMETER-KIT","EQ-HANDHELD-SURVEY","EQ-EPD-LEFT-CHEST","EQ-TLD-RIGHT-UPPER-CHEST"],"characters":["Daniel","Clara","Bram"],"clip":"B1.6-S04-P1"},{"cue":"B1.6-S04-P2","speaker":"Emilia","text":"Notice that nothing today has required anyone to approve anything new. The licence, the procedure, the designation, the client's justification and the two risk analyses were all in place before the first exposure. That is what a quiet morning looks like in this trade: the evidence was there before the pressure arrived.","screen_text":["Already in place: licence · procedure · designation · justifications · two risk analyses"],"start_visual":"The five documents as thumbnails in a row, each already 'in place'.","beats":[{"at":"nothing today has required anyone to approve anything new","show":"Thumbnail row"},{"at":"the evidence was there before the pressure arrived","show":"Row settles"}],"clip":"B1.6-S04-P2"}],"sequence":{"cues_before_interaction":["B1.6-S04-P1","B1.6-S04-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}},{"id":"S05","title":"11:40 — the worksite does not behave","paragraphs":[{"cue":"B1.6-S05-P1","speaker":"Emilia","text":"Then the morning stops being quiet. Twice in ten minutes, plant workers walk across the perimeter line to reach a store behind the hall, ignoring the signs and Clara at the boundary. The client's contact person has gone to take a call. Daniel has not started the exposure. He now has a decision that does not need a meeting.","screen_text":["Twice in ten minutes: plant workers cross the perimeter · contact person away · exposure NOT started"],"start_visual":"Familiar site drawing DOC-SITE-PLAN: two crossing marks on the perimeter line toward the store; Bram marker absent; the generator shown not emitting; HELD badge: 'Exposure held'. Reported workers remain outside any active emission; no accident spectacle.","beats":[{"at":"plant workers walk across the perimeter line","show":"Crossing marks on the drawing"},{"at":"The client's contact person has gone","show":"Bram marker greyed"},{"at":"Daniel has not started the exposure","show":"HELD badge"}],"documents":["DOC-SITE-PLAN"],"characters":["Daniel","Clara"],"clip":"B1.6-S05-P1"},{"cue":"B1.6-S05-P2","speaker":"Emilia","text":"The decree gives it to him in one sentence: industrial radiographers stop the radiography if it cannot be carried out safely, and they report that immediately, with the reason, to their hierarchical superior, to the head of the physical control service and to the client's contact person. That duty is Daniel's as a radiographer; as the designated agent he also informs me and, through our service, the expert of the abnormal situation. The decree also places a duty on the site: the responsible employer of the site makes sure that his own staff and third parties present respect the safety measures for the radiography, and the client's contact person is to be reachable throughout. And there is a further step that belongs to the company, not to Daniel: if radiographers stop or do not start a worksite and the situation cannot be resolved, the company contacts the Agency immediately.","screen_text":["Radiographers stop when unsafe → report with the reason to superior, head of service, client contact","Site employer ensures his staff and third parties respect the measures","Unresolved → the company contacts the Agency"],"start_visual":"Three short labels in turn; Daniel with phone at the drawing.","beats":[{"at":"The decree gives it to him in one sentence","show":"Label 1"},{"at":"the responsible employer of the site","show":"Label 2"},{"at":"the company contacts the Agency immediately","show":"Label 3 with FANC logo"}],"equipment":["EQ-FANC-LOGO"],"characters":["Daniel"],"clip":"B1.6-S05-P2"}],"interaction":{"id":"B1.6-I03","type":"single_choice","prompt_spoken_once":"Plant workers keep crossing the perimeter and the client's contact person has left. The exposure has not started. What does Daniel do?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Drawing: two crossings on the perimeter; contact person away; exposure held.","options":[{"id":"hold_report","text":"Hold the radiography and report at once, with the reason, to Luc, to Emilia and to Bram.","correct":true,"feedback":{"spoken":"Yes. The decree says radiographers stop the radiography when it cannot be done safely and report immediately, with the reason, to those three people—his supervisor, the head of service and the client's contact person; as agent he also informs the service, which informs the expert. The job resumes only after the client has restored control of the route and our team has verified, under the procedure, that the perimeter can be held and the agreed safety measures are in place. If it cannot be resolved, the company contacts the Agency immediately.","screen":"Hold; report with the reason to Luc, Emilia, Bram; resume only after verification."},"clip":"B1.6-I03-hold_report"},{"id":"shout","text":"Start the exposure with Clara shouting warnings — the dose rate at the line is low anyway.","correct":false,"feedback":{"spoken":"A low reading at the line is what the perimeter is for, and Clara at the boundary is doing her job. It says nothing about someone walking inside the line during an exposure. Safe working is not possible while people cross the perimeter, and the decree's answer to that is to stop and report, not to compensate with shouting.","screen":"Low at the line ≠ safe inside it; stop and report."},"clip":"B1.6-I03-shout"},{"id":"shrink","text":"Move the barriers closer to the vessel so there is less perimeter line to watch and fewer crossings.","correct":false,"feedback":{"spoken":"Reducing crossings is the right aim, and the client will do it by closing the route. The perimeter itself is the controlled area defined by the approved procedure and the risk analysis for this exposure; it is not a convenience that shrinks when supervision gets harder. Changing the protection arrangement on the spot is exactly the kind of improvisation the agent's instructions do not allow.","screen":"The perimeter is set by the procedure and risk analysis; the route is the client's to close."},"clip":"B1.6-I03-shrink"}],"placement":"Drawing with the HELD badge stays visible.","clip":"B1.6-I03-prompt"},"sequence":{"cues_before_interaction":["B1.6-S05-P1","B1.6-S05-P2"],"interaction_after_cue":"B1.6-S05-P2","interaction_id":"B1.6-I03","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."},"status_badges":[{"kind":"held","label":"Exposure held","explanation":"Safe working is not possible while people cross the perimeter and the contact person is away; the exposure has not started and does not start until the route is controlled and the team has verified the perimeter under the procedure."}]},{"id":"S06","title":"12:00 — the handover, and what it is not","paragraphs":[{"cue":"B1.6-S06-P1","speaker":"Emilia","text":"Daniel's call to me is the handover you have practised twice: 'Two plant workers crossed the perimeter twice; the contact person was away; I have not started the exposure and the radiography is on hold; I've told my supervisor, and the client's contact person has just called back; I don't know yet whether the plant can keep the route closed.' Observed, done, contacted, unknown. No exposure has occurred, nobody has been in a beam, and nothing has failed. My side of the call: I note the stop and its reason, I make sure the expert hears through our service, and I tell Daniel what has to be true before anyone resumes.","screen_text":["Observed · Done · Contacted · Unknown"],"start_visual":"Daniel's phone handover to Emilia; DOC-EVENT-RECORD lines fill: observation (crossings), status (held, no exposure), contacted (Luc; Bram called back), unknown (can the route be kept closed?).","beats":[{"at":"Two plant workers crossed the perimeter twice","show":"Record: observation"},{"at":"the radiography is on hold","show":"Record: status HELD"},{"at":"I've told my supervisor","show":"Record: contacted — Luc; Bram"},{"at":"I don't know yet whether the plant can keep the route closed","show":"Record: unknown"}],"documents":["DOC-EVENT-RECORD"],"characters":["Daniel","Emilia"],"clip":"B1.6-S06-P1"},{"cue":"B1.6-S06-P2","speaker":"Emilia","text":"Keep the lanes apart here too. This is a stopped worksite with a reason—the decree's route. Whether it is also a significant event under the Agency's criteria is for the responsible assessment with the expert; Daniel does not classify it, and nobody writes 'Agency notified' because a phone call was made to me. By half past twelve the client's contact person has closed the route with a locked gate and posted someone at it. That is the client's part. Ours is not to take his word for it: Daniel and Clara check that the perimeter can now be watched along its whole length and that the safety measures from the risk analyses are in place, they repeat the last-minute risk analysis, and Daniel confirms to me that safe working is possible again. Only then does the radiography resume under the procedure. The stop, its reason and the verification go into our records—the decree wants the company's findings documented in the physical control system—and I note it for the expert's next visit.","screen_text":["Stopped worksite (decree route) ≠ 'Agency notified'","12:30 — route closed by the client · team verifies · LMRA repeated · resume under the procedure · recorded"],"start_visual":"Return to the worksite status rather than an exercise: drawing shows the gate closed with a person posted (client's action); then Daniel and Clara's verification; the HELD badge is released only at 'Only then does the radiography resume'; record line 'stop · reason · verification' added.","beats":[{"at":"nobody writes 'Agency notified'","show":"FACT badge: 'Emilia informed; Agency: not applicable unless unresolved'"},{"at":"closed the route with a locked gate","show":"Gate closed; posted person marker"},{"at":"Daniel and Clara check","show":"Verification markers along the perimeter"},{"at":"Only then does the radiography resume","show":"HELD badge released"},{"at":"go into our records","show":"Record line added"}],"documents":["DOC-SITE-PLAN","DOC-EVENT-RECORD"],"characters":["Daniel","Clara"],"clip":"B1.6-S06-P2"}],"sequence":{"cues_before_interaction":["B1.6-S06-P1","B1.6-S06-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]},"status_badges":[{"kind":"fact","label":"Stopped worksite — reported","explanation":"Daniel reported the stop and its reason to Luc, Emilia and Bram; Emilia informs the expert through the service. Whether this is also a significant event is for the responsible assessment with the expert; no Agency notification is claimed."}]},{"id":"S07","title":"15:00 — the planner wants to make next time easier","paragraphs":[{"cue":"B1.6-S07-P1","speaker":"Emilia","text":"Back in the office, the planner has an idea born of a stressful morning: 'That hall is fine now—can we put it on a list of approved locations, so next time we skip the justification?' I understand the wish. But look at what the rule actually says. The client justifies the location in writing for each type of assignment. A vessel fixed in the hall today does not make the same hall a justified location for a casting next month. A movable casting that fits within one cubic metre and weighs under 500 kilograms is radiographed in a bunker—the mandatory condition from the licence lesson—and for anything else the feasibility reasoning starts again. And it is the client—not us, not our expert—who gives that justification. Our part is to assess it, do our risk analysis and refuse if it does not hold.","screen_text":["Location justification: by the client, in writing, per type of assignment","Movable, within 1 m³ and under 500 kg → always in a bunker; otherwise the assessment starts again"],"start_visual":"Office: the job-specific dossier (DOC-LOC-JUST for V-2) beside the next workpiece — a small casting image; the planner's suggestion as a speech line.","beats":[{"at":"put it on a list of approved locations","show":"Speech line"},{"at":"A vessel fixed in the hall today","show":"Dossier thumbnail"},{"at":"A movable casting","show":"Casting image beside it"}],"documents":["DOC-LOC-JUST"],"clip":"B1.6-S07-P1"},{"cue":"B1.6-S07-P2","speaker":"Emilia","text":"What we can do is keep today's dossier so that the next justification and risk analysis are quicker to review—the hall's layout, the routes, the gate that solved our problem. That is good practice. It is not a standing approval, and there is no document in our licence folder that could become one.","screen_text":["Keep today's dossier for a quicker review — not a standing approval"],"start_visual":"Dossier filed; no 'approved locations' list exists in the licence folder (folder shown without such a document).","beats":[{"at":"keep today's dossier","show":"Dossier filed"},{"at":"no document in our licence folder","show":"Licence folder tabs shown"}],"clip":"B1.6-S07-P2"}],"interaction":{"id":"B1.6-I04","type":"single_choice","prompt_spoken_once":"The planner wants the client's hall on a list of approved locations so future jobs there skip the justification. What applies?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Today's dossier: location justification for V-2 (two options assessed). Next workpiece: a movable casting.","options":[{"id":"each_type","text":"The client justifies the location in writing for each type of assignment; today's job does not pre-approve the hall.","correct":true,"feedback":{"spoken":"Right. The decree places the location justification on the client, in writing, for each type of assignment, with his risk-analysis information to us. Keeping today's dossier makes the next review faster; it does not replace it, and a different workpiece—a movable casting belongs in a bunker—is a different question.","screen":"Per type of assignment; dossier helps, does not replace."},"clip":"B1.6-I04-each_type"},{"id":"standing","text":"Once radiography has been done there, the hall counts as a justified location for future work.","correct":false,"feedback":{"spoken":"Today's dossier is genuinely useful next time—the layout, the routes, the gate. Justification, though, attaches to a type of assignment, not to a room. The reasoning that, for this fixed vessel, neither a bunker nor an irradiation infrastructure was reasonably feasible says nothing about the next workpiece, and the decree requires the written justification for each type of assignment.","screen":"Justification attaches to the assignment type, not the room."},"clip":"B1.6-I04-standing"},{"id":"expert","text":"Our recognised expert can approve the hall once, and that approval then covers future jobs.","correct":false,"feedback":{"spoken":"The recognised expert does approve real things: procedures, risk analyses and acceptances. She does not justify a client's location. That duty sits with the client, in writing, for each type of assignment. Moving it to our expert would misplace the responsibility and still not make it standing.","screen":"Expert approves procedures and acceptances; the client justifies the location."},"clip":"B1.6-I04-expert"}],"placement":"Dossier and casting stay visible.","clip":"B1.6-I04-prompt"},"sequence":{"cues_before_interaction":["B1.6-S07-P1","B1.6-S07-P2"],"interaction_after_cue":"B1.6-S07-P2","interaction_id":"B1.6-I04","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S08","title":"The same reasoning with a sealed source","paragraphs":[{"cue":"B1.6-S08-P1","speaker":"Emilia","text":"Today's job used a portable X-ray set. Most of the decisions would have been the same with a gamma projector: the client's justifications, the twenty-four-hour information, the designation of the agent, the specific instruction for a changed task, stopping when the perimeter cannot be held. One thing changes with a sealed source, and you know what it is. A gamma projector holds a radioactive substance, so the security decree applies to it—including during temporary work on the client's site—with the delegate for radiological security, the duty of anyone who sees a malicious act to inform the operator or the ARB at once, and the police-and-Agency route for security incidents. An X-ray set has none of that, because it holds no radioactive substance.","screen_text":["Same: justifications · 24 h · designation · instruction · stop when unsafe","Added with a sealed source: the security decree — ARB · anyone reports a malicious act · police-and-Agency route"],"start_visual":"Switch the equipment image from the X-ray generator to the supplied gamma projector EQ-GAMMA-PROJECTOR; the unchanged protection labels stay; the security labels appear beside the projector.","beats":[{"at":"Today's job used a portable X-ray set","show":"EQ-XRAY-GENERATOR"},{"at":"A gamma projector holds a radioactive substance","show":"Switch to EQ-GAMMA-PROJECTOR"},{"at":"the security decree applies to it","show":"Security labels"},{"at":"An X-ray set has none of that","show":"X-ray image with 'no radioactive substance'"}],"equipment":["EQ-XRAY-GENERATOR","EQ-GAMMA-PROJECTOR"],"clip":"B1.6-S08-P1"},{"cue":"B1.6-S08-P2","speaker":"Emilia","text":"Here is the transfer in one decision. Imagine the same client and the same vessel, but the welds need gamma radiography and the projector will stay on Bram's site overnight in temporary storage. Today's protection reasoning stays exactly as it was; keep the roles in mind—the operator, its delegate for radiological security, and the agent.","screen_text":["Same client · same vessel · gamma projector stored overnight on site"],"start_visual":"Projector image with a 'temporary storage on the client's site' label; no storage arrangement depicted.","beats":[{"at":"stay on Bram's site overnight","show":"Label"}],"equipment":["EQ-GAMMA-PROJECTOR"],"clip":"B1.6-S08-P2"}],"interaction":{"id":"B1.6-R01","type":"single_choice","prompt_spoken_once":"Which additional question arises when this job uses a sealed radioactive source?","behaviour":"The prompt is spoken automatically exactly once when the activity opens; the narration lead-in never reads it. Manual 'Hear the question' replay. Each option has its own spoken and written feedback (evidence, then next step). Retry without replaying narration; keyboard equivalents (labelled radio controls, Check, Try again, Continue); no auto-advance; no colour-only cues; no timer. Feedback never invents a dose, cause, approval or successful contact.","situation_visible_text":"Gamma projector with a sealed source; overnight temporary storage on the client's site. Radiation protection reasoning unchanged.","options":[{"id":"security","text":"Which security responsibilities apply to this source — including on the client's site and overnight — and who is informed: the operator or its delegate for radiological security.","correct":true,"feedback":{"spoken":"Yes. A gamma projector holds a radioactive substance, so the security decree applies to it, including during temporary work on the client's site: the operator's delegate for radiological security, the duty of anyone who sees a malicious act to inform the operator or the ARB at once, and the police-and-Agency route for security incidents. All of today's radiation-protection decisions stay in force beside it. What the arrangements are is for the ARB and the operator, not for this lesson.","screen":"Security decree applies to the source; ARB and the reporting route; protection reasoning unchanged."},"clip":"B1.6-R01-security"},{"id":"agent_covers","text":"Whether Daniel's agent designation now also covers security, since he is the agent on site.","correct":false,"feedback":{"spoken":"Daniel's designation is real and it continues with a gamma projector: his checks on the equipment and the perimeter are the same. It is a radiation-protection designation by the company. Security responsibilities belong to the operator and its delegate for radiological security, an appointment the Agency approves; the agent does not automatically hold the ARB role.","screen":"Agent = radiation protection; ARB = separate appointment."},"clip":"B1.6-R01-agent_covers"},{"id":"skip_location","text":"Whether the client's location justification can be skipped, because the projector's container is shielded.","correct":false,"feedback":{"spoken":"The projector's shielded container is one of the protection means, and it matters for the dose outside it. It does not change the decree's rule that the client justifies the location in writing for each type of assignment—that applied to the X-ray job this morning and applies here too. The question that is new with a sealed source is security.","screen":"Shielding is a protection means; location justification still applies; security is the new question."},"clip":"B1.6-R01-skip_location"}],"replaces":"B1.6 S08 R01 (private reflection) — replaced one-for-one as one compact decision","placement":"Projector image stays visible.","clip":"B1.6-R01-prompt"},"sequence":{"cues_before_interaction":["B1.6-S08-P1","B1.6-S08-P2"],"interaction_after_cue":"B1.6-S08-P2","interaction_id":"B1.6-R01","post_interaction_cues":[],"rule":"Play cues_before_interaction in order; open the interaction immediately after interaction_after_cue (it speaks its prompt once); post_interaction_cues play only when their condition is met; nothing in post_interaction_cues is spoken before the interaction."}},{"id":"S09","title":"What the module has given you","paragraphs":[{"cue":"B1.6-S09-P1","speaker":"Emilia","text":"That was one Thursday. Look back at what you used. From the opening lesson, the three questions, and the rule that the client justifies technique and location in writing while we check and refuse when a justification does not hold—with the decree's twenty-four hours for the written job information. From the lesson on people, the designation of the agent from our own trained staff, and the difference between a check record and an approval. From the licence lesson, the location tiers: movable workpieces within one cubic metre and under 500 kilograms always in a bunker; larger or heavier ones preferably in a bunker, then an irradiation infrastructure on the client's site, and only when neither is reasonably feasible another place, after a joint risk analysis. From the external-worker lesson, that Clara's experience does not make her our agent and that her instruction covers the task it was given for. And from the lesson on things going wrong, the stop-and-report duty, the three people who hear about it, the verification before anyone resumes, the company's route to the Agency when a stop cannot be resolved, and the discipline of saying what is not yet known.","screen_text":["Three questions · designation · location tiers · external worker · stop-and-report"],"start_visual":"Connected job story recap on the planner: each lesson's element pulses at its phrase (the request, the planning line, the location dossier, Clara's instruction record, the held drawing).","beats":[{"at":"From the opening lesson","show":"Request thumbnail"},{"at":"From the lesson on people","show":"Planning line"},{"at":"From the licence lesson","show":"Location dossier"},{"at":"From the external-worker lesson","show":"Clara's instruction record"},{"at":"from the lesson on things going wrong","show":"Held drawing and record"}],"clip":"B1.6-S09-P1"},{"cue":"B1.6-S09-P2","speaker":"Emilia","text":"A good decision is neither a permanent yes nor a permanent no. It connects a particular conclusion to particular evidence and to the people who hold the next responsibility. Finishing this module does not designate you as an agent, authorise an installation or replace the practical experience, the workplace instruction and the medical surveillance that real work requires—you know by now exactly which documents would show those things. The rest of the course turns to the science behind the decisions: what radiation is, how it interacts with matter and with people, and how we measure it. Keep one question with you into those lessons: what does this information actually allow me to conclude? Thank you for working through this module with me.","screen_text":["Finishing this module does not designate, authorise or replace practical experience, instruction or medical surveillance","Next: the science behind the decisions"],"start_visual":"Emilia to camera; calm route to the next subject (stop 2 of the course route).","beats":[{"at":"Finishing this module does not designate you","show":"Boundary label"},{"at":"The rest of the course turns to the science","show":"Course route: stop 2 highlighted"}],"clip":"B1.6-S09-P2"}],"sequence":{"cues_before_interaction":["B1.6-S09-P1","B1.6-S09-P2"],"interaction_after_cue":null,"interaction_id":null,"post_interaction_cues":[]}}]}]};
